Ceviri.ekle("hi","olay",{
"OLAYLAR_EK5:1538-08-03:0":{"b": ["अदन का क़ब्ज़ा और यमन तट का विलय", "e7d46d8f"], "d": ["हिंद अभियान के लिए स्वेज़ से चला बेड़ा, लाल सागर को सुरक्षित किए बिना महासागर में नहीं निकला जा सकने के कारण पहले यमन तट की ओर मुड़ा। हादिम सुलेमान पाशा 3 अगस्त 1538 को अदन बंदरगाह में दाख़िल हुए; पुर्तगालियों की ओर झुकाव रखने वाले ताहिरी शासक आमिर बिन दाऊद कप्तान के द्वार पर लाए जाकर मृत्युदंड पाए और नगर में 500 की चौकी छोड़ी गई। उसी अभियान के दौरान मोख़ा और जलडमरूमध्य पर हावी केमारान तथा फ़रासान द्वीप भी लिए गए और यमन बेयलरबेयिलिक की नींव पड़ी। इस तरह ऑटोमन राज्य पहली बार बाबुल-मंदब के उत्तरी तट के पूरे भाग का स्वामी हुआ; सनआ और भीतरी क्षेत्रों को नौ वर्ष और प्रतीक्षा करनी थी।", "495e1991"]},
"OLAYLAR_EK5:1538-09-01:0":{"b": ["बोग़दान अभियान और बुजाक (बेंदेर) क्षेत्र का विलय", "90a88a56"], "d": ["ऑटोमन दायित्व पूरे न करने वाले बोग़दान वोइवोडा पेत्रू रारेश पर किए अभियान में सुचेवा ले लिया गया, यास नगर क्रीमिया ख़ान साहिब गिराय द्वारा लूटा गया। पदीशाह ने चेकिर्गे स्तेफ़ान को वोइवोडा बनाया और बेंदेर के साथ बुजाक (दक्षिणी बेसाराबिया) क्षेत्र को सीधे ऑटोमन भूमि में मिला लिया। यह विलय काला सागर के उत्तर-पश्चिमी तटों को ऑटोमन का आंतरिक सागर बनाने वाली कड़ियों में से एक बना। बोग़दान पहले से ऑटोमन का अधीन वोइवोडेशिप था; इस अभियान ने भूमि किसी विदेशी राज्य से नहीं ली, केवल बेंदेर और बुजाक का आंतरिक प्रशासन वोइवोडा से लेकर सीधे पदीशाह से जोड़ा; वोइवोडेशिप का शेष भाग अधीन दर्जा बनाए रहा। यही ढाँचा 1484 में किली और अक़किरमान में, 1713 में होतिन में भी दोहराया जाएगा: सीमा के दुर्ग सीधे, भीतरी भूमि अधीन।", "96376de1"]},
"OLAYLAR_EK5:1540-11-01:0":{"b": ["अनाबोलू (नाफ़्प्लियो) का संधि से लिया जाना", "104d0937"], "d": ["प्रेवेज़ा के बाद तीन वर्ष चला वेनिस युद्ध, गणराज्य के मोरिया के अंतिम दो दुर्ग छोड़ने पर सहमत होने से समाप्त हुआ। घेराबंदी से न लिए जा सके अनाबोलू और बेनेफ़्शे, तीन लाख डुकाट की युद्ध-क्षतिपूर्ति के साथ मेज़ पर ऑटोमन को सौंपे गए। मोरिया प्रायद्वीप इस तरह एक भी वेनिस पदचिह्न के बिना एकीकृत हो गया।", "4a26ee03"]},
"OLAYLAR_EK5:1543-01-01:0":{"b": ["सेगेद का ऑटोमन प्रशासन में आना और सेगेद लिवा का गठन", "019aa000"], "d": ["बुदिन में ऑटोमन प्रशासन के 1541 में पूरी तरह स्थापित होने के बाद सेगेद के प्रमुखों ने फ़र्डिनेंड प्रथम के आधिपत्य को अपनाकर सशस्त्र रक्षा की तैयारी की। बुदिन बेयलरबेयी कुचुक बाली पाशा ने 1543 के आरंभ में नगर के प्रशासकों को अपने पास बुलवाकर विश्वासघात के आधार पर मृत्युदंड दिलवाया और फिर नगर को अपने हाथ में लेने के लिए टुकड़ी भेजी। इसी बीच सेगेद लिवा गठित होकर पहले संजक बेय के पद पर बाली पाशा के पुत्र दरवेश बेय को नियुक्त किया गया; लिवा आरंभ में डैन्यूब-तिसा के बीच तक फैला था।", "8293a839"]},
"OLAYLAR_EK5:1543-07-21:0":{"b": ["वालपो, शिक्लोश और पेचुय की विजय", "2ca030a3"], "d": ["बुदिन के विलय के दो वर्ष बाद निकले हंगरी अभियान का पहला लक्ष्य नए प्रांत के द्रावा और डैन्यूब के बीच के दक्षिणी पार्श्व को सुरक्षित करना था। वालपो और शिक्लोश दुर्ग लिए जाने के बाद बारान्या का केंद्र पेचुय समर्पित हुआ। नगर ऑटोमन हंगरी का सबसे घना और सबसे अधिक निर्माण पाने वाला केंद्र बनने वाला था, इतिहासकार इब्राहीम पेचुयलू ने अपना नाम यहीं से पाया।", "aacf43d3"]},
"OLAYLAR_EK5:1543-08-10:0":{"b": ["एस्तेरगोन और इस्तोलनी बेलग्रेड की विजय", "efca9e05"], "d": ["कानूनी के स्वयं निकले हंगरी अभियान में, ढाई सप्ताह की घेराबंदी के बाद हंगरी राज्य का धार्मिक केंद्र और आर्कबिशप नगर एस्तेरगोन ऑटोमन प्रशासन में आया। इसके बाद हंगरी राजाओं के राज्याभिषेक नगर इस्तोलनी बेलग्रेड को भी लेकर बुदिन प्रांत की रक्षा-पट्टी पूर्ण की गई। एस्तेरगोन 1595 तक डैन्यूब रेखा के कुंजी दुर्ग के रूप में ऑटोमन के हाथ में रहेगा।", "93577806"]},
"OLAYLAR_EK5:1544-09-01:0":{"b": ["बुदिन की उत्तरी और पश्चिमी रक्षा पट्टी: वाच, हातवान और शिमोन्तोर्ना", "733ee5ce"], "d": ["एस्तेरगोन और इस्तोलनी बेलग्रेड पर अधिकार के बाद बुदिन बेयलरबेयी ने राजधानी को घेरने वाली दुर्ग-शृंखला को पूर्ण करने के लिए पदीशाह के अभियान के बिना कार्रवाई की। डैन्यूब मोड़ का वाच, अल्फ़ोल्द का द्वार हातवान और शियो रेखा का शिमोन्तोर्ना एक-एक करके अपने हाथ में लिए गए। इस शांत वर्ष की उपलब्धियों ने बुदिन को सीमांत नगर से निकालकर एक सौ चालीस वर्ष टिकने वाले प्रांत-केंद्र में बदल दिया।", "0ca98fa3"]},
"OLAYLAR_EK5:1545-12-26:0":{"b": ["बसरा का विलय और बसरा खाड़ी तक पहुँच", "02f87c11"], "d": ["बग़दाद की विजय (1534) के समय बसरा शासक राशिद बिन मग़ामिस ने कानूनी के प्रति आज्ञाकारिता जताई थी, 1538 में नगर की कुंजियाँ भेजी थीं। उनकी जगह आए शेख़ याह्या के ऑटोमनों के विरुद्ध मोर्चा लेने पर बग़दाद बेयलरबेयी अयास पाशा स्थल से, मूसल संजक बेय 120 जहाज़ों से फ़रात होकर बढ़े; अयास पाशा 26 दिसंबर 1545 को बसरा में दाख़िल हुए और नगर बेयलरबेयिलिक का केंद्र बना। शत्तुल-अरब के मुहाने का यह बंदरगाह, पुर्तगाल के होरमुज़ से नियंत्रित खाड़ी में ऑटोमन के खुलने का द्वार था; 1555 की आमासिया संधि से ईरान ने भी इस स्थिति को मान लिया।", "8905782c"]},
"OLAYLAR_EK5:1547-01-01:0":{"b": ["सनआ और यमन के भीतरी भाग की विजय", "d31ded85"], "d": ["ताइज़ के बाद सनआ भी लिया जाकर पूरा देश बेयलरबेयिलिक से जोड़ा गया। किंतु दुर्गम भूगोल और मज़हबी भेद के कारण यह आधिपत्य कभी सहज न रहा; यमन ऑटोमन के लिए निरंतर सैनिक निगलने वाला मोर्चा बन गया।", "66968d6d"]},
"OLAYLAR_EK5:1547-02-01:0":{"b": ["ताइज़ की विजय", "d4509df9"], "d": ["नौ वर्ष पहले तट पट्टी से संतुष्ट रहे यमन में ज़ैदी इमामों के पर्वतीय भीतरी क्षेत्र में बढ़ती शक्ति पर ओज़देमिर पाशा की सेनाओं ने पठार पर चढ़कर ताइज़ को अपने क़ब्ज़े में लिया।", "46b811eb"]},
"OLAYLAR_EK5:1547-06-19:0":{"b": ["इस्तांबुल संधि — हैब्सबर्गों के साथ पाँच वर्षीय शांति", "41f81773"], "d": ["ऑटोमन और हैब्सबर्गों के बीच पाँच वर्ष की अवधि वाली शांति हस्ताक्षरित हुई; फ़र्डिनेंड ने अपने हाथ की हंगरी भूमि के लिए प्रतिवर्ष 30.000 डुकाट देना स्वीकार किया। संधि ने हंगरी की तीन भागों में बँटी वास्तविक स्थिति को विधिक रूप से पंजीकृत किया। पश्चिमी मोर्चे के इस तरह सुरक्षित हो जाने ने कानूनी को ईरान पर नए अभियान आयोजित करने की गुंजाइश दी।", "36cfadaa"]},
"OLAYLAR_EK5:1548-07-27:0":{"b": ["दूसरा ईरान अभियान और तबरेज़ का फिर लिया जाना", "e82365df"], "d": ["शाह तहमास्प से विद्रोह करके इस्तांबुल की शरण में आए भाई एल्क़ास मिर्ज़ा के उकसाने पर निकले अभियान में सेना दूसरी बार तबरेज़ में दाख़िल हुई। सफ़वियों के फिर खुले युद्ध में न उतरकर भूमि जलाते हुए हटने के कारण नगर में केवल कुछ सप्ताह ठहरा जा सका। अभियान ने तबरेज़ के थामे न जा सकने को निश्चित किया और ऑटोमन रणनीति को स्थायी सीमा रेखा बनाने, यानी वान को सुदृढ़ करने की ओर मोड़ा।", "bb2a7ceb"]},
"OLAYLAR_EK5:1548-08-24:0":{"b": ["वान की विजय और पूर्वी सीमा का स्थिर होना", "fc8f930b"], "d": ["तबरेज़ से लौटते समय घेरा गया वान दुर्ग, झील के पूर्वी तट की चट्टान पर उठी अपनी स्थिति से क्षेत्र की निर्विवाद कुंजी था और संक्षिप्त घेराबंदी के बाद समर्पित हुआ। नगर को तुरंत बेयलरबेयिलिक का केंद्र बनाया गया; एरचिश, अदिलजेवाज़ और हक्कारी संजक इससे जोड़े गए। तबरेज़ के विपरीत वान थामा गया और चार शताब्दी तक ऑटोमन के पूर्व की सबसे आगे की स्थायी चौकी बना रहा।", "3ca861b4"]},
"OLAYLAR_EK5:1550-01-01:0":{"b": ["लहसा और क़तीफ़ का विलय — खाड़ी का अरब तट", "f6701e60"], "d": ["बसरा पर अधिकार के बाद खाड़ी के पश्चिमी तट पर पुर्तगाल की अग्रिम चौकी बन चुका क़तीफ़ लिया गया और भीतरी लहसा नख़लिस्तानों के साथ नया बेयलरबेयिलिक स्थापित हुआ। बहरीन और होरमुज़ की ओर के अभियानों का प्रस्थान-बिंदु यही था। इस तरह ऑटोमन राज्य अरब प्रायद्वीप के लाल सागर और बसरा खाड़ी दोनों तटों पर एक साथ प्रभावी हुआ।", "240c0b43"]},
"OLAYLAR_EK5:1550-01-01:1":{"b": ["शेहरिज़ोर का हाथ से निकलना — अर्देलान बेय सुहराब सफ़वियों की ओर झुका", "5600efc9"], "d": ["इराक़ैन अभियान के दौरान (1535) ऑटोमन प्रशासन को मान चुका शेहरिज़ोर क्षेत्र ज़ल्म दुर्ग में रहने वाले अर्देलान अमीर बीगे बेय के शासन में था। बीगे बेय की 1550 में मृत्यु पर ज़ल्म दुर्ग लेकर बेयलिक पर क़ाबिज़ हुए भाई सुहराब सफ़वियों की ओर झुककर ऑटोमन की आज्ञाकारिता से अलग हो गए; शेहरिज़ोर क्षेत्र इस तरह ऑटोमन प्रभाव से निकल गया। क्षेत्र केवल नख़चिवान अभियान के दौरान, 1554 में, ज़ल्म दुर्ग के घेरे जाकर लिए जाने से वापस पाया गया।", "62ddad8a"]},
"OLAYLAR_EK5:1551-01-01:0":{"b": ["अर्दाहान और चिल्दिर घाटी का लिया जाना", "14c9eb76"], "d": ["सफ़वियों से चल रहे युद्ध के दौरान एरज़ुरुम बेयलरबेयी ने जॉर्जियाई अताबेगों की कुर मोड़ की भूमि की ओर बढ़कर अर्दाहान और चिल्दिर के आसपास को ऑटोमन प्रशासन से जोड़ा। कार्स-अर्दाहान रेखा इस तरह एकीकृत हुई और उत्तर-पूर्व में जॉर्जिया की ओर खुलने वाले पठार नियंत्रण में आ गए। क्षेत्र की निश्चित प्रशासनिक व्यवस्था सत्ताईस वर्ष बाद स्थापित होने वाले चिल्दिर प्रांत से पूर्ण होगी।", "2f8d92cc"]},
"OLAYLAR_EK5:1551-09-07:0":{"b": ["सोकोल्लू मेहमेद पाशा ने डैन्यूब पार की — ट्रांसिल्वेनिया युद्ध का आरंभ", "38fde931"], "d": ["ट्रांसिल्वेनिया राजा बाल यानोश ज़िग्मोंड के संरक्षक भिक्षु मार्तिनुज़्ज़ी के पैदा किए उलझावों और ट्रांसिल्वेनिया के बनात दुर्ग फ़र्डिनेंड को छोड़ देने पर नया अभियान आवश्यक माना गया; कमान रुमेली बेयलरबेयी सोकोल्लू मेहमेद पाशा को दी गई। सेना ने मार्तिनुज़्ज़ी के टालमटोल प्रयासों के बावजूद डैन्यूब पार की, बेचे, बेचकेरेक, चानाद और लिप्पा ले लिए; किंतु तेमेश्वार घेराबंदी 16 नवंबर को ठंड के कारण उठा ली गई। इस तरह हंगरी में नया ऑटोमन-हैब्सबर्ग युद्ध खुल गया।", "85071c5e"]},
"OLAYLAR_EK5:1551-11-06:0":{"b": ["लिपोवा (लिप्पा) नगर कास्ताल्दो की ऑस्ट्रियाई सेना के हाथ गया — दुर्ग 5 दिसंबर को समर्पित हुआ", "a0e1ff0d"], "d": ["सोकोल्लू मेहमेद पाशा द्वारा अक्तूबर 1551 में लिए गए लिपोवा को जनरल कास्ताल्दो की सेना ने 4 नवंबर को घेरा; दो दिन बाद नगर ऑस्ट्रियाइयों के हाथ गया। उलामा पाशा ने 5.000 की चौकी के साथ दुर्ग को नौ दिन और थामा और 5 दिसंबर 1551 को समझौते से निकले। तेमेश्वार के 1552 में गिरने तक लिपोवा हैब्सबर्ग के हाथ में रहा।", "22c85b1c"]},
"OLAYLAR_EK5:1552-07-27:0":{"b": ["तेमेश्वार से भेजी टुकड़ियों का दक्षिणी बनात की पालंकाओं को थामना — वेर्शेच, हराम, केवे", "edca0921"], "d": ["तेमेश्वार के ऑटोमन सेना को समर्पित होने के बाद घेराबंदी सेना से अलग हुई टुकड़ियाँ बनात की छोटी पालंकाओं की ओर मुड़ीं; बांलाकी के वर्णन के अनुसार वेर्शेच, फ़ाचेत, मेहादिया, चाकोवार, हरामवार और केवे पालंकाएँ इन बलों ने थामीं। इस तरह डैन्यूब तट का हराम भी ऑटोमन हाथ में आ गया।", "a5906d21"]},
"OLAYLAR_EK5:1552-09-04:0":{"b": ["सोलनोक की विजय और एग्री घेराबंदी की विफलता", "a7156e8f"], "d": ["तेमेश्वार पर अधिकार के बाद मिली दो ऑटोमन सेनाओं ने तिसा पर स्थित सोलनोक को किराये के रक्षकों के दुर्ग छोड़ने से लगभग बिना संघर्ष ले लिया। इसके बाद घेरा गया एग्री दुर्ग इश्तवान दोबो की कमान की दो हज़ार की चौकी के अड़तीस दिन के प्रतिरोध के सामने न लिया जा सका और सेना सर्दी आने पर हट गई। एक ही अभियान में एक दुर्ग का सहज गिरना और दूसरे का टिकना हंगरी में सीमा के अब ऑटोमन के पक्ष में अपने आप आगे न बढ़ने का पहला स्पष्ट संकेत था।", "354ed31f"]},
"OLAYLAR_EK5:1553-02-01:0":{"b": ["ऑटोमन-फ़्रांसीसी गठबंधन — फ़्रांसीसी बेड़े का ऑटोमन के आदेश में आना", "a8e01b22"], "d": ["1 फ़रवरी 1553 की संधि से फ़्रांस का बेड़ा ऑटोमन बेड़े के आदेश में दिया गया; स्पेन के विरुद्ध पश्चिमी भूमध्यसागर में संयुक्त कार्रवाई की परिकल्पना की गई। संधि के बाद तुर्गुत रेइस 15 जून 1553 को पैंतालीस गैली के साथ फ़्रांस को समर्थन देने अभियान पर निकले। यह 1536 की कैपिट्यूलेशनों के व्यापारिक आधार को सैन्य सहयोग तक ले जाने वाली पहली औपचारिक गठबंधन संधि थी।", "bfa2fc2d"]},
"OLAYLAR_EK5:1553-10-05:0":{"b": ["शहज़ादे मुस्तफ़ा का कोन्या एरेग्ली में मृत्युदंड", "dec36858"], "d": ["नख़चिवान अभियान के लिए जुटी सेना में सम्मिलित होने के लिए पिता के शिविर में आए शहज़ादे मुस्तफ़ा, हुज़ूर में पहुँचने के समय जल्लादों से मिले और गला घोंटकर मारे गए। सेना में बड़ा प्रेम पाने वाले उत्तराधिकारी-उम्मीदवार के वध ने येनिचेरियों में गहरा आक्रोश उत्पन्न किया, रुस्तम पाशा को वज़ीर-ए आज़मी से हटाया गया। घटना ऑटोमन शहज़ादा राजनीति की सबसे विवादित दरारों में से एक के रूप में साहित्य और लोक-स्मृति में दर्ज हुई।", "ce2742ae"]},
"OLAYLAR_EK5:1555-01-01:0":{"b": ["इब्रिम और नूबिया सीमा का दक्षिण खिसकना", "c57d5d77"], "d": ["मिस्र बेयलरबेयिलिक की दक्षिणी सीमा, नील पर चट्टानी अंतरीप पर खड़े इब्रिम दुर्ग के ओज़देमिर बेय के हाथों सुदृढ़ किए जाने और निचले नूबिया के ऑटोमन मिस्र से पूरी तरह जुड़ने से दूसरे प्रपात के पार खिसकी। (इब्रिम में ऑटोमन प्रशासनिक संगठन मिस्र की विजय के बाद स्थापित हुआ था; मानचित्र में इब्रिम 1517 से ऑटोमन दिखाया जाता है। यह वर्ष अनुमानित है, स्रोत वर्ष नहीं देता।) दुर्ग नूबिया से आने वाले आक्रमणों के विरुद्ध बाँध होने के साथ सेन्नार की ओर जाने वाले सोने और ग़ुलाम मार्ग का नियंत्रण बिंदु भी था। यहाँ बसाई गई बोस्नियाई रक्षक टुकड़ी इतनी स्थायी रही कि उसके वंशज तीन सौ वर्ष बाद भी दुर्ग में थे। स्रोत इब्रिम के ऑटोमन प्रशासन में आने के समय पर दो अलग वृत्तांत देते हैं: TDV का सूडान मद निचले नूबिया के ऑटोमन मिस्र से जुड़ने को 16वीं शताब्दी के मध्य में ओज़देमिर पाशा के अभियान से जोड़ता है, जबकि नूबिया मद हल्फ़ा घाटी तक के क्षेत्र और इब्रिम के प्रशासनिक संगठन के 1517 की विजय के तुरंत बाद स्थापित होने की बात लिखता है। इब्रिम संजक 26 जुलाई 1573 को हबेश प्रांत से जोड़ा गया।", "cd2c7ae9"]},
"OLAYLAR_EK5:1555-09-27:0":{"b": ["बिजाया (बूजी) का स्पेनियों से लिया जाना", "49691cda"], "d": ["तैंतालीस वर्ष से स्पेन के हाथ में रहे और अल्जीरिया तथा कोन्स्तांतीन के बीच के तट को दो में बाँटने वाला बिजाया, स्थल और समुद्र से घेरे जाने के बाद समर्पित हुआ। दुर्ग के गिरने से अल्जीरिया ओजाक का तट वहरान तक निर्बाध हो गया। स्पेन में इस हानि ने इतना भारी आक्रोश जगाया कि दुर्ग सौंपने वाले सेनानायक आलोन्सो दे पेराल्ता को अपने देश में मृत्युदंड दिया गया।", "a030d882"]},
"OLAYLAR_EK5:1559-01-01:0":{"b": ["ज़ेयला का हबेश प्रांत से जुड़ना", "7bbf369a"], "d": ["हबेश प्रांत के दक्षिणी छोर पर, अदन खाड़ी के अफ़्रीकी तट का ज़ेयला बंदरगाह ऑटोमन प्रशासन से जोड़ा गया। अदाल सल्तनत का समुद्र की ओर खुलने वाला द्वार यह नगर बाबुल-मंदब के बाहर जाने वाले जहाज़ों के लिए अंतिम रसद-बिंदु था। ज़ेयला के जुड़ने से ऑटोमन राज्य की अफ़्रीका में सीमा अपने सबसे दक्षिणी बिंदु तक पहुँची।", "fe4597b7"]},
"OLAYLAR_EK5:1559-05-30:0":{"b": ["कोन्या शहज़ादों का युद्ध", "1c8de387"], "d": ["गद्दी संघर्ष में उतरे शहज़ादे बायज़ीद लगभग 30.000 की सेना के साथ कोन्या के सामने आए और दो दिन चली लड़ाई में भाई शहज़ादे सेलिम से पराजित हुए। पराजित बायज़ीद आमासिया होकर ईरान में शाह तहमास्प की शरण में गए। युद्ध ने कानूनी के अंतिम वर्षों में सल्तनत उत्तराधिकार संकट को विदेश नीति की समस्या में बदल दिया।", "d466cfc5"]},
"OLAYLAR_EK5:1560-05-14:0":{"b": ["जेरबा नौसैनिक विजय", "c7b905c1"], "d": ["पियाले पाशा की कमान के ऑटोमन बेड़े ने त्रिपोली को वापस लेने के लिए जुटे स्पेनी-जेनोवी-माल्टा संयुक्त बेड़े को जेरबा के सामने दो भागों में बँटने की चाल से बिखेर दिया। मित्र राज्यों ने अपने बेड़े का बड़ा भाग खोया, द्वीप का दुर्ग भी शीघ्र गिर गया। जेरबा, प्रेवेज़ा के बाद ऑटोमन की भूमध्यसागर में श्रेष्ठता को दृढ़ करने वाली दूसरी बड़ी नौसैनिक विजय मानी जाती है।", "e987b794"]},
"OLAYLAR_EK5:1562-07-23:0":{"b": ["शहज़ादे बायज़ीद का क़ज़्वीन में मृत्युदंड", "a759de14"], "d": ["ईरान में शरण लेने वाले शहज़ादे बायज़ीद लंबी सौदेबाज़ी के परिणामस्वरूप शाह तहमास्प द्वारा ऑटोमन प्रतिनिधिमंडल को सौंपे गए और चार पुत्रों के साथ गला घोंटकर मारे गए। सौंपे जाने के बदले सफ़वियों ने महत्वपूर्ण भौतिक रियायतें और सीमा गारंटी पाई। इस वध से सेलिम द्वितीय के गद्दी पर बैठने के सामने की अंतिम बाधा हटी और आमासिया संधि की शांति-व्यवस्था सुरक्षित रही।", "cf625eb3"]},
"OLAYLAR_EK5:1566-04-14:0":{"b": ["साकिज़ का जेनोवियों से लिया जाना", "a4559b96"], "d": ["दो सौ वर्ष से जेनोवा के जुस्तिनियानी परिवार की व्यापारिक बस्ती के रूप में चलाया जाने वाला और ऑटोमन को कर देने वाला साकिज़, कर में चूक और शत्रु जहाज़ों को बंदरगाह देने के आधार पर पियाले पाशा द्वारा एक गोली चले बिना अपने हाथ में लिया गया। साकिज़ और इप्सारा के साथ एजियन के पूर्वी तट पर जेनोवा की अंतिम उपस्थिति का भी सफ़ाया हुआ। साकिज़वासियों के मस्तकी उत्पादन और विशेषाधिकार सुरक्षित रखकर द्वीप को जज़ायर-ए बहर-ए सफ़ीद प्रांत से जोड़ा गया।", "a5ec4417"]},
"OLAYLAR_EK5:1566-04-15:0":{"b": ["नक्सोस डची में लातिन प्रभुत्व का अंत", "f8b2620a"], "d": ["1207 से चली आ रही लातिन नक्सोस डची के अंतिम ड्यूक जाकोमो क्रिस्पो को प्रजा की शिकायतों पर इस्तांबुल में क़ैद किया गया। 1566 में द्वीप उस्मानी नियंत्रण में ले लिए गए और डची योसेफ़ नासी को दे दी गई; संजाक के रूप में सीधा प्रशासन 1579 में नासी की मृत्यु के बाद का है। कुछ छोटे द्वीप कुछ समय और ख़िराज देने वाले गोज़ादिनी परिवार के हाथ में रहे, जबकि तीनोस वेनिस के पास रहा।", "7e0a1a87"]},
"OLAYLAR_EK5:1567-04-01:0":{"b": ["यमन विद्रोह और कोजा सिनान पाशा का यमन अभियान", "c8218d8e"], "d": ["ज़ैदी इमाम मुतह्हर ने ज़बरदस्ती कर वसूले जाने के आधार पर विद्रोह करके ऑटोमन प्रशासन को यमन के बड़े भाग से उखाड़ फेंका। इस्तांबुल से भेजे गए कोजा सिनान पाशा ने 1568-1570 के बीच चलाए अभियान से कौकबान को लंबी घेराबंदी के बाद लेकर क्षेत्र में ऑटोमन आधिपत्य फिर स्थापित किया। अभियान लाल सागर के दक्षिणी द्वार और हिंद महासागर व्यापार मार्ग के नियंत्रण को बचाने की दृष्टि से जीवनदायी महत्व का था।", "d4771f85"]},
"OLAYLAR_EK5:1567-10-01:0":{"b": ["आचेह सल्तनत से रक्षा गठबंधन और हिंद महासागर सहायता", "8e835f24"], "d": ["पुर्तगाली आक्रमणों के सामने कानूनी से सहायता माँगने वाले आचेह के दूतों ने, पदीशाह के ज़िगेतवार में निधन पर, अपनी निष्ठा सेलिम द्वितीय को अर्पित की और उनसे रक्षा संधि हस्ताक्षरित हुई। पदीशाह ने इस्कंदरिया से तोपें, बंदूकें, बारूद और उस्ताद भेजे जाने का आदेश दिया; हिंद समुद्रों में भेजे जाने के लिए सत्रह युद्धपोत तैयार किए गए। यमन विद्रोह के बढ़ने ने बेड़े के रवाना होने को रोका, किंतु आचेह पहुँचे ऑटोमन तोपची और उस्तादों ने क्षेत्र में स्थायी छाप छोड़ी।", "65c41562"]},
"OLAYLAR_EK5:1570-07-02:0":{"b": ["साइप्रस अवतरण: लिमासोल का लिया जाना", "9074ccc9"], "d": ["द्वीप पर उतरी ऑटोमन सेना ने अधिक प्रतिरोध के बिना लिमासोल को अपने हाथ में लिया और अगले दिन लार्नाका की ओर मुड़ी। स्थानीय जनता के वेनिस प्रशासन से असंतुष्ट होने और ऑटोमन सेनाओं की सहायता करने के कारण लार्नाका में भी गंभीर प्रतिरोध नहीं मिला; तुज़ला घाट सैनिक और सामग्री उतारने का अड्डा बनाया गया। वेनिस ने रक्षा को लेफ़कोशा और मग़ुसा में जुटाया था; पाफ़ोस के वाली ने लेफ़कोशा के गिरने के बाद ही सेरदार के प्रति आज्ञाकारिता जताई।", "6bbd2fee"]},
"OLAYLAR_EK5:1570-09-09:0":{"b": ["लेफ़कोशा की विजय", "413d866b"], "d": ["25 जुलाई 1570 को आरंभ हुई और पैंतालीस दिन चली घेराबंदी के बाद साइप्रस की वेनिस-शासित राजधानी लेफ़कोशा ऑटोमन सेना के सामने समर्पित हुई। द्वीप के केंद्र के गिरने ने वेनिस के प्रतिरोध को मग़ुसा दुर्ग में समेट दिया। विजय ने पश्चिम में बड़ी गूँज उठाई और पोप के नेतृत्व में पवित्र गठबंधन बेड़े की स्थापना की ओर जाती प्रक्रिया को तेज़ किया।", "1ef832d4"]},
"OLAYLAR_EK5:1570-09-17:0":{"b": ["गिर्ने (कीरेनिया) का समर्पण — साइप्रस का उत्तरी तट", "39fdeea5"], "d": ["9 सितंबर को लेफ़कोशा के क़त्लेआम के साथ हुए पतन ने साइप्रस के उत्तर का प्रतिरोध तोड़ दिया। बेशपरमक पर्वतों के पीछे का गिर्ने दुर्ग, राजधानी का हाल जानकर आठ दिन बाद शर्तबद्ध समर्पित हुआ और उसकी चौकी को द्वीप से निकलने की अनुमति देकर भेजा गया। द्वीप पर वेनिस ध्वज केवल मग़ुसा में बचा; वह ग्यारह माह और टिकने वाला था।", "ecf762c9"]},
"OLAYLAR_EK5:1572-06-01:0":{"b": ["इनेबख़्ती के बाद बेड़े का पुनर्निर्माण", "db51fe44"], "d": ["इनेबख़्ती की पराजय के बाद कप्तान-ए दरया बनाए गए क़िलिच अली पाशा का पहला कार्य भारी हानि उठाए बेड़े को फिर बनाना रहा; जहाज़-घाट 1571-1572 की सर्दी भर निरंतर चलते रहे। जून 1572 में लगभग 250 गैली और 300 स्वयंसेवी रेइस गैलियों का नया बेड़ा भूमध्यसागर में उतरा। यह तेज़ वापसी दर्शाती है कि इनेबख़्ती ऑटोमन नौसैनिक शक्ति को स्थायी रूप से नहीं तोड़ सकी।", "324f2d99"]},
"OLAYLAR_EK5:1573-03-07:0":{"b": ["वेनिस से इस्तांबुल संधि — साइप्रस की मान्यता", "4d08ef50"], "d": ["पवित्र गठबंधन के बिखरने पर अकेले पड़े वेनिस ने ऑटोमन से अलग शांति करके साइप्रस के ऑटोमन का होने को औपचारिक रूप से माना और युद्ध क्षतिपूर्ति देना स्वीकार किया। संधि ने स्पष्ट कर दिया कि इनेबख़्ती की विजय ने ईसाई जगत को कोई राजनीतिक लाभ नहीं दिया। वेनिस इसके बाद सत्तर वर्ष तक ऑटोमन से सीधे युद्ध में उतरने से बचता रहा।", "de6151ba"]},
"OLAYLAR_EK5:1574-12-13:0":{"b": ["सेलिम द्वितीय का निधन", "c289f5ee"], "d": ["सेलिम द्वितीय गिरने के बाद लगभग दो माह दीवान में न आ सके और चल बसे। उनकी मृत्यु मनीसा के बड़े पुत्र मुराद के इस्तांबुल आने तक बारह दिन सराय में गुप्त रखी गई। मृत्यु-तिथि पर स्रोत अलग होते हैं: सेलानिकी 15 दिसंबर कहता है; गेरलाख़, मेहमेद बिन मेहमेद और जेनाबी 13 दिसंबर कहते हैं।", "e9e279ab"]},
"OLAYLAR_EK5:1574-12-22:0":{"b": ["सेलिम द्वितीय की मृत्यु की घोषणा और मुराद तृतीय का राज्यारोहण", "84334d70"], "d": ["सेलिम द्वितीय की मृत्यु और मनीसा से बुलाए गए मुराद तृतीय के राज्यारोहण की 22 दिसंबर 1574 को औपचारिक घोषणा की गई। नए पदीशाह इक्कीस वर्ष गद्दी पर रहेंगे और उनका शासन पूर्व में लंबे ईरान युद्धों, पश्चिम में लंबे युद्ध की पूर्वसंध्या और भीतर अक़चे के अवमूल्यन के लिए याद किया जाएगा। सोकोल्लू मेहमेद पाशा की 1579 की मृत्यु तक राज्य प्रशासन में पुरानी व्यवस्था चलती रही।", "3e1ec091"]},
"OLAYLAR_EK5:1578-08-04:0":{"b": ["वादिस्सेयल (क़सरुल-कबीर) युद्ध — ऑटोमन समर्थित अब्दुलमलिक ने पुर्तगाली सेना को नष्ट किया", "21280dac"], "d": ["ऑटोमन समर्थन से मोरक्को की गद्दी पर बैठे अब्दुलमलिक ने पुर्तगाल के राजा सेबास्तियाओ की बड़ी सेना को वादिस्सेयल में नष्ट किया; युद्ध में तीन शासकों के एक साथ मरने से पश्चिमी स्रोतों में 'तीन राजाओं का युद्ध' कहलाता है। पुर्तगाल की सैन्य शक्ति ढह गई और देश शीघ्र ही स्पेन के हाथ आ गया। अब्दुलमलिक भी युद्ध में मारे गए; उनके उत्तराधिकारी बने भाई अहमद अल-मंसूर ने विजय का समाचार प्रतिनिधिमंडल से इस्तांबुल भेजा। दोनों राज्यों का संबंध कर या अधीनता नहीं बल्कि दूत और उपहार के आदान-प्रदान के स्तर पर रहा और शीघ्र उपहार के मसले पर तनावपूर्ण हो गया।", "0ddf3962"]},
"OLAYLAR_EK5:1578-10-05:0":{"b": ["देरबेंद की जनता का लाला मुस्तफ़ा पाशा के प्रति निष्ठा निवेदन — देमिरकापी ऑटोमन प्रशासन में", "9c55aeff"], "d": ["शिरवान अभियान के दौरान देरबेंद की जनता का सात लोगों का प्रतिनिधिमंडल एरेश में मौजूद सेरदार लाला मुस्तफ़ा पाशा के पास जाकर निष्ठा निवेदन कर गया। कॉकेशस की दीवार और कैस्पियन सागर के बीच के संकरे दर्रे को बंद करने वाला देरबेंद (देमिरकापी) उत्तर से आने वाले स्थल मार्गों के अनिवार्य दर्रे के रूप में शिरवान के थामे रखने में कुंजी भूमिका में रहा। ऑटोमन आधिपत्य यहाँ 1607 तक चला।", "9776382c"]},
"OLAYLAR_EK5:1578-11-01:0":{"b": ["शिरवान की विजय: शमाख़ी का लिया जाना", "9afae4c1"], "d": ["चिल्दिर विजय के बाद कॉकेशस की ओर खुली सेना ने सफ़वियों के कैस्पियन तट के सबसे समृद्ध प्रांत शिरवान में प्रवेश किया और केंद्र नगर शमाख़ी ले लिया। ओज़देमिरोग़्लु उस्मान पाशा को यहाँ बेयलरबेयी नियुक्त करके रेशम मार्ग की उत्तरी शाखा ऑटोमन नियंत्रण में लाई गई। शिरवान बारह वर्ष चलने वाले पूर्वी युद्ध का सबसे अधिक हाथ बदलने वाला और सबसे महँगा मोर्चा बनने वाला था।", "9955f6f2"]},
"OLAYLAR_EK5:1583-08-01:0":{"b": ["बाकू का लिया जाना — कैस्पियन तट तक पहुँच", "eb5adab8"], "d": ["शिरवान अभियान की अंतिम कड़ी के रूप में कैस्पियन सागर के पश्चिमी तट का बाकू बंदरगाह लिया गया। नगर के आसपास के तेल कुएँ उस दौर में भी ज्ञात आय स्रोत थे और बंदरगाह कैस्पियन से आने वाले ईरानी रेशम का निकास बिंदु था। ऑटोमन राज्य इस तरह इतिहास में पहली और एकमात्र बार कैस्पियन सागर के तट का स्वामी बना।", "ffafa858"]},
"OLAYLAR_EK5:1583-09-13:0":{"b": ["येरेवान की विजय और दुर्ग निर्माण", "7f623b7b"], "d": ["कार्स में येरेवान जाकर वहाँ दुर्ग बनाने का आदेश पाए फ़रहाद पाशा येरेवान पर चढ़े और नगर 991 के रमज़ान के आरंभ में (सितंबर 1583 के मध्य) ऑटोमन नियंत्रण में लिया गया। अरस घाटी के उत्तरी द्वार को थामे येरेवान में नया और बड़ा दुर्ग बनाया गया; नगर बेयलरबेयिलिक का केंद्र बनाया गया। कार्स और तबरेज़ के बीच सेना मार्ग के मध्य में खड़ा येरेवान पूर्वी मोर्चे की रसद रीढ़ था। दुर्ग इतना मज़बूत बनाया गया कि अगली दो शताब्दी ऑटोमन-ईरान युद्धों का अटल लक्ष्य बना रहा।", "f6b3bd6e"]},
"OLAYLAR_EK5:1588-09-01:0":{"b": ["काराबाग़ और गांजा का विलय", "29abaead"], "d": ["दस वर्ष के पूर्वी युद्ध की अंतिम उपलब्धि के रूप में फ़रहाद पाशा 1588 में गांजा पर चढ़े और 1 सितंबर को नगर में दाख़िल हुए; कुर और अरस के बीच का काराबाग़ क्षेत्र और उसका केंद्र गांजा ऑटोमन प्रशासन में लिया गया। इस तरह शिरवान, येरेवान और काराबाग़ मिलकर कॉकेशस में निर्बाध ऑटोमन रेखा बने। 1590 में हस्ताक्षरित फ़रहाद पाशा संधि इस सीमा को पंजीकृत करेगी, किंतु उपलब्धि केवल बीस वर्ष थामी जा सकेगी।", "67f1d89d"]},
"OLAYLAR_EK5:1592-06-19:0":{"b": ["बिहाच की विजय", "651a7275"], "d": ["बोस्निया बेयलरबेयी तेल्ली हसन पाशा ने नवंबर 1591 में बिहाच के अग्र-दुर्ग रिपाच को लेने के बाद 1592 में नगर और दुर्ग को भी अपने क़ब्ज़े में लिया; दस दिन की घेराबंदी के बाद सेनानायक लाम्बेर्ग ने आत्मसमर्पण किया। इस विजय ने बोस्निया सीमा को उना नदी के किनारे आगे धकेला और एक वर्ष बाद तेल्ली हसन पाशा के कुल्पा के सामने शहीद होने से भड़कने वाले लंबे युद्ध की पूर्वसंध्या की अंतिम बड़ी ऑटोमन उपलब्धि रही।", "b6814991"]},
"OLAYLAR_EK5:1593-07-01:0":{"b": ["ऑटोमन-ऑस्ट्रिया 'लंबे युद्ध' का आरंभ", "bd22c392"], "d": ["बोस्निया बेयलरबेयी तेल्ली हसन पाशा के कुल्पा (सिसेक) के सामने पराजित होकर शहीद होने पर ऑटोमन राज्य ने ऑस्ट्रिया पर युद्ध घोषित किया और तेरह वर्ष चलने वाला लंबा युद्ध आरंभ हुआ। आग्नेयास्त्रों से सज्जित पैदल सेना के निर्णायक होने वाले इस युद्ध ने ऑटोमन सेना व्यवस्था में सेकबान और बंदूकधारी सैनिकों की भर्ती को तेज़ किया और तिमारधारी सिपाही के पतन को गहरा किया। युद्ध 1606 में ज़ितवातोरोक संधि से समाप्त होगा।", "f309a27f"]},
"OLAYLAR_EK5:1593-07-19:0":{"b": ["कोजा सिनान पाशा ऑस्ट्रिया अभियान पर निकले — लंबे युद्ध का पहला अभियान", "d4a2f46d"], "d": ["बोस्निया बेयलरबेयी हसन पाशा के सिस्का (सिसाक) के सामने पराजित होकर शहीद होने के बाद वज़ीर-ए आज़म कोजा सिनान पाशा ने चमकीले शब्दों और वादों से पदीशाह को युद्ध के लिए राज़ी किया और 12.000 येनिचेरी तथा अन्य टुकड़ियों के साथ निकले। इस तरह तेरह वर्ष चलने वाले ऑटोमन-ऑस्ट्रिया युद्ध का पहला अभियान खुला।", "0f217276"]},
"OLAYLAR_EK5:1594-09-27:0":{"b": ["यानिककाले (ग्योर) की विजय", "14b75207"], "d": ["वज़ीर-ए आज़म कोजा सिनान पाशा ने एक माह से अधिक चली घेराबंदी के बाद वियना मार्ग की कुंजी माने जाने वाले यानिककाले को अपने हाथ में लिया। दुर्ग के गिरने ने यूरोप में भारी घबराहट पैदा की और ऑटोमन के लंबे युद्ध की सबसे चमकदार उपलब्धि बनी। किंतु दुर्ग केवल चार वर्ष थामा जा सकेगा।", "a634af40"]},
"OLAYLAR_EK5:1595-01-17:0":{"b": ["मुराद तृतीय का निधन", "1b62e886"], "d": ["इक्कीस वर्ष के शासन के बाद मुराद तृतीय, वलाचिया सेना के इब्रायल को जलाकर सिलिस्त्रे तक पहुँचने के दिनों में, चल बसे और आया सोफ़िया के हज़ीरे में दफ़नाए गए। मनीसा से बुलाए गए पुत्र मेहमेद तृतीय दस दिन बाद इस्तांबुल पहुँचकर गद्दी पर बैठे (27 जनवरी 1595)।", "1deabc61"]},
"OLAYLAR_EK5:1595-09-02:0":{"b": ["एस्तेरगोन का ऑस्ट्रिया के हाथ जाना", "f420d333"], "d": ["कार्ल फ़ॉन मान्सफ़ेल्ड के संचालित घेराव में पर्याप्त सहायता न पा सके एस्तेरगोन के रक्षकों ने दुर्ग आर्कड्यूक माथियास को सौंप दिया। बावन वर्ष के ऑटोमन आधिपत्य की समाप्ति से डैन्यूब रेखा की रक्षा-शृंखला टूट गई और बुदिन सीधे ख़तरे में आ गया। दुर्ग केवल दस वर्ष बाद, 1605 में, वापस लिया जा सकेगा।", "7617d6f2"]},
"OLAYLAR_EK5:1596-10-12:0":{"b": ["एग्री दुर्ग की विजय", "3e511629"], "d": ["तीन सप्ताह चले संघर्ष के बाद वह सुदृढ़ एग्री दुर्ग, जिसे ऑटोमन पहले किसी तरह न ले सके थे, रक्षकों के समर्पण से गिर गया। पदीशाह के स्वयं मौजूद रहने वाली इस विजय ने खोए एस्तेरगोन से उपजे मनोबल को कुछ हद तक सुधारा और एग्री प्रांत स्थापित हुआ। दो सप्ताह बाद मिली हाचोवा विजय के साथ 1596 लंबे युद्ध का ऑटोमन के लिए सबसे सफल वर्ष रहा।", "5dc53fa9"]},
"OLAYLAR_EK5:1598-03-29:0":{"b": ["यानिककाले (ग्योर) की हानि", "b4ccc679"], "d": ["मिक्लोश पाल्फ़ी और अडोल्फ़ फ़ॉन श्वार्त्सेनबेर्ग की कमान की टुकड़ियों ने छापे से दुर्ग के द्वार उड़ाकर यानिककाले वापस ले लिया। चार वर्ष पहले कोजा सिनान पाशा द्वारा बड़े श्रम से पाए दुर्ग की हानि ने हंगरी में ऑटोमन की अग्रिम पंक्ति ढहा दी। उसी वर्ष बुदिन को घेरने वाली शत्रु सेनाएँ खदेड़ी गईं तो भी युद्ध का संतुलन धीरे-धीरे थकाऊ युद्ध में बदलता गया।", "80bf88e0"]},
"OLAYLAR_EK5:1599-01-01:0":{"b": ["कारायाज़ीजी अब्दुलहलीम विद्रोह", "30493b0d"], "d": ["लंबे युद्ध में सेना से भागे सेकबान और लेवेंदों को जुटाने वाले कारायाज़ीजी अब्दुलहलीम ने मध्य अनातोलिया में बड़े क्षेत्र को अपने नियंत्रण में लिया, उरफ़ा दुर्ग पर क़ब्ज़ा किया (नवंबर 1599) और 'हलीम शाह' उपाधि से पदीशाही की घोषणा करके अपनी तुग़रा वाले फ़रमान भेजे। बड़ी जलाली लहर का पहला नेता माने जाने वाले कारायाज़ीजी 1602 में मर चुके थे, उनका आंदोलन भाई देली हसन ने जारी रखा। विद्रोह अनातोलिया के किसानों के सामूहिक रूप से अपनी भूमि छोड़ने वाले 'बड़ी भगदड़' काल का आरंभ है।", "ceda9161"]},
"OLAYLAR_EK5:1601-09-10:0":{"b": ["तिर्याकी हसन पाशा की कानिजे रक्षा", "d56a5e6a"], "d": ["एक वर्ष पहले जीते गए कानिजे को वापस लेना चाहने वाले आर्कड्यूक फ़र्डिनेंड और उनके सहयोगियों ने दुर्ग को दो माह से अधिक घेरा; तिर्याकी हसन पाशा 9000 की सेना से डटे रहे। बाहर से सहायता न पाने पर भी आम हमले खदेड़े और बाहर निकलकर किए आक्रमणों से शत्रु को भारी हानि देकर हटने पर विवश किया। रक्षा ऑटोमन इतिहास-लेखन में महाकाव्य बन गई और 'कानिजे घेराव' अपने आप में साहित्यिक विधा बन गया।", "edc6d7b6"]},
"OLAYLAR_EK5:1603-12-20:0":{"b": ["मेहमेद तृतीय का निधन और अहमद प्रथम का राज्यारोहण", "da735fde"], "d": ["मेहमेद तृतीय की 20 दिसंबर को मृत्यु पर चौदह वर्षीय पुत्र अहमद प्रथम गद्दी पर बैठे। बाल्यावस्था में और संजक पर गए बिना गद्दी पर बैठने वाले पहले पदीशाह होना शहज़ादों के प्रांत में पलने की प्रथा के वस्तुतः समाप्त होने को दिखाता है। अहमद प्रथम के शासन में भाई-हत्या छोड़कर 'एकबरियत' (सबसे वयोवृद्ध पुरुष सदस्य का गद्दी पर बैठना) सिद्धांत पर आया जाएगा।", "a5f7151a"]},
"OLAYLAR_EK5:1605-10-03:0":{"b": ["एस्तेरगोन की वापसी", "7330f273"], "d": ["वज़ीर-ए आज़म लाला मेहमेद पाशा ने दस वर्ष पहले खोए एस्तेरगोन को घेरकर फिर ऑटोमन प्रशासन में मिला लिया। उसी अभियान में पेश्त और वाच भी बचाए गए, ऑटोमन ने हंगरी में अपनी पंक्ति सँभाल ली थी। इस सफलता ने अगले वर्ष ज़ितवातोरोक में अपेक्षाकृत सशक्त स्थिति से वार्ता की मेज़ पर बैठना संभव किया; एस्तेरगोन 1683 तक ऑटोमन हाथ में रहेगा।", "242d3547"]},
"OLAYLAR_EK5:1607-10-24:0":{"b": ["ओरुच मैदान विजय और जानबोलातओग़्लु विद्रोह का दमन", "30f93532"], "d": ["हलब में स्वतंत्र बेयलिक बनाकर तोस्काना से गठबंधन खोजने वाले जानबोलातओग़्लु अली पाशा, वज़ीर-ए आज़म कुयुजू मुराद पाशा द्वारा ओरुच मैदान में भारी पराजित किए गए। सीरिया में केंद्रीय सत्ता के पुनर्स्थापित होने से जलाली लहर की सबसे ख़तरनाक शाखा टूटी। कुयुजू मुराद पाशा का दो वर्ष चला निर्मम सफ़ाया अनातोलिया में अस्थायी ही सही व्यवस्था ले आया।", "6e620c57"]},
"OLAYLAR_EK5:1608-08-09:0":{"b": ["अलाचायिर विजय और कालेंदरओग़्लु विद्रोह का दमन", "55db0485"], "d": ["मनीसा और बुर्सा क्षेत्रों से कर वसूलने वाले जलाली नेता कालेंदरओग़्लु अलाचायिर में कुयुजू मुराद पाशा द्वारा पराजित किए गए और ईरान भागने को विवश हुए। इस विजय से अनातोलिया की बड़ी जलाली सेनाओं में से अंतिम बिखेर दी गई। कुयुजू मुराद पाशा का, मरवाए विद्रोहियों को खुदवाए कुओं में भरवाने की रिवायत वाला कठोर सफ़ाया, अल्पकाल में व्यवस्था लाने पर भी अनातोलिया की जनसंख्या और उत्पादन हानि की भरपाई न कर सका।", "dc332b4b"]},
"OLAYLAR_EK5:1612-07-06:0":{"b": ["हॉलैंड को पहला अहदनामा दिया जाना", "5d9d117e"], "d": ["नीदरलैंड संयुक्त गणराज्य के दूत कोर्नेलिस हागा, अहमद प्रथम से फ़्रांस और इंग्लैंड को दिए गए के समान दायरे का अहदनामा पाने में सफल हुए। हॉलैंड ने इस तरह इस्तांबुल में दूतावास, ऑटोमन घाटों पर वाणिज्य दूतावास खोलने और अपने ध्वज से व्यापार करने का अधिकार पाया। यह अहदनामा भूमध्यसागर व्यापार में वेनिस का स्थान लेने वाली उत्तरी समुद्री शक्तियों के ऑटोमन बाज़ार में प्रवेश का प्रतीक है।", "7991027b"]},
"OLAYLAR_EK5:1617-11-22:0":{"b": ["अहमद प्रथम की मृत्यु और मुस्तफ़ा प्रथम का राज्यारोहण — एकबरियत प्रथा", "9901c09e"], "d": ["इक्यावन दिन चली पेट की बीमारी के बाद अट्ठाईस वर्षीय अहमद प्रथम चल बसे और पुत्र की जगह भाई मुस्तफ़ा प्रथम को गद्दी पर बिठाया गया। इस तरह पिता से पुत्र को जाने वाली उत्तराधिकार प्रथा छोड़कर राजवंश के सबसे वयोवृद्ध पुरुष सदस्य के गद्दी पर बैठने की 'एकबरियत' प्रणाली पर वस्तुतः आ गए। छियानवे दिन चला यह पहला शासन शहज़ादों के 'कफ़स' में पलने के काल का भी आरंभ है।", "1f866a67"]},
"OLAYLAR_EK5:1618-02-26:0":{"b": ["मुस्तफ़ा प्रथम का पदच्युत होना और जेंच उस्मान (उस्मान द्वितीय) का राज्यारोहण", "e0f552f2"], "d": ["मानसिक स्वास्थ्य ठीक न होने के आधार पर मुस्तफ़ा प्रथम छियानवे दिन के अंत में गद्दी से उतारे गए और अहमद प्रथम के चौदह वर्षीय पुत्र उस्मान द्वितीय पदीशाह बने। हसनबेयज़ादे पर आधारित वृत्तांत के अनुसार इस पदच्युति के निर्णय में किज़लार आग़ासी मुस्तफ़ा आग़ा प्रभावी रहे। जेंच उस्मान, येनिचेरी ओजाक को समाप्त करके नई सेना बनाने की योजना के साथ ऑटोमन सुधार चर्चाओं के पहले मूलगामी व्यक्ति माने जाते हैं। यह योजना चार वर्ष बाद उनके अपने प्राणों का मूल्य बनने वाली थी।", "4d655aca"]},
"OLAYLAR_EK5:1618-09-26:0":{"b": ["सराव संधि — ईरान से शांति का नवीनीकरण", "e778aca8"], "d": ["पुल-ए शिकस्ते पराजय के बाद ईरान से हुई सराव संधि ने 1612 की नसूह पाशा संधि की शर्तों को बड़े पैमाने पर पुष्ट किया; सफ़वियों के भेजने वाले वार्षिक रेशम की मात्रा दो सौ बोझ से घटाकर सौ बोझ कर दी गई। इस तरह 1603 से चले आ रहे पूर्वी युद्धों का दूसरा चरण बंद हुआ। शांति दीर्घजीवी न होगी, बग़दाद के 1623 में हाथ से निकलने पर युद्ध फिर भड़केगा।", "f14d72aa"]},
"OLAYLAR_EK5:1621-10-09:0":{"b": ["होतिन अभियान और होतिन संधि", "bc4c823c"], "d": ["उस्मान द्वितीय के स्वयं कमान की गई बड़ी सेना के विरुद्ध खोद्केविच द्वारा होतिन के सामने बनाए क़िलेबंद शिविर को पार न किया जा सका और महीनों चले हमलों से कोई परिणाम न मिला। 9 अक्तूबर को हस्ताक्षरित संधि से द्नीस्तर नदी सीमा मानी गई, पोल ने कज़ाक आक्रमणों को रोकने का वचन दिया। विजय बताए जाने के बावजूद परिणाम न दे सके अभियान ने युवा पदीशाह के येनिचेरी के प्रति अविश्वास और ओजाक के सफ़ाए के इरादे को पक्का किया।", "7d812c58"]},
"OLAYLAR_EK5:1622-04-23:0":{"b": ["होरमुज़ का पुर्तगालियों से लिया जाना", "93e5f6cf"], "d": ["सफ़वी सेनाओं ने 1515 से पुर्तगाल के हाथ रहे होरमुज़ को घेरकर वापस लिया; क़िश्म और तट का ग़मरून (बंदर अब्बास) भी सफ़वी प्रशासन में गया और खाड़ी का व्यापार नए बंदरगाह की ओर खिसका।", "cc55e4bf"]},
"OLAYLAR_EK5:1623-09-10:0":{"b": ["मुस्तफ़ा प्रथम का दूसरा पदच्युत होना और मुराद चतुर्थ का राज्यारोहण", "1b3a9e74"], "d": ["उस्मान द्वितीय के वध के बाद दूसरी बार गद्दी पर बिठाए गए मुस्तफ़ा प्रथम एक वर्ष तीन माह बाद फिर उतारे गए और ग्यारह वर्षीय मुराद चतुर्थ पदीशाह घोषित हुए। पहले नौ वर्ष राज्य वस्तुतः उनकी माता कोसेम सुल्तान और सराय के बड़े लोगों द्वारा चलाया गया। मुराद चतुर्थ 1632 से शासन अपने हाथ में लेकर कठोर केंद्रीकरण का काल आरंभ करेंगे।", "6dea0fec"]},
"OLAYLAR_EK5:1623-11-28:0":{"b": ["बग़दाद का सफ़वियों के हाथ जाना", "db81be0c"], "d": ["बग़दाद में विद्रोह करने वाले बेकिर सूबाशी की सफ़वियों से की गई सौदेबाज़ी के अंत में, भीतरी दुर्ग की रक्षा कर रहे पुत्र दरवेश मेहमेद ने नगर शाह अब्बास की सेनाओं को सौंप दिया। ख़िलाफ़त विरासत के प्रतीक नगरों में से एक और इराक़ के बड़े भाग के हाथ से निकलने ने इस्तांबुल में भारी आक्रोश जगाया। बग़दाद को वापस लेना पंद्रह वर्ष तक ऑटोमन पूर्वी नीति का एकमात्र लक्ष्य रहेगा।", "ef09360d"]},
"OLAYLAR_EK5:1628-09-22:0":{"b": ["अबाज़ा मेहमेद पाशा के एरज़ुरुम-केंद्रित विद्रोह का दमन", "e6da2729"], "d": ["उस्मान द्वितीय के वध का बदला लेने के दावे से येनिचेरियों के विरुद्ध विद्रोह करने वाले एरज़ुरुम बेयलरबेयी अबाज़ा मेहमेद पाशा ने वर्षों पूर्वी अनातोलिया को अपने नियंत्रण में रखा और केंद्र का प्रतिरोध किया। वज़ीर-ए आज़म ख़ुसरव पाशा की एरज़ुरुम घेराबंदी से उन्हें समर्पण करना पड़ा, क्षमा करके बोस्निया में नियुक्त किया गया। विद्रोह का अंत मुराद चतुर्थ के ईरान पर अभियान कर सकने की पूर्वशर्त था।", "68311e29"]},
"OLAYLAR_EK5:1634-01-08:0":{"b": ["पहला शेख़ुल-इस्लाम मृत्युदंड: अहीज़ादे हुसैन एफ़ेंदी", "a60a58c5"], "d": ["सैन्य अशांति में मध्यस्थता करने और पदीशाह को न्याय पद्धति पर लिखित चेतावनी भेजने के बहाने शेख़ुल-इस्लाम अहीज़ादे हुसैन एफ़ेंदी को बुयुकचेकमेजे के निकट मृत्युदंड दिया गया। मृत्युदंड पाने वाले पहले ऑटोमन शेख़ुल-इस्लाम होना, इल्मिये सदस्यों के लिए सबसे कड़ा दंड निर्वासन होने की गहरी जड़ों वाली परंपरा को तोड़ गया। घटना मुराद चतुर्थ के कठोर होते अधिकार और राज्य-उलेमा संतुलन के बिगड़ने का प्रतीक मानी जाती है।", "2822f303"]},
"OLAYLAR_EK5:1635-08-08:0":{"b": ["मुराद चतुर्थ द्वारा येरेवान की विजय", "b65a9b73"], "d": ["28 मार्च 1635 को इस्तांबुल से चले मुराद चतुर्थ ने 28-29 जुलाई को येरेवान को घेरा और 8 अगस्त को दुर्ग को अपने हाथ में लिया; इसके बाद ख़ाली कराए गए तबरेज़ में दाख़िल होकर नगर को तहस-नहस करवाया। पदीशाह ने विजय की स्मृति में तोपकापी सराय में येरेवान कोश्क बनवाया। यह अभियान पदीशाह के स्वयं सेना की कमान करने वाले तीस वर्ष के अंतराल के बाद का पहला बड़ा पूर्वी अभियान था।", "2da4da04"]},
"OLAYLAR_EK5:1636-04-01:0":{"b": ["येरेवान का सफ़वियों के हाथ जाना", "fbb8dd25"], "d": ["ऑटोमन सेना के हटने के बाद शाह सफ़ी की सेनाओं ने येरेवान को घेरकर आठ माह में वापस ले लिया। दुर्ग का इतनी जल्दी हाथ से निकलना दिखा गया कि कॉकेशस में स्थायी आधिपत्य रसद की दृष्टि से कितना कठिन है। येरेवान 1639 की क़स्र-ए शीरीन संधि से भी ईरान में छोड़ा जाएगा और ऑटोमन अज़रबैजान के दावे से हट जाएगा।", "f90cb004"]},
"OLAYLAR_EK5:1638-12-24:0":{"b": ["बग़दाद की पुनर्विजय", "4d2f27f3"], "d": ["8 मई 1638 को इस्तांबुल से निकले मुराद चतुर्थ ने चालीस दिन चली तीव्र घेराबंदी के बाद पंद्रह वर्ष से सफ़वी हाथ में रहे बग़दाद को वापस लिया; घेराबंदी में वज़ीर तयार मेहमेद पाशा शहीद हुए। नगर की विजय से इराक़ में ऑटोमन प्रशासन फिर स्थापित हुआ और पदीशाह ने 'बग़दाद विजेता' उपाधि ली। विजय अगले वर्ष की क़स्र-ए शीरीन संधि से स्थायी होकर आज की तुर्की-ईरान सीमा की नींव रख गई।", "bb99d1fb"]},
"OLAYLAR_EK5:1640-02-09:0":{"b": ["मुराद चतुर्थ की मृत्यु और सुल्तान इब्राहीम का राज्यारोहण", "e2ca1ca0"], "d": ["सत्ताईस वर्ष की आयु में (हिजरी गणना से अट्ठाईस) मरने वाले मुराद चतुर्थ के बाद राजवंश के जीवित एकमात्र पुरुष सदस्य उनके भाई इब्राहीम गद्दी पर बैठे। वर्षों कफ़स में रह चुके नए पदीशाह के शासन में सराय का ख़र्च और सराय के भीतर की प्रभाव-खींचतान ने राज्य व्यवस्था को हिलाया। आठ वर्ष बाद पदच्युत होकर वध किए जाने से ऑटोमन इतिहास का दूसरा पदीशाह-वध घटित होगा।", "9ad0a971"]},
"OLAYLAR_EK5:1642-02-26:0":{"b": ["आज़ाक दुर्ग का कज़ाकों से वापस लिया जाना", "e5fcf160"], "d": ["1637 में दोन कज़ाकों द्वारा क़ब्ज़ाया गया आज़ाक दुर्ग, सुल्तानज़ादे मेहमेद पाशा और क्रीमिया ख़ान चतुर्थ मेहमेद गिराय की संयुक्त कार्रवाई के सामने ख़ाली कर दिया गया; कज़ाक दुर्ग को जलाकर हट गए। काला सागर के उत्तरी द्वार के वापस लिए जाने ने कज़ाक आक्रमणों के इस्तांबुल जलडमरूमध्य तक पहुँचने के ख़तरनाक काल को बंद किया। दुर्ग 1696 में इस बार रूसी ज़ार पीटर प्रथम के हाथ चला जाएगा।", "39448f1f"]},
"OLAYLAR_EK5:1645-08-22:0":{"b": ["क्रीट अभियान का आरंभ और हानिया की विजय", "a1b0c77f"], "d": ["माल्टा के समुद्री डाकुओं के ऑटोमन हज जहाज़ पर प्रहार करके क्रीट में शरण लेने के बहाने वेनिस पर युद्ध घोषित हुआ और यूसुफ़ पाशा की कमान के बेड़े ने द्वीप पर सैनिक उतारे। चौवन दिन की घेराबंदी के बाद हानिया दुर्ग लिया जाकर क्रीट में पहला स्थायी ऑटोमन अड्डा बना। इस तरह ऑटोमन इतिहास का सबसे लंबा चला युद्ध आरंभ हुआ; द्वीप चौबीस वर्ष बाद, 1669 में, पूरी तरह जीता जा सकेगा।", "2809708a"]},
"OLAYLAR_EK5:1646-11-13:0":{"b": ["रेसमो की विजय — क्रीट का दो भागों में बँटना", "8f2c4353"], "d": ["हानिया पर अधिकार के एक वर्ष बाद द्वीप के मध्य भाग का रेसमो दुर्ग भी गिरा और क्रीट का पश्चिमी आधा भाग पूरी तरह ऑटोमन प्रशासन में आ गया। वेनिस के हाथ में केवल राजधानी कंदिये और पूर्वी छोर बचा; द्वीप तेईस वर्ष दो भागों में बँटा रहा। रेसमो का लिया जाना कंदिये घेराबंदी आरंभ करने वाला क़दम बना — इतिहास की सबसे लंबी घेराबंदी यहीं से शुरू हुई।", "88ec9840"]},
"OLAYLAR_EK5:1648-03-31:0":{"b": ["क्लिस का वेनिस के हाथ जाना", "5473c22c"], "d": ["क्रीट (कंदिये) युद्ध के दालमासिया मोर्चे पर वेनिस सेनानायक लेओनार्दो फ़ोस्कोलो के जवाबी आक्रमण ने 1537 से संजक का केंद्र रहे क्लिस को भी समेट लिया; दुर्ग वेनिस के पास चला गया। ऑटोमन के पूरी शक्ति से क्रीट पर केंद्रित होने ने दालमासिया सीमा पर इस हानि की भरपाई को असंभव कर दिया — क्लिस फिर कभी ऑटोमन प्रशासन में नहीं लौटेगा; संजक का केंद्र लिव्नो ले जाया गया।", "d0ec59d4"]},
"OLAYLAR_EK5:1648-05-01:0":{"b": ["कंदिये की घेराबंदी का आरंभ", "13016b10"], "d": ["हानिया और रेसमो पर अधिकार के बाद ऑटोमन सेना ने वेनिस के द्वीप पर अंतिम बड़े सहारे कंदिये को घेरे में लिया। इक्कीस वर्ष चलने वाली यह नाकाबंदी विश्व सैन्य इतिहास की सबसे लंबी घेराबंदियों में से एक के रूप में दर्ज हुई। घेराबंदी के दौरान वेनिस के बेड़े के चानाक्काले जलडमरूमध्य बंद करने के प्रयासों ने युद्ध को एजियन के मध्य तक पहुँचाया।", "8a35e8f9"]},
"OLAYLAR_EK5:1651-09-02:0":{"b": ["वालिदे सुल्तान कोसेम सुल्तान की हत्या", "9d763f79"], "d": ["लगभग बासठ वर्षीय कोसेम सुल्तान, मेहमेद चतुर्थ की माता तुरहान सुल्तान के आदेश से कार्य करने वाले बाशलाला उज़ुन सुलेमान आग़ा और उसके लोगों द्वारा हरम में एक कमरे में पाकर मार दी गईं। तीन पदीशाहों के काल में राज्य की राजनीति को दिशा देने वाली इस शक्तिशाली राजवंशीय स्त्री की मृत्यु 'स्त्रियों की सल्तनत' कहे जाने वाले काल का वस्तुतः अंत मानी जाती है। ख़ाली हुए अधिकार ने पाँच वर्ष बाद कोप्रुलु मेहमेद पाशा के असाधारण अधिकारों के साथ वज़ीर-ए आज़म बनने का मार्ग खोला।", "d1ff09cb"]},
"OLAYLAR_EK5:1656-07-13:0":{"b": ["चानाक्काले की पराजय और बोज़जाअदा तथा लिम्नी की हानि", "e01a1f7e"], "d": ["वेनिस एडमिरल मोचेनिगो की जून 1656 में चानाक्काले जलडमरूमध्य के सामने जीती बड़ी नौसैनिक विजय ने ऑटोमन बेड़े को लगभग पूरी तरह नष्ट कर दिया; इसके बाद बोज़जाअदा, लिम्नी और सेमादिरेक पर क़ब्ज़ा हुआ। जलडमरूमध्य के वेनिस नाकाबंदी में आने से इस्तांबुल में खाद्य क़ीमतें उछलीं और राजधानी पर आक्रमण का भय फैला। यह विपत्ति सितंबर 1656 में कोप्रुलु मेहमेद पाशा के शर्तबद्ध और असाधारण अधिकारों के साथ वज़ीर-ए आज़म बनाए जाने का सीधा कारण बनी।", "31f7a914"]},
"OLAYLAR_EK5:1657-08-25:0":{"b": ["चानाक्काले विजय और बोज़जाअदा की वापसी", "603da863"], "d": ["कोप्रुलु मेहमेद पाशा के जुटाए बेड़े ने 19 जुलाई 1657 को जलडमरूमध्य के सामने वेनिस के बेड़े को पराजित किया; इसके बाद कुर्द पाशा की कमान की सेनाओं ने 25 अगस्त को बोज़जाअदा वापस लिया और 30 अगस्त को वेनिसवासियों ने द्वीप को पूरी तरह ख़ाली किया। नवंबर में लिम्नी भी छुड़ाया जाकर चानाक्काले की नाकाबंदी टूटी और इस्तांबुल का रसद मार्ग फिर खुला। कोप्रुलु ने स्वयं द्वीप पर जाकर क़िलेबंदी की मरम्मत करवाई; यह सफलता कोप्रुलु काल की पहली बड़ी सैन्य उपलब्धि है।", "af4d7bfd"]},
"OLAYLAR_EK5:1658-08-27:0":{"b": ["यानोवा (इनेउ) की विजय और ट्रांसिल्वेनिया अभियान", "d1089616"], "d": ["बिना अनुमति पोलैंड अभियान पर निकलकर ऑटोमन संरक्षण की अवहेलना करने वाले ट्रांसिल्वेनिया राजकुमार द्वितीय ग्योर्ग्य राकोचि को दंडित करने निकले कोप्रुलु मेहमेद पाशा ने बेलग्रेड होकर कूच करके रणनीतिक यानोवा दुर्ग को लिया। ट्रांसिल्वेनिया में नया राजकुमार नियुक्त करके सामंती बंधन कठोरता से स्मरण कराया गया। यह अभियान ऑटोमन के मध्य यूरोप में अधिकार को फिर स्थापित करने के प्रयास की पहली कड़ी था। ट्रांसिल्वेनिया पहले से ऑटोमन की अधीन रियासत थी; यानोवा का लिया जाना किसी विदेशी राज्य से विजय नहीं, अधीन ट्रांसिल्वेनिया के इस दुर्ग को रियासत प्रशासन से निकालकर सीधे ऑटोमन संजक से जोड़ना था; रियासत का शेष भाग अधीन दर्जे में रहा।", "4e24d834"]},
"OLAYLAR_EK5:1659-02-16:0":{"b": ["अबाज़ा हसन पाशा विद्रोह का दमन", "4ba74321"], "d": ["कोप्रुलु मेहमेद पाशा के कठोर सफ़ाए के विरुद्ध अनातोलिया के बेयलरबेयियों और सेकबान आग़ाओं को साथ लेने वाले अबाज़ा हसन पाशा ने वज़ीर-ए आज़म को हटाने की माँग करके बड़ा विद्रोह आरंभ किया। विद्रोह हलब में कुचला गया और सरगना हटाए गए; यह प्रांतीय पाशाओं का केंद्र के विरुद्ध अंतिम सामूहिक प्रतिरोध रहा। कोप्रुलु का अधिकार इस तरह निर्विवाद हुआ और वज़ीर-ए आज़म पद फिर राज्य के वास्तविक कार्यकारी केंद्र के स्तर पर पहुँचा।", "900e66b5"]},
"OLAYLAR_EK5:1660-08-27:0":{"b": ["वारद (ओरादेया) की विजय", "0e6ad300"], "d": ["ऑटोमन पर युद्ध घोषित करने वाले ट्रांसिल्वेनिया राजकुमार द्वितीय ग्योर्ग्य राकोचि के विरुद्ध आयोजित अभियान के दायरे में वारद का दुर्ग और नगर लिया गया। ट्रांसिल्वेनिया के कुंजी दुर्गों में से एक के गिरने से क्षेत्र में नया ऑटोमन प्रांत (वारद प्रांत) स्थापित हुआ। विजय ने हैब्सबर्गों को सतर्क किया और तीन वर्ष बाद आरंभ होने वाले ऑटोमन-ऑस्ट्रिया युद्ध के सीधे कारणों में से एक बनी। उसी तिथि को शामिल हुए अन्य स्थान: वारात। यहाँ भी भूमि किसी विदेशी राज्य से नहीं ली गई: ट्रांसिल्वेनिया पहले से अधीन ऑटोमन रियासत थी; वारद के प्रांत बनने ने केवल इस नगर का प्रशासन अधीन रियासत से लेकर सीधे पदीशाह से जोड़ा, ठीक दो वर्ष पहले यानोवा की तरह।", "991162de"]},
"OLAYLAR_EK5:1664-08-01:0":{"b": ["सेंट गोतहार्ड (सेंट गोटहार्ड) युद्ध", "61ebc1f2"], "d": ["रआब नदी पार करने वाली ऑटोमन सेनाएँ मोंतेकुक्कोली की कमान के संयुक्त यूरोपीय सेना द्वारा रोकी गईं और भारी हानि उठाई। युद्ध अनुशासित आग्नेयास्त्र पैदल सेना की बंदूक-वर्षा की ऑटोमन घुड़सवार हमले पर श्रेष्ठता को पहली बार स्पष्ट सामने लाने के कारण सैन्य इतिहास में मोड़ माना जाता है। पराजय के बावजूद ऑटोमन नौ दिन बाद हस्ताक्षरित वास्वार संधि में लाभदायक शर्तें पाने में सफल रहा।", "4ab743fc"]},
"OLAYLAR_EK5:1664-08-09:0":{"b": ["वास्वार संधि", "089c978c"], "d": ["सेंट गोतहार्ड की पराजय के बावजूद हस्ताक्षरित संधि ने उयवार और वारद के ऑटोमन में रहने, ट्रांसिल्वेनिया के ऑटोमन संरक्षण में तटस्थ छोड़े जाने और ऑस्ट्रिया के 200.000 क़ुरुश 'उपहार' देने का प्रावधान किया। बीस वर्षीय यह शांति युद्ध हारने वाले पक्ष के मेज़ पर जीतने के दुर्लभ उदाहरणों में से है। संधि से हैब्सबर्ग जनमत में पैदा असंतोष मध्य हंगरी आंदोलन और परोक्ष रूप से 1683 के वियना अभियान को पोषित करेगा।", "61ca5d47"]},
"OLAYLAR_EK5:1671-01-01:0":{"b": ["अल्जीरिया में दाई शासन का आरंभ", "e99faa51"], "d": ["अल्जीरिया के ओजाक और तायफ़े-ए रेइस (समुद्री डाकू कप्तान) ने अंतिम आग़ा को हटाकर हाजी मेहमेद को आजीवन शर्त पर दाई चुना। इस तिथि के बाद अल्जीरिया को इस्तांबुल द्वारा नियुक्त बेयलरबेयी नहीं, स्थानीय ओजाक द्वारा अपने बीच से चुना दाई चलाता रहा; ऑटोमन संबंध ख़ुतबे में पदीशाह का नाम पढ़ने, ध्वज और अभियान दायित्व तक सीमित रहा। अल्जीरिया इस तरह प्रांत से ओजाकलिक में बदला — यही परिवर्तन ट्यूनिस ने 1705 में हुसैनियों से, त्रिपोलीतानिया ने 1711 में करामानलियों से देखा।", "b8decd95"]},
"OLAYLAR_EK5:1672-06-04:0":{"b": ["पोलैंड अभियान आरंभ हुआ — मेहमेद चतुर्थ और फ़ाज़िल अहमद पाशा सेना के नेतृत्व में", "75e15a39"], "d": ["ऑटोमन संरक्षण में आए यूक्रेन के हेटमैन पेत्रो दोरोशेंको के विरुद्ध पोलैंड के आक्रमण जारी रहने पर इस्तांबुल ने पोल राजा से आक्रमणों से विरत होने को कहा; सकारात्मक उत्तर न आने पर पोलैंड पर अभियान का निर्णय हुआ। वज़ीर-ए आज़म फ़ाज़िल अहमद पाशा ने, पदीशाह के भी साथ रहने वाली सेना से, 4 जून 1672 को पोलैंड की ओर प्रस्थान किया। अभियान कामानिचे की विजय और बुचाच संधि में परिणत होगा।", "7340721a"]},
"OLAYLAR_EK5:1672-08-27:0":{"b": ["कामानिचे की विजय और पोडोलिया प्रांत की स्थापना", "c3f4f6d0"], "d": ["नौ दिन की घेराबंदी के बाद पोलैंड के पूर्व के सबसे सशक्त दुर्ग माने जाने वाले कामानिचे ने आत्मसमर्पण किया; मेहमेद चतुर्थ ने 2 सितंबर को कैथेड्रल से बदली गई मस्जिद में पहली जुमे की नमाज़ पढ़ी। दुर्ग को केंद्र बनाकर पोडोलिया प्रांत स्थापित हुआ और ऑटोमन ध्वज आज के यूक्रेन की भूमि पर सबसे उत्तर तक पहुँचा। कामानिचे 1699 की कार्लोफ़चा संधि तक साम्राज्य का उत्तर-पश्चिमी छोर रहेगा।", "d89c513a"]},
"OLAYLAR_EK5:1674-08-03:0":{"b": ["कारा मुस्तफ़ा पाशा ने उमान पोलैंड से प्राप्त किया", "0d3543a0"], "d": ["पोलैंड के विरुद्ध भेजे गए कारा मुस्तफ़ा पाशा ने पोलैंड के हाथ के दुर्गों में से उमान को आत्मसमर्पण में प्राप्त किया; नगर कार्लोफ़चा तक ऑटोमन प्रशासन में रहा।", "bdb8e553"]},
"OLAYLAR_EK5:1678-08-21:0":{"b": ["चेहरिन दुर्ग की विजय", "a17cedd0"], "d": ["एक वर्ष पहले मेलेक इब्राहीम पाशा के परिणाम न पा सके अभियान के बाद वज़ीर-ए आज़म मेरज़ीफ़ोनलू कारा मुस्तफ़ा पाशा ने स्वयं कमान करके क़िलेबंद चेहरिन दुर्ग को घेरा (19/21 जुलाई) और 21 अगस्त को अपने हाथ में लिया। यूक्रेन के कज़ाक हेटमैनशिप पर ऑटोमन-रूसी प्रतिद्वंद्विता के प्रतीक दुर्ग का गिरना रूस को शांति के लिए विवश कर गया। यह सफलता मेरज़ीफ़ोनलू के वियना की ओर बढ़ने वाले आत्मविश्वास के स्रोतों में से एक बनी।", "aee53ec4"]},
"OLAYLAR_EK5:1681-02-13:0":{"b": ["बाग़चेसराय संधि — रूस से पहली औपचारिक शांति", "df82bc0b"], "d": ["चेहरिन अभियानों के बाद क्रीमिया ख़ान की मध्यस्थता से चली वार्ताओं के अंत में, ओज़ू (नीपर) नदी को सीमा मानकर ऑटोमन राज्य और रूस के बीच बीस वर्ष की शांति हस्ताक्षरित हुई। यह दोनों राज्यों के बीच पहली व्यापक संधि होने के कारण ऑटोमन-रूसी संबंधों का आरंभिक दस्तावेज़ माना जाता है। शांति से पूर्वी मोर्चा सुरक्षित होने पर सेना को मध्य यूरोप की ओर मोड़ा जा सका।", "56f57388"]},
"OLAYLAR_EK5:1682-09-16:0":{"b": ["तोकोली इमरे को मध्य हंगरी राज्य की बेरात दिया जाना", "3cd8d51d"], "d": ["हैब्सबर्ग दबाव के विरुद्ध विद्रोह करने वाले प्रोटेस्टेंट हंगरियाई कुलीन तोकोली इमरे को अप्रैल 1682 से 'मध्य हंगरी का निर्वाचित राजा' माना जाने लगा और 16 सितंबर को बुदिन बेयलरबेयी इब्राहीम पाशा ने उन्हें राजसी चिह्न भेंट किए। इस तरह ऑटोमन संरक्षण में नया सामंती हंगरियाई राज्य स्थापित हुआ। इस हस्तक्षेप ने ऑस्ट्रिया से युद्ध को अनिवार्य बनाकर अगले वर्ष की द्वितीय वियना घेराबंदी तक की शृंखला आरंभ की।", "6f7f5236"]},
"OLAYLAR_EK5:1684-08-06:0":{"b": ["आयामावरा (लेफ़कादा) का वेनिस के हाथ जाना", "e6905fee"], "d": ["पवित्र गठबंधन में सम्मिलित वेनिस के बेड़े ने नगर पर तोप बरसाकर आयोनियन सागर के आयामावरा द्वीप पर क़ब्ज़ा किया। उसी वर्ष प्रेवेज़ा के भी गिरने से ऑटोमन का एड्रियाटिक मुहाने का नियंत्रण टूटा। ये हानियाँ मोरोसिनी के तीन वर्ष में पूरा मोरिया ले लेने वाले अभियान के आरंभिक क़दम थीं।", "8fe34c55"]},
"OLAYLAR_EK5:1685-08-11:0":{"b": ["कोरोन का वेनिस के हाथ जाना", "2ed762bc"], "d": ["मोरोसिनी की कमान की वेनिस सेनाओं ने मोरिया प्रायद्वीप के दक्षिण-पश्चिमी छोर का कोरोन दुर्ग अपने हाथ में लिया; नगर इसके बाद तीस वर्ष वेनिस प्रशासन में रहेगा। कोरोन का गिरना मोरिया की विजय की ओर बढ़ने वाले वेनिस अभियान का पहला बड़ा लाभ था। दुर्ग केवल 1715 में सिलाहदार अली पाशा की कमान की ऑटोमन सेना द्वारा वापस लिया जा सका।", "506cf83e"]},
"OLAYLAR_EK5:1688-04-08:0":{"b": ["एथेंस की वापसी — वेनिस का हटना", "03393b46"], "d": ["1687 के सितंबर में अक्रोपोलिस पर बम बरसाकर पार्थेनन को उड़ाने वाले मोरोसिनी ने सर्दी एथेंस में बिताकर समझ लिया कि नगर में टिक नहीं सकेंगे। प्लेग महामारी, रसद-कठिनाई और ऑटोमन सेनाओं के सँभलने पर वेनिस चौकी नगर ख़ाली करके मोरिया हट गई। एथेंस इस तरह बिना लड़े फिर ऑटोमन प्रशासन में लौटा, किंतु पार्थेनन को हुई तबाही वापस न की जा सकी।", "79c8586a"]},
"OLAYLAR_EK5:1688-06-22:0":{"b": ["लिपोवा (लिप्पा) कराफ़ा के सम्मुख समर्पित — ऑस्ट्रिया के हाथ में गया", "7f0a8d38"], "d": ["अंतोनियो कराफ़ा की तीन दिन की घेराबंदी के बाद लिपोवा ने 12-22 जून 1688 के बीच आत्मसमर्पण किया और ऑस्ट्रिया के हाथ में चला गया। उस्मानियों ने बाद में नगर वापस ले लिया, ऑस्ट्रिया ने 1691 में पुनः अधिकार किया; 1695 के अभियान में उस्मानियों ने फिर नियंत्रण पाया। इसी तिथि को उस्मानी से हाब्सबर्ग को जाने वाली अन्य बस्तियाँ: अराद और विलागोश (शिरिया)। अराद के लिए स्रोत केवल वर्ष देता है (MKL, अराद: 1551-1688 के बीच उस्मानी हाथ में); दिन लिपोवा से लिया गया है, विलागोश के लिए अराद की तिथि को आधार माना गया (अनुमानित जानकारी)। लुगोश (लुगोज) और कारान्शेबेश (कारांसेबेश) के दुर्ग भी जून के अंत में ऑस्ट्रिया के पास गए (Bánlaky 0016/1302 'Jenővel elveszett Lugos és Karánsebes'; 0017/1443 'június végén')।", "0dd3ce90"]},
"OLAYLAR_EK5:1688-10-20:0":{"b": ["वेनिस की एग्रिबोज़ घेराबंदी का खदेड़ा जाना", "aae7e6a0"], "d": ["मोरिया लेने के बाद एजियन की ओर मुड़े मोरोसिनी ने तीन माह से अधिक चली घेराबंदी से एग्रिबोज़ लेने का प्रयास किया; किंतु 1687-1688 की सर्दी में सुदृढ़ की गई क़िलेबंदी और चौकी के प्रतिरोध के सामने भारी हानि उठाकर हटना पड़ा। इस विफलता ने वेनिस की एजियन में प्रगति रोकी और मोरोसिनी की सैन्य प्रतिष्ठा को हिलाया। एग्रिबोज़ कार्लोफ़चा में भी ऑटोमन हाथ में रहेगा।", "ea8430a3"]},
"OLAYLAR_EK5:1690-04-23:0":{"b": ["कानिजे दुर्ग का ऑस्ट्रिया के हाथ जाना", "553b45f3"], "d": ["1690 जनवरी से 60.000 की हैब्सबर्ग सेना की कड़ी नाकाबंदी में आया कानिजे महीनों बिना सहायता डटे रहने के बाद अंतिम रक्षक मुस्तफ़ा पाशा के हस्ताक्षरित समर्पण समझौते से हाथ से निकल गया। इस तरह तिर्याकी हसन पाशा की महाकाव्यात्मक रक्षा से याद किए जाने वाले दुर्ग में नब्बे वर्ष का ऑटोमन आधिपत्य समाप्त हुआ। कानिजे की हानि हंगरी के पश्चिम में ऑटोमन के अंतिम बड़े सहारे का ढहना थी।", "dc630d57"]},
"OLAYLAR_EK5:1691-06-22:0":{"b": ["सुलेमान द्वितीय का निधन", "d2478080"], "d": ["कफ़स में लगभग चालीस वर्ष बिताने के बाद 1687 में गद्दी पर बिठाए गए सुलेमान द्वितीय, बीमार दशा में सेना की तैयारियाँ देखते हुए 22 जून 1691 शुक्रवार को दोपहर के क़रीब एदिर्ने में चल बसे; शासन तीन वर्ष आठ माह दो दिन चला। वज़ीर-ए आज़म ने पदीशाह की मृत्यु की स्थिति में भाई अहमद के गद्दी पर बिठाए जाने के लिए आवश्यक निर्देश पहले ही दे रखे थे। जनाज़े की नमाज़ उसी दिन अलाय कोश्क में पढ़ी गई; पार्थिव शरीर इस्तांबुल लाकर कानूनी सुल्तान सुलेमान के मक़बरे में उनके दाहिनी ओर दफ़नाया गया।", "3cf4fcb1"]},
"OLAYLAR_EK5:1691-06-23:0":{"b": ["अहमद द्वितीय का गद्दी पर बैठना", "52947b14"], "d": ["सुलेमान द्वितीय की मृत्यु पर उनचास वर्षीय भाई अहमद द्वितीय एदिर्ने में गद्दी पर बैठे। उनका शासन पवित्र गठबंधन युद्धों के सबसे भारी वर्षों से टकराया; राज्यारोहण के दो माह बाद सालान्केमेन में वज़ीर-ए आज़म फ़ाज़िल मुस्तफ़ा पाशा शहीद हुए। इसके विपरीत उनके काल में लागू की गई मालिकाने प्रणाली ऑटोमन वित्त की दीर्घकालिक संरचना को बदलने वाली सबसे महत्वपूर्ण व्यवस्थाओं में से एक रही।", "d3441b14"]},
"OLAYLAR_EK5:1693-01-06:0":{"b": ["मेहमेद चतुर्थ का एदिर्ने में निधन", "17388b7e"], "d": ["1687 में गद्दी से उतारे गए अवजी (शिकारी) मेहमेद, सुलेमान द्वितीय के 1689 के हंगरी अभियान के दौरान एदिर्ने लाए गए और दूसरे भाई अहमद द्वितीय के शासन के भी साक्षी बने। अपने अत्यंत प्रिय इस नगर में चल बसे। पार्थिव शरीर इस्तांबुल लाकर माता तुरहान सुल्तान के येनिजामी के निकट के मक़बरे में दफ़नाया गया।", "fd0f3d8c"]},
"OLAYLAR_EK5:1695-02-06:0":{"b": ["अहमद द्वितीय का एदिर्ने में निधन", "c6306c08"], "d": ["चार वर्ष का शासन युद्ध में बीतने वाले अहमद द्वितीय बावन वर्ष की आयु में इस्तिस्क़ा (जलोदर) के कारण एदिर्ने में चल बसे। पार्थिव शरीर इस्तांबुल लाकर कानूनी सुल्तान सुलेमान के मक़बरे में दफ़नाया गया। उनकी जगह भतीजे मुस्तफ़ा द्वितीय बैठे।", "a61e819c"]},
"OLAYLAR_EK5:1696-01-01:0":{"b": ["बसरा का ईरानियों के हाथ जाना", "a9cdf3a3"], "d": ["ऑटोमन राज्य के पश्चिम में पवित्र गठबंधन युद्धों में उलझे होने के समय बसरा, 1690 की प्लेग महामारी के बाद पहले मुंतफ़िक शेख़ माने और फिर हुवैज़ा ख़ान फ़रजुल्लाह की लूट का शिकार हुआ था। इस अशांति का लाभ उठाकर ईरानियों ने 1696 में नगर ले लिया और बसरा में एक रक्षक छोड़ा।", "2db76d27"]},
"OLAYLAR_EK5:1700-07-14:0":{"b": ["इस्तांबुल संधि — आज़ाक का रूस को छोड़ा जाना", "79db4724"], "d": ["कार्लोफ़चा में रूस से केवल दो वर्ष का युद्धविराम हो सका था; स्थायी शांति इस्तांबुल में डेढ़ वर्ष चली कठिन सौदेबाज़ी के बाद हस्ताक्षरित हुई। ऑटोमन राज्य ने 1696 में खोए आज़ाक दुर्ग और उसके आसपास की भूमि को औपचारिक रूप से रूस को छोड़ दिया, क्रीमिया ख़ान के मॉस्को से पाए वार्षिक कर को त्याग दिया। इसके बदले रूस ने इस्तांबुल में स्थायी दूत रखने का अधिकार पाया; इस तरह काला सागर के उत्तरी तट पर रूसी उपस्थिति विधिक रूप से पंजीकृत हो गई।", "a3a5a803"]},
"OLAYLAR_EK5:1701-01-01:0":{"b": ["दलताबान मुस्तफ़ा पाशा का क़ूर्ने और बसरा वापस लेना", "7adb777d"], "d": ["कार्लोफ़चा संधि के बाद बग़दाद वालीत्व और बसरा सेरआस्कर पद पर लाए गए दलताबान मुस्तफ़ा पाशा हलब, रक्का, सिवास और करमान की सेनाओं और बिरेजिक से उतरे नदी-बेड़े के साथ दक्षिण की ओर बढ़े। आसपास के क़बीलाई शेख़ों ने एक-एक करके आज्ञा मानी, ईरान के बसरा रक्षक दाऊद ख़ान ने नगर छोड़ा और क़ूर्ने तथा बसरा फिर ऑटोमन प्रशासन में आ गए।", "60abbe06"]},
"OLAYLAR_EK5:1703-12-29:0":{"b": ["मुस्तफ़ा द्वितीय का निधन", "626c394d"], "d": ["एदिर्ने घटना से गद्दी भाई अहमद तृतीय को छोड़ने वाले मुस्तफ़ा द्वितीय, गद्दी से उतारे जाने के पाँच माह बाद अत्यंत प्रिय एदिर्ने में चल बसे। उनकी बीमारी में हाल की घटनाओं का शोक भी जुड़ गया था। कुछ पश्चिमी स्रोत लिखते हैं कि जनता में उन्हें ज़हर दिए जाने की धारणा व्यापक थी।", "8ce146e8"]},
"OLAYLAR_EK5:1704-01-01:0":{"b": ["बग़दाद में कोलेमेन (मामलूक) शासन का आरंभ", "abe52618"], "d": ["जॉर्जियाई मूल के हसन पाशा के बग़दाद वालीत्व पर लाए जाने से इराक़ में केंद्र से नियुक्त वालियों के स्थान पर अपने ग़ुलामों से तैयार शासक वर्ग के हावी होने का काल आरंभ हुआ। सुलेमान पाशा की 1749 की वालीत्व से प्रणाली पूरी तरह जम गई और बाबे-आली अब मनचाहे व्यक्ति को नहीं, प्रभाव हथिया चुके कोलेमेनों में से किसी एक को नियुक्त करने को विवश हुआ। यह अर्ध-स्वायत्त ढाँचा ईरान सीमा की रक्षा में काम आया तो भी इराक़ पर केंद्रीय अधिकार के नियंत्रण को डेढ़ शताब्दी तक कमज़ोर करता रहा।", "7cf655d4"]},
"OLAYLAR_EK5:1705-07-12:0":{"b": ["ट्यूनिस में हुसैनी राजवंश की स्थापना", "cb1a98f9"], "d": ["अल्जीरियाई सेनाओं के ट्यूनिस पर आक्रमण से बने अधिकार-शून्य में तुर्क मूल के सिपाही आग़ा हुसैन बिन अली ने बेयलिक अपने हाथ में लिया और ऑटोमन पदीशाह के प्रति निष्ठा बताकर वैधता पाई। उनका स्थापित राजवंश 1705-1735 और 1756-1957 के बीच ट्यूनिस पर शासन करता रहा; ओजाक शासन का स्थान पिता से पुत्र को जाने वाली बेयलिक व्यवस्था ने ले लिया। इस तरह पश्चिमी ओजाकों में केंद्र से जुड़ी पर वस्तुतः स्वायत्त राजवंशीय संरचनाओं का पहला उदाहरण जन्मा।", "941c7858"]},
"OLAYLAR_EK5:1708-04-04:0":{"b": ["वहरान (ओरान) और मेर्सेलकबीर का स्पेनियों से लिया जाना", "b67ce06a"], "d": ["अल्जीरिया ओजाक के बेयलरबेयी की सेनाओं ने दो शताब्दी से स्पेनी चौकी के हाथ रहे वहरान और बंदरगाह मेर्सेलकबीर को लंबी घेराबंदी के बाद अपने हाथ में लिया। पश्चिमी भूमध्यसागर में ऑटोमन संरक्षण के पश्चिमी ओजाकों की स्पेन के विरुद्ध सबसे बड़ी सफलता थी और अल्जीरिया का पश्चिमी पार्श्व सुरक्षित किया। नगर 1732 में फिर स्पेनी क़ब्ज़े में आएगा, किंतु 1792 में निश्चित रूप से वापस लिया जाएगा।", "33d9da74"]},
"OLAYLAR_EK5:1711-07-21:0":{"b": ["प्रुत संधि — आज़ाक और तायगन की वापसी", "bac5d2a1"], "d": ["प्रुत तट पर घिरी रूसी सेना के आत्मसमर्पण से हस्ताक्षरित सात धाराओं की संधि ने आज़ाक दुर्ग के भूमि और गोला-बारूद के साथ ऑटोमन को लौटाए जाने का प्रावधान किया। तायगन, कामेंका और येनिकाले की क़िलेबंदियाँ ध्वस्त की जाएँगी, पक्ष इन क्षेत्रों में नया दुर्ग नहीं बनाएँगे। पीटर प्रथम का वोरोनेज़ और आज़ाक में सोलह वर्ष में बनाया बेड़ा और अड्डा व्यवस्था ढह गई; रूस का काला सागर में उतरना लगभग पचास वर्ष टल गया।", "657d45ff"]},
"OLAYLAR_EK5:1711-07-29:0":{"b": ["त्रिपोलीतानिया में करामानली राजवंश की स्थापना", "e1105d4a"], "d": ["ओजाक आग़ाओं की खींचतान से त्रस्त त्रिपोलीतानिया में घुड़सवार अधिकारी अहमद करामानली ने प्रशासन अपने हाथ में लिया और इस्तांबुल से पाई बेयलरबेयी बेरात से अपनी स्थिति को औपचारिक बनाया। अहमद पाशा, पुत्र मेहमेद पाशा और पौत्र यूसुफ़ पाशा के हाथों 1711-1835 के बीच चलने वाला राजवंश जन्मा; अपना बेड़ा बनाने वाली, यूरोपीय राज्यों से सीधी संधि हस्ताक्षरित करने वाली अर्ध-स्वतंत्र संरचना उभरी। यह काल केवल 1835 में प्रांत के सीधे केंद्र से जुड़ने के साथ समाप्त होगा।", "b1c3dd0a"]},
"OLAYLAR_EK5:1713-06-24:0":{"b": ["रूस से एदिर्ने संधि", "14901a70"], "d": ["प्रुत में दिए वचनों के पूरे न किए जाने पर दो बार और युद्ध घोषित हुआ, अंत में रूसियों के प्रतिबद्धताएँ स्वीकार करने पर एदिर्ने में स्थायी शांति हस्ताक्षरित हुई। संधि ने प्रुत की शर्तें पुष्ट कीं; रूस पोलैंड के मामलों में हस्तक्षेप नहीं करेगा, कज़ाक भूमि से हट जाएगा और स्वीडन के राजा दिमिर्बाश (लोहे के सिर वाले) कार्ल को देश लौटने से नहीं रोकेगा। उत्तरी मोर्चे के इस तरह बंद होने ने ऑटोमन राज्य को अपना मुँह मोरिया और वेनिस मोर्चे की ओर मोड़ने में सक्षम किया। उसी तिथि को शामिल हुए अन्य स्थान: होतिन।", "34010e06"]},
"OLAYLAR_EK5:1714-12-08:0":{"b": ["वेनिस पर युद्ध घोषणा — मोरिया अभियान की तैयारी", "d970b122"], "d": ["वेनिस के मोंटेनेग्रो विद्रोहियों का समर्थन करने, ऑटोमन व्यापारी जहाज़ों पर क़ब्ज़ा करने और कार्लोफ़चा में पाए मोरिया को भारी करों से कुचलने के आधार पर दीवान में युद्ध का निर्णय लिया गया। वज़ीर-ए आज़म सिलाहदार दामाद अली पाशा के तैयार किए अभियान का परिणाम अगले वर्ष सौ दिन से कम में पूरे मोरिया प्रायद्वीप की वापसी होगा। किंतु यह सफलता ऑस्ट्रिया को सक्रिय करेगी और 1716 में कहीं अधिक भारी युद्ध का द्वार खोलेगी।", "ef2edb5f"]},
"OLAYLAR_EK5:1715-06-05:0":{"b": ["इस्तेंदिल (तिनोस): वेनिस के एजियन के अंतिम द्वीप का समर्पण", "4abec891"], "d": ["मोरिया अभियान पर निकले बेड़े ने मार्ग में वेनिस के एजियन में शेष एकमात्र द्वीप इस्तेंदिल के सामने लंगर डाला। नाक्सोस डची के 1566 में गिरने के बावजूद लातिन जनसंख्या के कारण डेढ़ सौ वर्ष और वेनिस ध्वज उठाए रहा द्वीप, संक्षिप्त घेराबंदी के बाद रक्त बहे बिना समर्पित हुआ। इस तरह एजियन सागर में वेनिस का अंतिम पदचिह्न मिट गया और समुद्र पूरी तरह ऑटोमन का आंतरिक सागर बन गया।", "7b191aca"]},
"OLAYLAR_EK5:1715-07-20:0":{"b": ["अनाबोलू की विजय — मोरिया का कुंजी दुर्ग", "62a5808a"], "d": ["वेनिस की मोरिया की राजधानी और सबसे सशक्त क़िलेबंदी अनाबोलू, पालामिदी तबिया के नौ दिन की बमबारी के बाद लिए जाने से गिरा। दुर्ग के इतनी जल्दी लिए जाने ने प्रायद्वीप के शेष भाग का प्रतिरोध तोड़ा। कार्लोफ़चा में खोए मोरिया की वापसी वस्तुतः यहीं पूर्ण हुई। उसी तिथि को वेनिस से ऑटोमन को गया अन्य स्थान: आर्गोस — अनाबोलू की तिथि को आधार माना गया (TDV अनाबोलू; अनुमानित जानकारी)।", "819680c1"]},
"OLAYLAR_EK5:1715-08-01:0":{"b": ["मोदोन का समर्पण", "43faa909"], "d": ["अनाबोलू के गिरने के बाद मोरिया के दक्षिण-पश्चिमी छोर का मोदोन दुर्ग, स्थल से सेना और समुद्र से बेड़े द्वारा घेरा गया और शीघ्र समर्पित हुआ। वेनिस के पूर्वी भूमध्यसागर अभियानों में दो शताब्दी प्रयुक्त यह बंदरगाह जहाज़ों के पानी और रसद लेने का अनिवार्य पड़ाव था। इसकी हानि ने वेनिस बेड़े की एजियन में गतिशीलता समाप्त कर दी।", "0d2c6d1a"]},
"OLAYLAR_EK5:1715-08-16:0":{"b": ["कोरोन का समर्पण — मोरिया अभियान की पूर्णता", "e4b9c8a4"], "d": ["मेस्सेनिया खाड़ी के मुहाने को थामे कोरोन दुर्ग के समर्पण से मोरिया प्रायद्वीप पर वेनिस प्रशासन पूरी तरह समाप्त हुआ। कार्लोफ़चा में खोया प्रायद्वीप अभियान खुलने के केवल तीन माह बाद पूरी तरह वापस ले लिया गया। उसी अभियान के क्रम में, सितंबर 1715 में, आयोनियन सागर का आयामावरा (लेफ़कादा) द्वीप भी वेनिस से लिया गया। इस गति ने वेनिस को ऑस्ट्रिया को युद्ध में उतारने के लिए विवश किया और तीन वर्ष बाद पासारोफ़चा का मार्ग खुला।", "d3173b05"]},
"OLAYLAR_EK5:1715-09-07:0":{"b": ["चुहा द्वीप (किथिरा) का लिया जाना", "494de6c6"], "d": ["मोरिया के दक्षिणी छोर का चुहा द्वीप, प्रायद्वीप के पूर्ण होने के बाद बेड़े द्वारा अपने हाथ में लिया गया। आयोनियन सागर और एजियन के बीच के पारगमन पर नज़र रखने वाला यह द्वीप वेनिस की इन समुद्रों को नियंत्रित करने की अग्रिम चौकी था। किंतु थामा रहने वाला एकमात्र ऑटोमन द्वीप न बना: तीन वर्ष बाद पासारोफ़चा में वेनिस को वापस दे दिया गया।", "42162c0d"]},
"OLAYLAR_EK5:1716-04-13:0":{"b": ["ऑस्ट्रिया और वेनिस ने गठबंधन किया — 1716-1718 ऑटोमन-ऑस्ट्रिया युद्ध का द्वार", "99511ca2"], "d": ["ऑटोमन के मोरिया को वेनिस से वापस लेने के बाद ऑस्ट्रिया ने कार्लोफ़चा संधि के उल्लंघन का दावा करके वेनिस से गठबंधन संधि हस्ताक्षरित की; राजकुमार यूजीन ने वज़ीर-ए आज़म को लिखे पत्र में वेनिस से लिए स्थानों की वापसी माँगी। दावुतपाशा शिविर की मंत्रणा में वज़ीर-ए आज़म अली पाशा के दबाव से ऑस्ट्रिया पर युद्ध घोषित किया गया और इसके लिए शेख़ुल-इस्लाम से फ़तवा लिया गया।", "4a2089d7"]},
"OLAYLAR_EK5:1716-04-24:0":{"b": ["वज़ीर-ए आज़म अली पाशा ऑस्ट्रिया अभियान पर निकले", "2fbdce42"], "d": ["ऑस्ट्रिया पर युद्ध घोषित होने के बाद सेरदार-ए एकरम अली पाशा 100.000 से अधिक की सेना के साथ ऑस्ट्रिया अभियान पर निकले; बेड़ा उसी गर्मी कोर्फ़ू की ओर मुड़ा। सेना बेलग्रेड से वारादिन की ओर कूच करेगी और अगस्त के आरंभ की पराजय में वज़ीर-ए आज़म शहीद होंगे।", "02a5590b"]},
"OLAYLAR_EK5:1716-08-05:0":{"b": ["वारादिन (पेत्रोवारादिन) पराजय — दामाद अली पाशा की शहादत", "265c1d81"], "d": ["बेलग्रेड के रास्ते डैन्यूब पार करने वाली ऑटोमन सेना राजकुमार यूजीन की कमान की ऑस्ट्रियाई सेनाओं से वारादिन के सामने मिली; पहले हमले में येनिचेरी के आक्रमण ने शत्रु की खाइयों को दबाया तो भी घुड़सवार पार्श्व के ढहने से पंक्तियाँ बिखर गईं। वज़ीर-ए आज़म सिलाहदार दामाद अली पाशा माथे में गोली लगने से शहीद हुए, शिविर और तोपख़ाना पूरी तरह शत्रु के हाथ चला गया। ऑटोमन वक़ाइयनामों के 'वारादिन वर्ष' कहकर याद करने वाली यह पराजय तेमेश्वार की और अगले वर्ष बेलग्रेड की हानि की ओर जाने वाली शृंखला की पहली कड़ी थी।", "ad21a2c3"]},
"OLAYLAR_EK5:1716-08-20:0":{"b": ["कोर्फ़ू घेराबंदी का विफलता में समाप्त होना", "b2aa7011"], "d": ["मोरिया सेरआस्कर कारा मुस्तफ़ा पाशा ने स्थल से, कप्तान-ए दरया जानिम होजा मेहमेद पाशा ने बेड़े से समुद्र की ओर से कोर्फ़ू पर ज़ोर डाला; द्वीप वेनिस का एड्रियाटिक का कुंजी अड्डा था। किंतु दुर्ग की अत्यंत सशक्त क़िलेबंदी, वेनिस बेड़े द्वारा लाई गई कुमक और डैन्यूब मोर्चे से आई पराजय की ख़बरें घेराबंदी उठाने का कारण बनीं। कोर्फ़ू के न लिए जाने ने मोरिया की पुनर्विजय से उठे उत्साह को बुझा दिया और युद्ध का गुरुत्व-केंद्र हंगरी की ओर खिसका दिया।", "4589579c"]},
"OLAYLAR_EK5:1716-10-13:0":{"b": ["तेमेश्वार (तिमिशोआरा) का ऑस्ट्रिया के हाथ जाना", "27fe1365"], "d": ["वारादिन की पराजय के बाद राजकुमार यूजीन सीधे तेमेश्वार पर चढ़े और दुर्ग चालीस दिन से अधिक चली घेराबंदी के अंत में समझौते से समर्पित हुआ। 1552 में कानूनी काल में जीता गया और 164 वर्ष तक बेयलरबेयिलिक का केंद्र रहकर हंगरी रक्षा का पूर्वी स्तंभ माना जाने वाला नगर इस तरह हाथ से निकल गया। तेमेश्वार के पतन से बनात क्षेत्र पूरा ऑस्ट्रिया के पास चला गया और ऑटोमन सीमा डैन्यूब के दक्षिण में धकेली गई। उसी तिथि को ऑटोमन से हैब्सबर्ग को गए अन्य स्थान: चाकोवार, फ़ाचेत और करानशेबेश (Caransebeş) — तेमेश्वार प्रांत के हस्तांतरण के साथ (TDV तिमिशोआरा; स्थान स्तर पर दिन स्रोत में नहीं है, जिस केंद्र से वे जुड़े थे उसकी तिथि को आधार माना गया; अनुमानित जानकारी)।", "e77e6790"]},
"OLAYLAR_EK5:1716-11-16:0":{"b": ["हराम (येनी पालंका) दुर्ग का ऑस्ट्रिया को समर्पण — बनात का डैन्यूब तट हाथ से निकला", "38ee4c6d"], "d": ["तेमेश्वार के पतन के बाद बनात के शेष भाग को लेने को नियुक्त ऑस्ट्रियाई घुड़सवार जनरल मेर्सी 14 नवंबर को डैन्यूब तट के हराम (येनी पालंका) पर चढ़े; 16 नवंबर को दुर्ग पर पहुँचने पर 200 की ऑटोमन चौकी ने श्वेत ध्वज उठाकर निर्बाध हटने की शर्त पर समर्पण किया। इस तरह 1552 से ऑटोमन हाथ के दक्षिणी बनात की डैन्यूब पंक्ति भी ऑस्ट्रिया के पास चली गई। उसी तिथि को ऑटोमन से हैब्सबर्ग को गया अन्य स्थान: वेर्शेच — हराम की तिथि को आधार माना गया (Bánlaky 0019/1703; अनुमानित जानकारी)।", "133a6bf9"]},
"OLAYLAR_EK5:1718-07-21:0":{"b": ["पासारोफ़चा संधि — मोरिया पाया, बेलग्रेड और बनात खोए", "d46aa216"], "d": ["वेनिस से मोरिया वापस लिया जा चुका था, किंतु युद्ध में उतरे ऑस्ट्रिया ने पेत्रोवारादिन और बेलग्रेड की विजयों के साथ वार्ता की मेज़ पर बढ़त पाई। इंग्लैंड और हॉलैंड की मध्यस्थता में हस्ताक्षरित संधि ने मोरिया को ऑटोमन में रखा, इसके बदले बेलग्रेड के साथ उत्तरी सर्बिया, बनात और छोटा वलाचिया ऑस्ट्रिया को छोड़े गए; TDV के शब्दों में 'उत्तरी बोस्निया पूरी तरह ऑस्ट्रिया को छोड़ा गया है' — सावा तट के बोस्निया दुबिचा और बोस्निया ब्रोद जैसे दुर्ग मानचित्र में इस दिन से ऑस्ट्रिया को चले जाते हैं (निश्चित सीमा आयुक्तों ने एक-एक करके खींची, TDV इन दुर्गों को नाम से नहीं गिनता); वेनिस ने आयोनियन तट के प्रेवेज़ा और चुहा जैसे मोर्चे बनाए रखे। उसी दिन हस्ताक्षरित व्यापार अहदनामे से ऑस्ट्रियाई माल पर लिया सीमा-शुल्क पाँच प्रतिशत से तीन प्रतिशत किया गया। संधि ने ऑटोमन राज्य के मध्य यूरोप में पीछे हटने को पंजीकृत करते हुए सत्ताईस वर्ष की शांति खोली जिसने लाले काल (1718-1730) की ज़मीन तैयार की: नेवशेहिरली दामाद इब्राहीम पाशा के शासन में पहला ऑटोमन छापाख़ाना (1727, इब्राहीम मुतेफ़र्रिका), अनुवाद दल, चेचक टीके के अवलोकन और नया सराय-सांस्कृतिक जीवन इन्हीं शांति वर्षों की देन है। उसी दिन हाथ बदलने वाले अन्य स्थान: क्राइओवा (Craiova), रिमनिक (Râmnicu Vâlcea) और तुर्नू सेवेरिन (छोटा वलाचिया/ओल्तेनिया, ऑटोमन से ऑस्ट्रिया को) तथा आयामावरा (लेफ़कादा) (ऑटोमन से वेनिस को; TDV आयामावरा: 1718 में पासारोफ़चा संधि से द्वीप वेनिस को छोड़ा गया)। छोटे वलाचिया में तिर्गु जिउ भी ऑस्ट्रिया को; वोनित्सा (वोनिचे, TDV पासारोफ़चा संधि) और चुहा द्वीप (किथिरा, TDV चुहा द्वीप: पासारोफ़चा की तीसरी धारा) वेनिस को जाते हैं।", "60fce52c"]},
"OLAYLAR_EK5:1723-06-15:0":{"b": ["पूर्वी अभियान: तिफ़्लिस का लिया जाना और ईरान युद्ध का आरंभ", "78343dc2"], "d": ["सफ़वी राज्य के अफ़ग़ान आक्रमण से ढहने और रूस के कैस्पियन तटों पर उतरने पर ऑटोमन राज्य ने ख़ालीपन के पूरी तरह रूसी प्रभाव में चले जाने से बचने के लिए पूर्व की ओर सेना भेजी। तिफ़्लिस लेकर जॉर्जिया ऑटोमन प्रशासन से जोड़ा गया; इसके बाद गांजा, येरेवान और नख़चिवान की ओर प्रगति जारी रही। लाले काल की शांतिपूर्ण छवि के पीछे चलाया गया यह अभियान तेरह वर्ष चलने और अंत में जीते गए हर स्थान के लौटाए जाने से समाप्त होने वाले लंबे पूर्वी अभियान का आरंभ बना।", "5c412d91"]},
"OLAYLAR_EK5:1723-08-01:0":{"b": ["1723 ईरान अभियान: शिरवान और जॉर्जिया में प्रवेश", "c81189fc"], "d": ["सफ़वी राज्य के अफ़ग़ान आक्रमण से ढहने पर, रूस के कैस्पियन तटों पर उतरने को रोकने के आधार पर पूर्व की ओर अभियान खुला। एरज़ुरुम सेना जॉर्जिया होकर तिफ़्लिस और शिरवान शाखा शमाख़ी में दाख़िल हुई और एक सौ तीस वर्ष पहले खोई भूमि वापस ली। यह अभियान ऑटोमन की कॉकेशस में अंतिम बड़ी प्रगति रहा।", "9f84acd9"]},
"OLAYLAR_EK5:1723-10-01:0":{"b": ["किरमानशाह पर अधिकार", "03d3f08a"], "d": ["बग़दाद के वाली हसन पाशा ने अक्तूबर 1723 में, जब सफ़वी राज्य बिखर रहा था, किरमानशाह पर क़ब्ज़ा कर लिया।", "83cd686f"]},
"OLAYLAR_EK5:1724-06-24:0":{"b": ["इस्तांबुल मुक़ासेमेनामे — ईरान का रूस से बँटवारा", "fce8eec2"], "d": ["ध्वस्त सफ़वी देश पर ऑटोमन और रूस के आमने-सामने आने से बचने के लिए फ़्रांसीसी राजदूत की मध्यस्थता से बँटवारा संधि हस्ताक्षरित हुई। कैस्पियन सागर के पश्चिमी और दक्षिणी तट रूस को, जॉर्जिया, शिरवान, अज़रबैजान और पश्चिमी ईरान के नगर ऑटोमन राज्य को छोड़े गए। काग़ज़ पर बड़े लाभ जैसा दिखता यह बँटवारा शीघ्र ही नादिर शाह के उदय से वस्तुतः अमान्य हो जाने वाला था। संधि के अनुसार शाबरान और मुश्कूर जैसी शिरवान की उपजाऊ भूमि रूस की ओर छोड़ी गई (Çaycıoğlu, DergiPark)।", "7b0b411b"]},
"OLAYLAR_EK5:1724-08-11:0":{"b": ["नख़चिवान का लिया जाना", "bdf14d0a"], "d": ["अरस के किनारे बढ़ती ऑटोमन सेनाओं ने नख़चिवान और ओर्दूबाद को लिया; जुल्फ़ा भी नख़चिवान लिवा में सम्मिलित हुआ। नगर, ईरान के उत्तर-पश्चिमी द्वार के रूप में नवस्थापित येरेवान प्रांत से जोड़ा गया। इस तरह ऑटोमन सीमा कानूनी काल की सबसे पूर्वी रेखा तक फिर पहुँची।", "9e602879"]},
"OLAYLAR_EK5:1724-08-31:0":{"b": ["हमेदान की विजय", "e1339a97"], "d": ["करमानशाह से पूर्व की ओर बढ़ी सेना ने ईरान पठार की पश्चिमी दहलीज़ के हमेदान को लंबी घेराबंदी के बाद लिया। नगर, ऑटोमन सेनाओं के इराक़ैन अभियान के बाद से पहुँच पाए सबसे पूर्वी बिंदु इस्फ़हान मार्ग का अंतिम बड़ा पड़ाव था। उसी वर्ष रूस से हस्ताक्षरित इस्तांबुल मुकावेलेनामे ने बिखरे ईरान के ऑटोमन और रूस के बीच बँटवारे को काग़ज़ पर उतारा।", "81552031"]},
"OLAYLAR_EK5:1724-10-03:0":{"b": ["येरेवान की पुनर्विजय", "88acabef"], "d": ["नब्बे दिन चली कठिन घेराबंदी के बाद अरस घाटी का कुंजी दुर्ग येरेवान फिर ऑटोमन प्रशासन में गया। 1583 में बनाया और 1604 में खोया दुर्ग इस बार अधिक सशक्त चौकी के साथ सुदृढ़ किया गया। घेराबंदी की लंबाई ऑटोमन सेना के अब आसानी से आगे न बढ़ने का संकेत थी। कार्पी (उचकिलिसे), शेरूर, माकू और शुरेगेल नाहिये भी येरेवान प्रांत से जोड़े गए।", "a989b1eb"]},
"OLAYLAR_EK5:1725-07-28:0":{"b": ["तबरेज़ का लिया जाना — अज़रबैजान पर अधिकार", "e502a4f7"], "d": ["एक वर्ष पहले के विफल प्रयास के बाद फिर घेरा गया तबरेज़, गली-गली चली कठिन लड़ाई के बाद ऑटोमन सेना को समर्पित हुआ। तबरेज़ प्रांत से जुड़े मरंद, मराग़ा और सोवुकबुलाक (महाबाद) भी ऑटोमन प्रशासन में आए। उसी वर्ष लोरी, गांजा, अर्दबील और ख़ुर्रमाबाद भी लिए जाकर इस्तांबुल मुक़ासेमेनामे से ऑटोमन के हिस्से आई भूमियाँ वस्तुतः क़ब्ज़े में ले ली गईं। पूर्व में पहुँची यह विशालता फ़रहाद पाशा संधि काल के बाद की सबसे आगे की सीमा थी; किंतु इसे थामे रखना सेना और राजकोष पर भारी बोझ डाल गया।", "e0953563"]},
"OLAYLAR_EK5:1725-09-04:0":{"b": ["गांजा की विजय — कॉकेशस अभियान का अंत", "875bca7a"], "d": ["कॉकेशस अभियान का अंतिम लक्ष्य गांजा, कुर और अरस के बीच के काराबाग़ के केंद्र के रूप में अपने हाथ में लिया गया। शिरवान, येरेवान, नख़चिवान और गांजा रेखा के पूर्ण होने से ऑटोमन राज्य कॉकेशस में 1590 की विशालता तक पहुँचा। किंतु यह उपलब्धि अल्पजीवी रही: नादिर शाह का उदय दस वर्ष में पूरे क्षेत्र को वापस ले लेगा।", "265db7e0"]},
"OLAYLAR_EK5:1727-10-04:0":{"b": ["हमेदान संधि — पश्चिमी ईरान का ऑटोमन में मिलना", "94a29dc3"], "d": ["अफ़ग़ान शासक अशरफ़ शाह से हस्ताक्षरित संधि से चार वर्ष चला युद्ध समाप्त हुआ और ऑटोमन राज्य के क़ब्ज़े वाली पश्चिमी ईरान की भूमि विधिक रूप से मान्य हुई। अशरफ़ शाह ने बदले में ऑटोमन पदीशाह की ख़िलाफ़त स्वीकार की और ईरान में ख़ुतबे को पदीशाह के नाम से पढ़वाने का ज़िम्मा लिया। यह कूटनीतिक विजय अल्पजीवी रही; नादिर शाह का 1730 में आरंभ किया जवाबी आक्रमण संधि की उपलब्धियों को कुछ वर्षों में मिटा देने वाला था।", "fd0174b9"]},
"OLAYLAR_EK5:1731-01-01:0":{"b": ["हेकीमओग़्लु अली पाशा ने रूमिये लिया", "eac7f64d"], "d": ["ईरान अभियान में हेकीमओग़्लु अली पाशा ने पहले उर्मिया (रूमिये) को, फिर ऑटोमन के लिए ख़ाली कराए गए तबरेज़ को 15 नवंबर 1731 को लिया। TDV उर्मिया के लिए जाने का दिन नहीं देता; केवल वर्ष और तबरेज़ से पहले आना ज्ञात है।", "f99d74f9"]},
"OLAYLAR_EK5:1732-01-08:0":{"b": ["अहमद पाशा संधि — पश्चिमी ईरान के बड़े भाग की वापसी", "590d839f"], "d": ["नादिर शाह की मेलायिर में जीती विजय और लगातार आए ईरानी आक्रमणों पर बग़दाद के वाली अहमद पाशा ने केंद्र से पूछे बिना शांति-पाठ हस्ताक्षरित कर दिया। संधि के अनुसार अरस नदी सीमा मानी गई; हमेदान, करमानशाह, अर्दलान, अर्दबील और तबरेज़ जैसे पश्चिमी ईरान के नगर ईरान को लौटाए गए, गांजा और तिफ़्लिस ऑटोमन में रहे। इस्तांबुल में रोष से ग्रहण किया गया यह पाठ नादिर शाह को भी अपर्याप्त लगा और 1732 का वर्ष पूरा होने से पहले ही युद्ध फिर भड़क उठा। मानचित्र पर कोतुर भी, जिसका हश्र ख़ोय जैसा ही माना गया है, इस दिन ऑटोमन से सफ़वी को गया दिखाया गया है (TDV ख़ोय; कोतुर का अपना दिन स्रोत में नहीं है — अनुमानित जानकारी)।", "fc358d4e"]},
"OLAYLAR_EK5:1732-07-01:0":{"b": ["वहरान (ओरान) का फिर स्पेन के हाथ जाना", "20485027"], "d": ["स्पेन के राजा फ़ेलिपे पंचम के भेजे बड़े उतरने वाले बेड़े ने काउंट मोंतेमार की कमान में वहरान के सामने आकर अल्जीरिया ओजाक की सेनाओं को पराजित किया और नगर वापस ले लिया। चौबीस वर्ष पहले जीता बंदरगाह साठ वर्ष फिर स्पेनी चौकी के हाथ में रहेगा। पश्चिमी भूमध्यसागर में पश्चिमी ओजाकों की शक्ति की सीमाएँ दिखाने वाली यह हानि केवल 1792 में वहरान की निश्चित विजय से पूरी की जा सकी।", "b255a8da"]},
"OLAYLAR_EK5:1733-05-01:0":{"b": ["हुम्बराजी ओजाक का यूरोपीय पद्धति में सुधार और हुम्बराहाने की स्थापना", "d980cf2a"], "d": ["ऑटोमन सेवा में आए फ़्रांसीसी मूल के हुम्बराजी अहमद पाशा ने वज़ीर-ए आज़म हेकीमओग़्लु अली पाशा के समर्थन से हुम्बराजी ओजाक को वेतनभोगी और यूरोपीय ढंग से संगठित टुकड़ी बना दिया। बोस्निया से भर्ती किए तीन सौ सैनिकों को गणित और ज्यामिति पर आधारित नियमित प्रशिक्षण दिया गया; संगठन, उपकरण और सेवानिवृत्ति के लिए नई नियमावलियाँ तैयार की गईं, आधुनिक तकनीक से सौ हुम्बरा तोपें और पचास हज़ार हुम्बरा बनाए गए। हुम्बराहाने, जहाँ ज्यामिति पढ़ाई जाती थी, ऑटोमन में आधुनिक सैन्य इंजीनियरी शिक्षा का पहला केंद्रक माना जाता है।", "181b7161"]},
"OLAYLAR_EK5:1736-06-24:0":{"b": ["अहमद तृतीय का निधन", "455f7fba"], "d": ["पत्रोना हलील विद्रोह से 1730 में गद्दी से उतारे गए अहमद तृतीय ने जीवन के अंतिम छह वर्ष तोपकापी सराय के पदच्युत पदीशाहों के लिए निर्धारित कक्ष में बिताए और तिरेसठ वर्ष की आयु में चल बसे। बाहचेकापी में येनिजामी के निकट दादी तुरहान सुल्तान के मक़बरे में दफ़नाए गए।", "00cc8767"]},
"OLAYLAR_EK5:1736-09-01:0":{"b": ["इस्तांबुल संधि — दक्षिणी कॉकेशस का ईरान को छोड़ा जाना", "8c205aab"], "d": ["चार वर्ष चला दूसरा ईरान युद्ध, अरपाचाय पराजय तथा गांजा और तिफ़्लिस की हानि के बाद हस्ताक्षरित संधि से समाप्त हुआ। ऑटोमन राज्य 1723 से जीते सभी दक्षिणी कॉकेशस और पश्चिमी ईरान की भूमि से हट गया, सीमा 1639 की क़स्र-ए शीरीन रेखा पर लौटी। तेरह वर्ष के पूर्वी अभियानों से भारी वित्तीय बोझ और ख़ाली राजकोष बचा; इसके बदले रूस से आरंभ नए युद्ध के लिए पूर्वी मोर्चे का बंद होना जीवनदायी लाभ था।", "bcb0cbe8"]},
"OLAYLAR_EK5:1737-07-11:0":{"b": ["ओज़ू (ओचाकोव) दुर्ग का रूसियों के हाथ गिरना", "f93e61f3"], "d": ["मार्शल मिनिख़ की कमान की रूसी सेना ने नीपर के मुहाने के ओज़ू दुर्ग को घेरा; बारूदख़ाने के फटने से रक्षा ढह गई और दुर्ग भारी जनहानि के साथ गिरा। काला सागर के उत्तर-पश्चिमी तट की कुंजी माने जाने वाले ओज़ू के हाथ से निकलने ने क्रीमिया का मार्ग रूसियों के लिए खोला और इस्तांबुल में बड़ी घबराहट पैदा की। दुर्ग अगले वर्ष महामारी और रसद-कठिनाई के कारण रूसियों द्वारा ख़ाली किए जाकर फिर ऑटोमन के पास जाएगा।", "479e0090"]},
"OLAYLAR_EK5:1737-08-04:0":{"b": ["बान्यालुका विजय — बोस्निया का बचाव", "f603865a"], "d": ["ऑस्ट्रियाई सेनाओं के बोस्निया में घुसकर बान्यालुका को घेरने पर बोस्निया वाली हेकीमओग़्लु अली पाशा स्थानीय जनता से जुटाई सेना के साथ सहायता को पहुँचे और संख्या में श्रेष्ठ शत्रु को भारी पराजय दी। इस विजय ने ऑस्ट्रिया की बोस्निया पर क़ब्ज़े की योजना को पहले ही क़दम पर ढहा दिया और प्रांत का उत्तर पूरी तरह वापस लिया गया। बान्यालुका 1683 के बाद ऑस्ट्रिया के सामने लगातार पीछे हट रही ऑटोमन सेना के मनोबल को सुधारने वाले मोड़ों में से एक बना।", "81c1850e"]},
"OLAYLAR_EK5:1739-07-22:0":{"b": ["हिसारजिक (ग्रोत्स्का) विजय — बेलग्रेड मार्ग का खुलना", "2101cdff"], "d": ["बेलग्रेड की रक्षा के लिए बढ़ती ऑस्ट्रियाई सेना, डैन्यूब तट के संकरे दर्रे में घात में फँसाई जाकर दिन भर चली लड़ाई में भारी हानि उठा गई। मार्शल वालिस की सेनाएँ अव्यवस्थित ढंग से बेलग्रेड की ओर हटीं तो ऑटोमन सेना दुर्ग के सामने आ डटी और घेराबंदी आरंभ की। हिसारजिक, कार्लोफ़चा के बाद ऑस्ट्रिया के सामने जीती सबसे निश्चित खुली विजय थी और सीधे बेलग्रेड की वापसी का कारण बनी।", "5811893a"]},
"OLAYLAR_EK5:1739-10-03:0":{"b": ["निश संधि — रूस से शांति, आज़ाक का तटस्थीकरण और क्रीमियाई आक्रमणों का रुकना", "674f974e"], "d": ["ऑस्ट्रिया के बेलग्रेड में शांति पर राज़ी होने से अकेले पड़े रूस को, फ़्रांसीसी राजदूत विलनव की मध्यस्थता से, युद्ध समाप्त करना पड़ा। आज़ाक दुर्ग की क़िलेबंदियाँ ध्वस्त करके क्षेत्र को दोनों राज्यों के बीच तटस्थ भूमि घोषित किया गया; रूस ने काला सागर में युद्ध या व्यापारी जहाज़ न रखने की शर्त स्वीकार की। इस तरह रूस के समुद्र तक पहुँचने का लक्ष्य एक पीढ़ी और टल गया और ऑटोमन राज्य XVIII. शताब्दी में अंतिम बार मेज़ से लाभ लेकर उठा।", "7ca0d614"]},
"OLAYLAR_EK5:1739-12-12:0":{"b": ["ओज़ू रूसी क़ब्ज़े से लौटा: 1739 की शांति से दुर्ग ध्वस्त होने के बाद सौंपा गया", "7ecc2bef"], "d": ["रूसियों ने ओज़ू को 11 जुलाई 1737 को लिया था। 1739 में रूस से हुई शांति के अनुसार दुर्ग की क़िलेबंदियाँ ध्वस्त होने के बाद उसे फिर ऑटोमनों को सौंपा गया; ऑटोमन ने ओज़ू को यास संधि से पहले 1788 तक अपने हाथ में रखा।", "39ee6708"]},
"OLAYLAR_EK5:1743-10-23:0":{"b": ["मूसल रक्षा — नादिर शाह का खदेड़ा जाना", "c03ffbc1"], "d": ["किरकुक और इरबिल लेकर मूसल के सामने आए नादिर शाह ने चालीस दिन नगर पर तोप बरसाई और लगातार आम हमले किए। वाली हुसैन पाशा अल-जलीली की नगरवासियों को भी शस्त्र देकर चलाई रक्षा ने ईरानी सेना को भारी हानि के साथ घेराबंदी उठाने को विवश किया। मूसल के टिकने ने पूरे इराक़ के हाथ से निकलने को रोका और जलीली परिवार के नगर में प्रभाव को एक शताब्दी दृढ़ किया।", "b9f67e29"]},
"OLAYLAR_EK5:1744-01-01:0":{"b": ["दिरइया गठबंधन — नज्द में पहली सऊदी अमीरात की स्थापना", "188751bf"], "d": ["उयैना से निकाले गए आलिम मुहम्मद बिन अब्दुलवहाब को दिरइया में संरक्षण देने वाले अमीर मुहम्मद बिन सऊद ने उनके साथ राजनीतिक सत्ता को धार्मिक आह्वान की सेवा में लगाने वाला गठबंधन किया। इस समझौते ने सऊद परिवार के लिए नया इतिहास आरंभ किया और नज्द की बिखरी नख़लिस्तान-अमीरातों को एक आंदोलन के गिर्द इकट्ठा किया। आधी शताब्दी में कर्बला, मक्का और मदीना तक पहुँचने वाली यह शक्ति ऑटोमन राज्य को हिजाज़ में अपने आधिपत्य की रक्षा करने को बाध्य करेगी।", "6843c874"]},
"OLAYLAR_EK5:1746-09-04:0":{"b": ["केरदेन संधि — ऑटोमन-ईरान युद्धों का अंत", "1d3a919e"], "d": ["चार वर्ष चले अंतिम युद्ध के बाद हस्ताक्षरित संधि से 1639 की क़स्र-ए शीरीन सीमा ज्यों की त्यों नवीकृत हुई; दोनों पक्ष भूमि-लाभ न पा सके। नादिर शाह की जाफ़री मत को पाँचवें मज़हब के रूप में मान्यता दिए जाने की आग्रही माँग निष्फल रही, इसके बदले ईरानी हाजियों को स्वतंत्र रूप से हज करने और परस्पर दूत आदान-प्रदान का निर्णय हुआ। दो शताब्दी से अधिक चले ऑटोमन-ईरान युद्ध इस तरह वस्तुतः बंद हुए; यह सीमा आज तक बड़े पैमाने पर बनी हुई है।", "2a089331"]},
"OLAYLAR_EK5:1754-12-13:0":{"b": ["महमूद प्रथम की मृत्यु और उस्मान तृतीय का राज्यारोहण", "30203700"], "d": ["चौबीस वर्ष के शासन में बेलग्रेड संधि से खोई भूमि वापस लेने वाले और हुम्बराजी ओजाक सुधार का समर्थन करने वाले महमूद प्रथम जुमे की सलामी से लौटते हुए चल बसे। उनकी जगह अट्ठावन वर्ष की आयु तक कफ़स-जीवन जी चुके भाई उस्मान तृतीय बैठे। संक्षिप्त और बेचैन शासन आरंभ हुआ; तीन वर्ष में छह वज़ीर-ए आज़म बदलने वाले उस्मान तृतीय के काल में राज्य कार्यों में स्पष्ट ठहराव छाया रहा।", "8bdf7c4e"]},
"OLAYLAR_EK5:1757-10-30:0":{"b": ["उस्मान तृतीय की मृत्यु और मुस्तफ़ा तृतीय का राज्यारोहण", "3ac10f85"], "d": ["तीन वर्ष के शासन के बाद उस्मान तृतीय की मृत्यु पर गद्दी पर सुधार विचारों के लिए खुले और राज्य कार्यों में निकट रुचि दिखाने वाले मुस्तफ़ा तृतीय बैठे। नए पदीशाह ने वज़ीर-ए आज़म कोजा रागिब पाशा के अनुभव पर भरोसा करके वित्त को सुधारने और सेना को नया करने का प्रयास किया; बैरन द तोत के द्रुत तोपची इसी काल में स्थापित हुए। किंतु 1768 में छिड़ा रूसी युद्ध सत्रह वर्ष के शासन की सभी उपलब्धियों को छाया में डालने वाला था।", "2d13aff2"]},
"OLAYLAR_EK5:1768-10-08:0":{"b": ["रूस पर युद्ध घोषणा — बाल्टा घटना और 1768-1774 युद्ध का आरंभ", "9c6aabe0"], "d": ["पोलैंड के बार संघ का पीछा करती रूसी और कज़ाक टुकड़ियों के ऑटोमन सीमा के बाल्टा क़स्बे पर धावा बोलकर उसे जलाने पर दीवान ने युद्ध का निर्णय लिया, रूसी राजदूत येदिकुले में बंदी बनाया गया। गंभीर सैन्य तैयारी के बिना और छह माह पहले घोषित करके छेड़ा गया युद्ध आरंभ से ही बुरा चला। छह वर्ष चलने वाला यह संघर्ष चेशमे आक्रमण, कार्तल पराजय और क्रीमिया के क़ब्ज़े से ऑटोमन इतिहास की सबसे भारी पराजय-शृंखलाओं में से एक बनने वाला था।", "18bfa4d5"]},
"OLAYLAR_EK5:1769-09-20:0":{"b": ["होतिन दुर्ग का रूसियों के हाथ जाना", "66d43ea4"], "d": ["राजकुमार गोलित्सिन की कमान की रूसी सेना के दो प्रयास खदेड़े जा चुके थे; कामानिचे और होतिन के बीच वज़ीर-ए आज़म की पराजय पर सेना पीछे हटी और रक्षकों ने दुर्ग ख़ाली कर दिया। डैन्यूब के उत्तर के सबसे सशक्त ऑटोमन क़िले का बिना प्रतिरोध हाथ से निकलना वलाचिया और बोग़दान के द्वार रूसियों के लिए खोल गया। दोनों रियासतें उसी वर्ष अधिकृत हुईं; होतिन केवल 1774 में क्यूचुक कायनार्जा संधि से वापस लिया जा सका।", "1d0b219f"]},
"OLAYLAR_EK5:1770-08-01:0":{"b": ["कार्तल (काहुल) मैदान की पराजय", "6f408eaf"], "d": ["चेशमे में बेड़े के जलाए जाने के तीन सप्ताह बाद, डैन्यूब तट की मुख्य ऑटोमन सेना कार्तल मैदान में मार्शल रुम्यांत्सेव की संख्या में कहीं छोटी किंतु अनुशासित टुकड़ियों के सामने बिखर गई। शिविर, साज़-सामान और सैकड़ों तोपें शत्रु के हाथ आईं; भागती टुकड़ियों ने डैन्यूब पार करते हुए भारी हानि उठाई। उसी गर्मी में बेड़े और स्थल सेना दोनों का विनाश किली, अक़किरमान, इस्माईल और बेंदेर के एक-एक करके गिरने तथा क्रीमिया के क़ब्ज़े का कारण बना।", "0fd97052"]},
"OLAYLAR_EK5:1771-07-01:0":{"b": ["क्रीमिया प्रायद्वीप पर रूसी क़ब्ज़ा", "217837b0"], "d": ["एक वर्ष पहले बुजाक पर क़ब्ज़ा करने वाली रूसी सेनाओं ने राजकुमार दोल्गोरुकोव की कमान में ओर कापी को पार करके पूरे क्रीमिया प्रायद्वीप पर आक्रमण किया। ख़ान गद्दी से उतारे गए, रूस-समर्थक साहिब गिराय को सिंहासन पर बिठाकर ख़ानत को ऑटोमन से काटने की दिशा में पहला क़दम उठाया गया। तीन शताब्दी से ऑटोमन की उत्तरी ढाल रहे क्रीमिया के हाथ से निकलने ने 1774 में स्वतंत्रता और 1783 में सीधे विलय की प्रक्रिया का आरंभ किया।", "952270d8"]},
"OLAYLAR_EK5:1774-01-21:0":{"b": ["मुस्तफ़ा तृतीय की मृत्यु और अब्दुलहमीद प्रथम का राज्यारोहण", "42cba8e2"], "d": ["रूसी युद्ध के सबसे संकट भरे क्षण में चल बसे मुस्तफ़ा तृतीय की जगह, तैंतालीस वर्ष सराय के कफ़स में बिता चुके भाई अब्दुलहमीद प्रथम उनचास वर्ष की आयु में गद्दी पर बैठे। राज्य के सबसे कठिन कालों में से एक को सँभालने वाले नए पदीशाह को उसी वर्ष हस्ताक्षरित होने वाली क्यूचुक कायनार्जा संधि की भारी शर्तों का सामना करना पड़ा। पंद्रह वर्ष का शासन क्रीमिया की हानि और नए रूसी युद्ध में बीता, 1789 में ओज़ू के गिरने की ख़बर पढ़ते समय आए पक्षाघात से समाप्त होने वाला था।", "05963836"]},
"OLAYLAR_EK5:1774-06-25:0":{"b": ["कोज़लुजा पराजय — क्यूचुक कायनार्जा की ओर ले जाने वाली हार", "8e0542f9"], "d": ["शुम्नू के सामने जुटी ऑटोमन सेनाएँ सुवोरोव और कामेंस्की की संयुक्त टुकड़ियों से कोज़लुजा में पराजित हुईं और सेना का बड़ा भाग बिखर गया। इस पराजय से बाल्कन में प्रतिरोध करने वाला बल नहीं बचा; रूसी अग्रदल ने शुम्नू को घेरा और वज़ीर-ए आज़म का मुख्यालय ख़तरे में आ गया। एक माह पूरा होने से पहले क्यूचुक कायनार्जा में वार्ता की मेज़ पर बैठना और असाधारण भारी शर्तों को स्वीकार करना सीधे इस पराजय का परिणाम है।", "6721d6e3"]},
"OLAYLAR_EK5:1775-05-07:0":{"b": ["बुकोविना (उत्तरी बोग़दान) का ऑस्ट्रिया को छोड़ा जाना", "190f9caa"], "d": ["क्यूचुक कायनार्जा से उपजी दुर्बलता का लाभ उठाने वाले ऑस्ट्रिया ने बोग़दान और ट्रांसिल्वेनिया के बीच संपर्क देने वाला बुकोविना क्षेत्र माँगा और बिना युद्ध में उतरे, धमकी और रिश्वत से यह भूमि पा ली। होतिन के दक्षिण-पश्चिम के इस उपजाऊ और रणनीतिक क्षेत्र की हानि ने बोग़दान वोइवोडेशिप को वस्तुतः दो भागों में बाँट दिया। एक भी गोली चले बिना हुआ यह त्याग ऑटोमन राज्य के अब निवारक क्षमता खो देने के सबसे स्पष्ट संकेतों में से एक माना गया। 1775 में बुकोविना के त्याग से सुचेवा और चेर्नोविट्ज़ ऑस्ट्रिया के पास गए (दिन का सत्यापन नहीं हो सका)।", "0db811a5"]},
"OLAYLAR_EK5:1776-04-16:0":{"b": ["बसरा का ईरानी क़ब्ज़े में जाना", "0161e709"], "d": ["ज़ंद शासक करीम ख़ान के भाई सादिक़ ख़ान ने एक वर्ष चली घेराबंदी के बाद बसरा ले लिया और ऑटोमन राज्य ने बसरा खाड़ी का अपना सबसे महत्वपूर्ण बंदरगाह खो दिया। क़ब्ज़े ने हिंद व्यापार मार्ग, खजूर और मोती की आय तथा इराक़ की दक्षिणी रक्षा को सीधे हिला दिया। नगर केवल 1779 में करीम ख़ान की मृत्यु पर ईरान में उठे गद्दी-झगड़ों के दौरान वापस लिया जा सका।", "838306ba"]},
"OLAYLAR_EK5:1779-03-21:0":{"b": ["आयनालीकवाक़ तनक़ीहनामे — क्रीमिया पर अस्थायी समझौता", "9b3b0468"], "d": ["क्रीमिया ख़ानत की गद्दी पर किसके बैठने पर युद्ध की कगार पर आए दोनों राज्यों ने, फ़्रांस की मध्यस्थता से, आयनालीकवाक़ महल में एक स्पष्टीकरण-पाठ हस्ताक्षरित किया। रूस ने क्रीमिया से अपने सैनिक हटाने, ऑटोमन राज्य ने रूस-समर्थक शाहिन गिराय की ख़ानत को मान्यता देने को स्वीकार किया; पदीशाह के क्रीमिया पर धार्मिक ख़िलाफ़त के अधिकार की पुष्टि हुई। चार वर्ष चलने वाला यह नाज़ुक संतुलन 1783 में रूस के प्रायद्वीप के सीधे विलय से पूरी तरह ढहने वाला था।", "8a428802"]},
"OLAYLAR_EK5:1781-01-01:0":{"b": ["अनापा दुर्ग का निर्माण — कॉकेशस रक्षा रेखा", "be92a80f"], "d": ["क्यूचुक कायनार्जा से क्रीमिया के हाथ से निकलने पर कॉकेशस में ऑटोमन प्रभाव को बचाने के लिए कुबान नदी के मुहाने पर नए दुर्ग का निर्माण आरंभ हुआ। जेनोवी बस्ती के खंडहरों पर बना अनापा, बाज़ार, हम्मामों और ढाई सौ से अधिक दुकानों के साथ शीघ्र चेरकेज़ क़बीलों से संपर्क कराने वाला नगर बन गया। दुर्ग रूस के कॉकेशस में उतरने के विरुद्ध अड़तालीस वर्ष ऑटोमन की सबसे आगे की चौकी बना रहा।", "334a40cb"]},
"OLAYLAR_EK5:1785-04-27:0":{"b": ["वज़ीर-ए आज़म हलील हमीद पाशा की बर्ख़ास्तगी और मृत्युदंड", "c44001ca"], "d": ["अब्दुलहमीद प्रथम ने जिनकी सेवाओं से संतोष कई अवसरों पर जताया था उन सुधारवादी वज़ीर-ए आज़म हलील हमीद पाशा को 31 मार्च 1785 की सुबह के क़रीब अचानक हटाकर गैलीपोली निर्वासित किया गया और उनकी सारी संपत्ति ज़ब्त की गई। पहले उन्हें हबेश प्रांत, जिद्दा संजक और मक्का शेख़ुल-हरम का पद दिया गया; अप्रैल 1785 यात्रा की तैयारी में बोज़जाअदा में बिताते समय इस पद से भी हटाए गए और निकले मृत्युदंड के फ़रमान से जज़ायरली ग़ाज़ी हसन पाशा के आदमियों में से कारा-कहया-ज़ादे अली द्वारा मारे गए। कटा सिर इस्तांबुल भेजा जाकर ओर्ताकापी में प्रदर्शित किया गया। TDV के अनुसार इस अचानक पतन को पदीशाह को गद्दी से उतारकर शहज़ादे सेलिम को बिठाने की साज़िश के आरोप से जोड़ा गया है, किंतु असली कारण क्रीमिया के विलय पर चुप रहने से उपजा आक्रोश, उनके सुधारों से आहत वर्गों की शत्रुता और ग़ाज़ी हसन पाशा का विरोध रहे होंगे।", "6f73b0a5"]},
"OLAYLAR_EK5:1787-08-16:0":{"b": ["रूस पर युद्ध घोषणा — 1787-1792 ऑटोमन-रूसी युद्ध आरंभ हुआ", "3bfb870c"], "d": ["कैथरीन द्वितीय की प्रदर्शन भरी क्रीमिया यात्रा और जॉर्जिया को अपने संरक्षण में लेने पर दीवान ने विलय को पलटने के उद्देश्य से युद्ध का निर्णय लिया और रूसी राजदूत फिर येदिकुले में बंद किया गया। किंतु सेना तैयार नहीं थी, राजकोष ख़ाली था और सहयोगी खोजना निष्फल रहा था। पाँच वर्ष चलने वाला युद्ध ओज़ू के क़त्लेआम से गिरने, इस्माईल की हानि और यास संधि की भारी शर्तों में परिणत होने वाला था।", "80a26d8f"]},
"OLAYLAR_EK5:1788-02-09:0":{"b": ["ऑस्ट्रिया का युद्ध में प्रवेश — दो मोर्चों पर संघर्ष", "ae912290"], "d": ["1781 में रूस के साथ की गई गुप्त संधि के अनुसार ऑस्ट्रियाई सम्राट जोसेफ़ द्वितीय ने उस्मानी राज्य के विरुद्ध युद्ध घोषित कर बेलग्रेड और बोस्निया की ओर कूच किया। उस्मानी सेना को अचानक उत्तर में रूस और पश्चिम में ऑस्ट्रिया के विरुद्ध एक साथ दो मोर्चों पर लड़ना पड़ा। मेहादिया और सेबेश में ऑस्ट्रियाइयों पर मिली जीतों के बावजूद 1789 में बेलग्रेड के हाथ से जाने के साथ पश्चिमी मोर्चा भी ढहने वाला था।", "a1d111a2"]},
"OLAYLAR_EK5:1790-01-31:0":{"b": ["ऑटोमन-प्रशिया गठबंधन", "03b88e51"], "d": ["गद्दी पर बैठते ही यूरोप में सहयोगी खोजने वाले सेलिम तृतीय ने प्रशिया से पारस्परिक सहायता का प्रावधान करने वाली गठबंधन संधि हस्ताक्षरित की; प्रशिया ने रूस और ऑस्ट्रिया पर युद्ध घोषित करने, ऑटोमन राज्य ने क्रीमिया वापस लिए बिना शांति न करने का वचन दिया। यह ऑटोमन इतिहास में किसी यूरोपीय राज्य से हस्ताक्षरित पहला वास्तविक पारस्परिक गठबंधन-पाठ था और शास्त्रीय 'काफ़िरों से गठबंधन नहीं होता' धारणा के त्यागे जाने को दिखाता था। प्रशिया युद्ध में नहीं उतरा, किंतु ऑस्ट्रिया को शांति के लिए विवश करके ज़िश्तोवी संधि का मार्ग खोला।", "de29f327"]},
"OLAYLAR_EK5:1790-12-22:0":{"b": ["इस्माईल दुर्ग का गिरना और क़त्लेआम", "6a296b0c"], "d": ["डैन्यूब डेल्टा के सबसे सशक्त क़िले माने जाने वाले इस्माईल दुर्ग को जनरल सुवोरोव के आयोजित ख़ूनी आम हमले से एक दिन में ले लिया गया; चौकी और नगरवासियों का बड़ा भाग तलवार के घाट उतारा गया। यूरोप में बड़ी गूँज उठाने वाले इस क़त्लेआम ने ऑटोमन जनमत में गहरा आघात पहुँचाया और डैन्यूब रक्षा पंक्ति की रीढ़ तोड़ दी। दुर्ग एक वर्ष बाद यास संधि से वापस लिया जाएगा, किंतु युद्ध का भाग्य तब तक तय हो चुका होगा।", "225351fb"]},
"OLAYLAR_EK5:1791-08-04:0":{"b": ["ज़िश्तोवी संधि — ऑस्ट्रिया मोर्चे का बंद होना", "58741f1d"], "d": ["प्रशिया के दबाव और फ़्रांसीसी क्रांति के ऑस्ट्रिया को पश्चिम में व्यस्त रखने के कारण दोनों राज्य युद्ध-पूर्व सीमाओं को आधार मानकर शांति पर पहुँचे। ऑस्ट्रिया ने अधिकृत बेलग्रेड सहित सभी स्थान लौटाए; ऑटोमन राज्य ने केवल क्रोएशिया सीमा पर छोटे सुधार स्वीकार किए। पश्चिमी मोर्चे के इन शर्तों पर बंद होने ने ऑटोमन राज्य को अपनी सारी शक्ति रूस के विरुद्ध जुटाने में सक्षम किया और यास संधि की हानि को सीमित किया। क्रोएशिया सीमा के इन सुधारों से चेटिन (चेटिनग्राद) और द्रेज़्निक ग्राद ऑटोमन से हैब्सबर्ग को जाते हैं (TDV ज़िश्तोवी संधि; Korić 2016, n. 118, अनुच्छेद 4)। ओरशोवा (पुराना ओरशोवा) अकेला स्थान है जो लौटाया नहीं गया (Bánlaky 0019/1796); मानचित्र में हस्तांतरण के लिए विधिक रूप से इसी दिन को आधार माना गया है (वास्तविक क़ब्ज़ा 16 अप्रैल 1790)।", "5a028ac8"]},
"OLAYLAR_EK5:1792-01-10:0":{"b": ["यास संधि — क्रीमिया की निश्चित हानि और तुर्ला सीमा", "a56fd194"], "d": ["पाँच वर्ष के युद्ध के अंत में हस्ताक्षरित संधि से तुर्ला (द्नीस्तर) नदी सीमा मानी गई; नदी का बायाँ तट रूस को, दायाँ तट ऑटोमन को रहा और ओज़ू तथा उसका आसपास निश्चित रूप से हाथ से निकल गए। ऑटोमन राज्य ने क्रीमिया वापस लेने की आशा पूरी तरह छोड़ दी और 1783 के विलय को विधिक रूप से मान लिया; वलाचिया और बोग़दान दो वर्ष की कर-छूट के साथ लौटाए गए। एक करोड़ बीस लाख क़ुरुश के युद्ध-क्षतिपूर्ति दायित्व को भी स्वीकार करके काला सागर का उत्तर स्थायी रूप से रूस को छोड़ दिया गया। उसी तिथि को शामिल हुए अन्य स्थान: इस्माईल।", "277ee99d"]},
"OLAYLAR_EK5:1792-02-12:0":{"b": ["वहरान (ओरान) का स्पेनियों द्वारा ख़ाली किया जाना और अल्जीरिया को हस्तांतरण", "9f95cee6"], "d": ["1790 के भूकंप में दुर्ग और नगर के बड़े पैमाने पर ढहने पर, तीन शताब्दी से चलाई महँगी चौकी अब न ढो सकने वाले स्पेन ने अल्जीरिया ओजाक से समझौता करके वहरान और मेर्सेलकबीर बिना युद्ध सौंप दिए। इस तरह उत्तरी अफ़्रीका तट का अंतिम यूरोपीय मोर्चा भी समाप्त हुआ। ऑटोमन अल्जीरिया फ़्रांसीसी क़ब्ज़े तक बीतने वाले अड़तीस वर्ष तट के पूरे भाग पर हावी रहा।", "c73636aa"]},
"OLAYLAR_EK5:1795-03-01:0":{"b": ["पज़वंदओग़्लु उस्मान का विदिन में वास्तविक शासन", "0ce70361"], "d": ["निज़ाम-ए जदीद व्यवस्थाओं के विरुद्ध विद्रोह करने वाले पज़वंदओग़्लु उस्मान ने विदिन के वाली को भगाकर नगर ले लिया और डैन्यूब किनारे गहरी खाइयों से क़िलेबंद किया। 1797 में शक्ति के शिखर पर अस्सी हज़ार के क़रीब सेना जुटाकर निग्बोलू, ज़िश्तोवी, रूसचुक, सोफ़िया और निश को अपने नियंत्रण में लिया; स्वयं को विद्रोही नहीं सुधारवादी के रूप में प्रस्तुत किया। बाबे-आली की 1798-1799 की महीनों चली घेराबंदी निष्फल रही और वे 1807 में अपनी मृत्यु तक उत्तरी बुल्गारिया में अर्ध-स्वतंत्र शासन करते रहे।", "b0acf80b"]},
"OLAYLAR_EK5:1795-09-01:0":{"b": ["मुहेंदिसहाने-ए बर्री-ए हुमायूँ का उद्घाटन", "e9a3a34b"], "d": ["निज़ाम-ए जदीद सेना के लिए तोपख़ाना, क़िलेबंदी और मानचित्रकार अधिकारी तैयार करने के लिए हास्कोय में स्थल इंजीनियरी विद्यालय खोला गया; यह 1773 में स्थापित नौसेना इंजीनियरी विद्यालय का स्थल सेना में समकक्ष था। पाठ्यक्रम में बीजगणित, ज्यामिति, यांत्रिकी, क़िलेबंदी और प्रक्षेप्य-विज्ञान पढ़ाए गए, यूरोपीय भाषाओं से गणित और तोपख़ाना ग्रंथों के अनुवाद हुए। तुर्की में आधुनिक इंजीनियरी शिक्षा की जड़ माना जाने वाला यह विद्यालय आज के इस्तांबुल तकनीकी विश्वविद्यालय का आरंभ माना जाता है।", "ff1a8344"]},
"OLAYLAR_EK5:1798-09-09:0":{"b": ["फ़्रांस पर युद्ध घोषणा और रूस-इंग्लैंड से गठबंधन", "80e95bd7"], "d": ["नेपोलियन के मिस्र पर क़ब्ज़े पर ऑटोमन राज्य ने ढाई शताब्दी की पारंपरिक फ़्रांसीसी मित्रता तोड़कर फ़्रांस पर युद्ध घोषित किया। उसी प्रक्रिया में इतिहास में पहली बार रूस से गठबंधन किया और रूसी बेड़े को जलडमरूमध्य से गुज़रकर भूमध्यसागर में निकलने की अनुमति दी; इसके बाद इंग्लैंड से भी गठबंधन हस्ताक्षरित हुआ। इन गठबंधनों से आयोनियन द्वीप फ़्रांसीसियों से लिए गए, किंतु जलडमरूमध्य का किसी विदेशी बेड़े के लिए खुलना भविष्य में भारी क़ीमत वाली मिसाल बना।", "7d8a9e45"]},
"OLAYLAR_EK5:1798-10-23:0":{"b": ["फ़्रांसीसियों से प्रेवेज़ा का लिया जाना", "054b359d"], "d": ["1797 में वेनिस गणराज्य के पतन पर आयोनियन द्वीप तथा मुख्य भूमि पर प्रेवेज़ा, पार्गा और वोनित्सा फ़्रांस के हाथ में चले गए। यानिया के वाली तेपेलेना के अली पाशा ने मिस्र पर फ़्रांसीसी क़ब्ज़े के कारण छिड़े युद्ध का लाभ उठाकर अक्तूबर 1798 में प्रेवेज़ा ले लिया। इस प्रकार पासारोवित्ज़ में वेनिस के पास छोड़ा गया यह बंदरगाह अस्सी वर्ष बाद उस्मानी प्रशासन में आ गया; इसी अभियान में बुत्रिंत भी उस्मानियों के पास चला गया।", "0e9ad533"]},
"OLAYLAR_EK5:1799-05-20:0":{"b": ["अक्का रक्षा — नेपोलियन का खदेड़ा जाना", "56b5c45b"], "d": ["मिस्र से सीरिया की ओर बढ़े नेपोलियन ने अक्का को घेरा और दो माह लगातार हमले किए; नगर की रक्षा जेज़्ज़ार अहमद पाशा ने अंग्रेज़ बेड़े के सहयोग और इस्तांबुल से भेजी निज़ाम-ए जदीद टुकड़ियों के साथ की। घेराबंदी उठाकर मिस्र हटने को विवश नेपोलियन ने पूर्व तक फैलने का सपना इन प्राचीरों के सामने दफ़न कर दिया। ख़बर इस्तांबुल में बड़े उल्लास से ली गई और नई बनी प्रशिक्षित सेना के पहली गंभीर परीक्षा पार करने का प्रमाण मानी गई।", "78b85f0c"]},
"OLAYLAR_EK5:1801-04-01:0":{"b": ["वहाबियों का कर्बला पर हमला", "522341ed"], "d": ["नज्द से चली वहाबी सेनाओं ने कर्बला में प्रवेश करके नगर को लूटा, हज़रत हुसैन के मक़बरे को तहस-नहस किया और तीन हज़ार से अधिक लोगों को मारा। इराक़ में ऑटोमन राज्य के कोलेमेन गवर्नर इस हमले को रोक न सके; घटना ने ईरान और इस्तांबुल दोनों में भारी प्रतिक्रिया जगाई। यह हमला सऊदी आंदोलन के नख़लिस्तान अमीरात से निकलकर ऑटोमन के पवित्र नगरों को ख़तरे में डालने वाली क्षेत्रीय शक्ति बन जाने की घोषणा था।", "f571ab30"]},
"OLAYLAR_EK5:1801-09-24:0":{"b": ["कार्तली-काखेती (पूर्वी जॉर्जिया) का रूस में विलय", "3b650c5e"], "d": ["1783 में रूसी संरक्षण स्वीकार करने वाला और 1795 में ईरान के विनाशकारी अभियान का शिकार हुआ कार्तली-काखेती राजतंत्र भंग किया गया; 12 सितंबर 1801 के आदेश से रूस का प्रांत घोषित करके रूसी प्रशासन प्रणाली स्थापित की जाने लगी। जॉर्जिया ने इस तिथि से स्वतंत्रता खो दी; कुछ वर्षों में मेग्रेलिया (1803), इमेरेतिया और गूरिया (1804) भी रूसी आधिपत्य में आए और रूस ऑटोमन की कॉकेशस सीमा तक आ पहुँचा। इस घटना से गोरी, दुशेती (कार्तली) और तेलावी (काखेती) रूस को चले गए।", "f5e0d5d5"]},
"OLAYLAR_EK5:1801-10-09:0":{"b": ["मिस्र का फ़्रांसीसियों से ख़ाली कराया जाना", "00cfdc8c"], "d": ["ऑटोमन और अंग्रेज़ बलों के स्थल और समुद्र से संयुक्त अभियान के परिणामस्वरूप पहले क़ाहिरा, फिर इस्कंदरिया लिया गया और फ़्रांसीसी सेनाएँ जहाज़ों से अपने देश भेजी गईं। तीन वर्ष का क़ब्ज़ा समाप्त होने पर मिस्र काग़ज़ पर ऑटोमन प्रशासन में लौटा, किंतु कोलेमेन बेयों और अल्बानियाई टुकड़ियों के बीच आधिपत्य के संघर्ष ने देश को अराजकता में धकेल दिया। यह ख़ालीपन कुछ ही वर्षों में कवालाली मेहमेद अली के उदय की ज़मीन तैयार करने वाला था।", "acaf7e40"]},
"OLAYLAR_EK5:1802-06-25:0":{"b": ["पेरिस संधि — फ़्रांस से शांति की पुनर्स्थापना", "1b76991f"], "d": ["मिस्र के ख़ाली किए जाने के बाद हस्ताक्षरित संधि से ऑटोमन राज्य और फ़्रांस के बीच युद्ध की स्थिति औपचारिक रूप से समाप्त हुई और पुरानी कैपिट्यूलेशन नवीकृत की गईं। फ़्रांसीसी व्यापारी जहाज़ों को काला सागर में प्रवेश की अनुमति दी गई; इसके बदले फ़्रांस ने ऑटोमन की क्षेत्रीय अखंडता को मान्यता दी। शांति की स्थापना ने रूस और इंग्लैंड के बीच फँसी सेलिम तृतीय की विदेश नीति को फिर चाल चलने का अवसर दिया।", "367c616e"]},
"OLAYLAR_EK5:1803-02-01:0":{"b": ["वहाबियों का ताइफ़ पर क़ब्ज़ा", "7b791359"], "d": ["सऊद बिन अब्दुलअज़ीज़ की कमान की वहाबी सेनाओं ने हिजाज़ की ओर पहले क़दम में ताइफ़ को घेरकर लूटा; नगर पवित्र भूमि की ओर खुलने वाले पहले द्वार के रूप में गिरा। हरमैन के संरक्षक की उपाधि धारण करने वाले ऑटोमन पदीशाह के लिए यह शासन की वैधता को सीधे हिला देने वाला आघात था। ढाई माह बाद वही सेना मक्का पर चढ़ने वाली थी।", "289d52ef"]},
"OLAYLAR_EK5:1803-04-30:0":{"b": ["वहाबियों का पहली बार मक्का पर क़ब्ज़ा", "21157c05"], "d": ["ताइफ़ के गिरने के ढाई माह बाद वहाबी सेनाएँ मक्का में प्रविष्ट हुईं, मक़बरे गिराए और अपनी समझ के अनुसार व्यवस्था स्थापित की; शरीफ़ ग़ालिब को जिद्दा में हटना पड़ा। हज मार्गों के बंद होने की गूँज पूरे इस्लामी जगत में उठी और इस्तांबुल को मिस्र वाली मेहमेद अली से सैन्य सहायता माँगने को विवश किया। यह पहला आधिपत्य केवल तीन माह चलने वाला था।", "7194e460"]},
"OLAYLAR_EK5:1803-08-06:0":{"b": ["शरीफ़ ग़ालिब का मक्का वापस लेना", "83d08dff"], "d": ["जिद्दा में हटे शरीफ़ ग़ालिब ने जुटाई सेनाओं से मक्का को घेरा और पच्चीस दिन की घेराबंदी के बाद नगर वहाबियों से वापस ले लिया; ऑटोमन के नाम का ख़ुतबा फिर पढ़ा गया। यह दूसरा आधिपत्य भी स्थायी न होगा, सऊद सेनाएँ 1806 में नगर को फिर ले लेंगी।", "8c15c19e"]},
"OLAYLAR_EK5:1804-02-14:0":{"b": ["प्रथम सर्ब विद्रोह का आरंभ", "0f6e8767"], "d": ["बेलग्रेड में शासन हथियाने वाले विद्रोही येनिचेरी दायियों के सर्ब प्रमुखों का सामूहिक रूप से क़त्ल करने पर कारा योर्गी के नेतृत्व में सशस्त्र प्रतिरोध आरंभ हुआ। आरंभ में पदीशाह के प्रति निष्ठावान रहकर केवल दायियों के विरुद्ध चलाया गया आंदोलन शीघ्र स्वायत्तता और स्वतंत्रता माँगने वाले राष्ट्रीय विद्रोह में बदल गया। सर्ब सेनाओं ने 1806 में बेलग्रेड ले लिया; यह विद्रोह बाल्कन में राष्ट्रवादी स्वतंत्रता आंदोलनों की पहली कड़ी बना।", "07d5d6c6"]},
"OLAYLAR_EK5:1805-06-01:0":{"b": ["वहाबियों का मदीना पर क़ब्ज़ा", "84e310d7"], "d": ["मक्का के बाद मदीना भी वहाबी सेनाओं के हाथ आया; रौज़ा-ए मुतह्हरा का ख़ज़ाना बाँटा गया और नगर के गुंबददार मक़बरे गिराए गए। इस तरह दोनों पवित्र नगर एक साथ ऑटोमन नियंत्रण से निकल गए और दमिश्क़ तथा मिस्र से आने वाले हज क़ाफ़िले वर्षों रवाना न हो सके। मदीना केवल सात वर्ष बाद, 1812 में, मेहमेद अली पाशा के पुत्र तोसून पाशा की कमान की मिस्री सेना द्वारा वापस लिया जा सका।", "b8d034e6"]},
"OLAYLAR_EK5:1806-12-22:0":{"b": ["रूस से युद्ध का आरंभ (1806-1812 ऑटोमन-रूसी युद्ध) और जलडमरूमध्य का बंद किया जाना", "ea170804"], "d": ["नेपोलियन की ऑस्टरलिट्ज़ विजय के बाद फ़्रांस के निकट आए सेलिम तृतीय के वलाचिया और बोग़दान के वोइवोडाओं को रूसी दबाव के बावजूद हटाने पर रूसी सेनाओं ने दोनों रियासतों पर क़ब्ज़ा किया और युद्ध आरंभ हुआ। ऑटोमन राज्य ने जलडमरूमध्य को रूसी बेड़े के लिए बंद किया; इसके जवाब में इंग्लैंड ने भी रूस का पक्ष लेकर इस्तांबुल को बेड़ा भेजा। छह वर्ष चलने वाला यह युद्ध, काबाक्चि विद्रोह और सेलिम तृतीय के पदच्युत होने से गुँथा हुआ, 1812 की बुख़ारेस्ट संधि में बेसाराबिया की हानि के साथ समाप्त होने वाला था।", "901537a4"]},
"OLAYLAR_EK5:1807-02-20:0":{"b": ["अंग्रेज़ बेड़े का इस्तांबुल के सामने आना (डकवर्थ अभियान)", "195bb58f"], "d": ["ऑटोमन राज्य को फ़्रांस से संबंध तोड़ने को विवश करना चाहने वाले इंग्लैंड ने एडमिरल डकवर्थ की कमान के बेड़े को चानाक्काले से गुज़ारकर इस्तांबुल के सामने लंगर डलवाया। फ़्रांसीसी राजदूत सेबास्तियानी के निर्देशन से इस्तांबुल की जनता लामबंद हुई, तटीय बैटरियाँ दिनों में सुदृढ़ की गईं और नगर पर तोप चलने से पहले बेड़े को पीछे हटना पड़ा; लौटते समय चानाक्काले में भारी हानि उठाई। राजधानी के किसी विदेशी बेड़े द्वारा पहली बार इतने निकट से ख़तरे में डाले जाने ने जलडमरूमध्य के मसले को यूरोपीय कूटनीति के केंद्र में रख दिया।", "bf71116c"]},
"OLAYLAR_EK5:1808-11-17:0":{"b": ["मुस्तफ़ा चतुर्थ का गला घोंटकर मारा जाना", "eeb75c20"], "d": ["अलेमदार मुस्तफ़ा पाशा के छापे में मरने और विद्रोहियों के सराय की ओर बढ़ने की इच्छा पर, गद्दी से उतारे गए मुस्तफ़ा चतुर्थ भाई महमूद द्वितीय के आदेश से गला घोंटकर मारे गए। जनाज़ा बाहचेकापी में पिता अब्दुलहमीद प्रथम के मक़बरे में दफ़नाया गया; विद्रोहियों में ताबूत के ख़ाली होने की अफ़वाह फैली।", "8a944508"]},
"OLAYLAR_EK5:1809-01-05:0":{"b": ["क़लआ-ए सुल्तानिये संधि — इंग्लैंड से शांति और जलडमरूमध्य नियम", "fe282117"], "d": ["डकवर्थ अभियान की विफलता के बाद इंग्लैंड से हस्ताक्षरित संधि से दोनों राज्यों के बीच युद्ध समाप्त हुआ और अंग्रेज़ व्यापारियों के पुराने विशेषाधिकार लौटाए गए। पाठ में आए और 'क़दीम क़ाइदे' कहे जाने वाले प्रावधान ने शांति काल में किसी विदेशी युद्धपोत के जलडमरूमध्य से न गुज़र सकने को अभिलेखित किया। यह सिद्धांत XIX. शताब्दी भर जलडमरूमध्य व्यवस्था को आकार देने वाली सभी अंतरराष्ट्रीय व्यवस्थाओं का विधिक आधार बना।", "7ef33a02"]},
"OLAYLAR_EK5:1811-10-14:0":{"b": ["स्लोबोज़िया पराजय — डैन्यूब सेना का घिरना", "54b60fd1"], "d": ["रूसचुक के सामने डैन्यूब पार करने वाली ऑटोमन सेना का बड़ा भाग, कुतुज़ोव की नदी के उस पार से की घेराव-चाल से स्लोबोज़िया में फँसाकर भूख के हवाले कर दिया गया। हज़ारों सैनिकों को समर्पण करना पड़ा; वज़ीर-ए आज़म के हाथ की सेना वस्तुतः घुल गई और बाबे-आली को एक माह बाद युद्धविराम माँगना पड़ा। यह पराजय 1812 की बुख़ारेस्ट संधि में बेसाराबिया के दिए जाने पर राज़ी होने का सीधा कारण है।", "d9da91c7"]},
"OLAYLAR_EK5:1813-10-05:0":{"b": ["बेलग्रेड की वापसी और प्रथम सर्ब विद्रोह का दमन", "06f56f52"], "d": ["बुख़ारेस्ट संधि से रूसी समर्थन से वंचित सर्ब विद्रोही बोस्निया और रुमेली से आई सेनाओं की संयुक्त कार्रवाई के सामने न टिक सके; ख़ुर्शीद अहमद पाशा बेलग्रेड में दाख़िल हुए और नौ वर्ष का विद्रोह पूरी तरह कुचला गया। कारा योर्गी ऑस्ट्रिया भाग गए, सेमेंदिरे संजक फिर सीधे ऑटोमन प्रशासन से जोड़ा गया। किंतु अपनाए गए कठोर उपाय दो वर्ष बाद मिलोश ओब्रेनोविच के नेतृत्व में दूसरे और स्थायी विद्रोह को भड़काने वाले थे।", "1f0a751b"]},
"OLAYLAR_EK5:1815-04-23:0":{"b": ["द्वितीय सर्ब विद्रोह और मिलोश ओब्रेनोविच का बशकनेज़ पद", "e6e82ad2"], "d": ["प्रथम विद्रोह के दमन के बाद अपनाए गए भारी उपायों के विरुद्ध मिलोश ओब्रेनोविच के नेतृत्व में नया विद्रोह फूटा; इस बार बाबे-आली ने बल की जगह समझौता चुना। हुए समझौते से मिलोश 'बशकनेज़' के रूप में मान्य हुए, कर वसूली और आंतरिक मामले चलाने का अधिकार सर्ब केनेज़ों को छोड़ा गया। वास्तविक स्वायत्तता का यह पहला केंद्रक, 1830 के फ़रमान और 1878 की स्वतंत्रता तक जाने वाली प्रक्रिया का आरंभ बिंदु बना।", "bf6041bb"]},
"OLAYLAR_EK5:1821-02-22:0":{"b": ["वलाचिया विद्रोह — यप्सिलांती का प्रुत पार करना और व्लादिमिरेस्कू विद्रोह", "67d46a98"], "d": ["रूसी सेना में जनरल रहे अलेक्सांद्र यप्सिलांती ने फ़िलिकी एतेरिया के नाम पर प्रुत पार करके वलाचिया और बोग़दान में सामान्य यूनानी विद्रोह आरंभ करने का प्रयास किया; उन्हीं दिनों तुदोर व्लादिमिरेस्कू ने भी स्थानीय किसानों को हरकत में ला दिया। दोनों आंदोलन मिल न सके: व्लादिमिरेस्कू ने यप्सिलांती की साथ मिलकर तुर्कों से लड़ने की पुकार को 'मैंने तुर्कों के नहीं, यूनानियों के विरुद्ध विद्रोह किया है' उत्तर दिया और शीघ्र यप्सिलांती के आदमियों द्वारा मारे गए। विद्रोह ऑटोमन सेनाओं ने मई में कुचला, किंतु फ़ेनेरी वोइवोडेशिप व्यवस्था समाप्त हुई और विद्रोह की आग मोरिया तक फैल गई।", "64b96ac8"]},
"OLAYLAR_EK5:1824-06-01:0":{"b": ["द्वितीय सऊदी राज्य की रियाद में स्थापना", "34dad3bd"], "d": ["दिरइया के 1818 में गिरने और पहले सऊदी राज्य के ढहने के छह वर्ष बाद तुर्की बिन अब्दुल्लाह ने मिस्री चौकियों को नज्द से निकालकर रियाद-केंद्रित नई सऊदी अमीरात स्थापित की। नई संरचना ने हिजाज़ तक फैलने से बचकर नज्द में बने रहना चुना और ऑटोमन-मिस्री सेनाओं से सीधे टकराव से दूर रही। यह दूसरा राज्य शताब्दी के अंत तक चलने और आज के सऊदी अरब की स्थापना की ओर जाने वाली शृंखला की दूसरी कड़ी बनने वाला था। उसी तिथि को हाथ से निकले अन्य स्थान: दिरइया (नज्द)।", "72b5fd29"]},
"OLAYLAR_EK5:1826-10-07:0":{"b": ["अक़किरमान संधि — सर्बिया और रियासतों को रियायतें", "c75f15d0"], "d": ["येनिचेरी ओजाक के उन्मूलन के तुरंत बाद सेना-रहित हुए ऑटोमन राज्य को रूस के अल्टीमेटम के सामने भारी शर्तों वाली संधि स्वीकार करनी पड़ी। सर्बिया को वादा की गई स्वायत्तता की पुष्टि हुई, वलाचिया और बोग़दान के वोइवोडाओं के रूसी स्वीकृति के बिना न हटाए जा सकने की बात मानी गई, रूसी व्यापारी जहाज़ों को जलडमरूमध्य में पूर्ण स्वतंत्रता दी गई। बाबे-आली के दो वर्ष बाद यूनानी मसले के कारण संधि को न मानने की घोषणा करने पर रूस इसे युद्ध का कारण मानेगा।", "a7de6cda"]},
"OLAYLAR_EK5:1827-02-01:0":{"b": ["तिमार प्रणाली का उन्मूलन", "84d5d1d6"], "d": ["येनिचेरी ओजाक के उन्मूलन के एक वर्ष बाद रुमेली और अनातोलिया के तिरपन संजकों के लगभग 5.200 तिमारधारी सिपाही, तिमार आय के साथ असाकिर-ए मंसूरे के घुड़सवार दल में बदल दिए गए। इस तरह ऑटोमन भूमि, कर और सेना व्यवस्था की चार शताब्दी की रीढ़ तिमार शासन वस्तुतः समाप्त हुआ। ख़ाली हुए तिमार राजकोष को सौंपे गए और केंद्रीय वेतनभोगी सेना तथा नक़द कर प्रणाली में जाने का मार्ग खुला।", "077ea4ea"]},
"OLAYLAR_EK5:1827-03-14:0":{"b": ["तिबहाने-ए आमिरे की स्थापना — आधुनिक चिकित्सा शिक्षा का आरंभ", "ac3e57c0"], "d": ["नवस्थापित असाकिर-ए मंसूरे सेना के लिए चिकित्सक और शल्य-चिकित्सक तैयार करने के लिए, हकीमबाशी मुस्तफ़ा बेहचेत एफ़ेंदी के प्रस्ताव पर शहज़ादेबाशी में तिबहाने-ए आमिरे खोला गया। पाठ यूरोप के पाठ्यक्रम के अनुसार तय किए गए और शिक्षा आरंभ में फ़्रांसीसी में दी गई; कुछ वर्ष बाद जर्राहहाने-ए आमिरे भी स्थापित होकर दोनों संस्थाएँ मिला दी गईं। तुर्की में आधुनिक चिकित्सा शिक्षा का आरंभ माना जाने वाला यह विद्यालय आज के इस्तांबुल चिकित्सा संकाय का मूल माना जाता है।", "54a2ed54"]},
"OLAYLAR_EK5:1828-04-26:0":{"b": ["1828-1829 ऑटोमन-रूसी युद्ध का आरंभ", "9dff4e05"], "d": ["नावारिन में बेड़े के जलाए जाने और बाबे-आली के अक़किरमान संधि को न मानने की घोषणा पर रूस ने एक साथ दो मोर्चों से युद्ध छेड़ा। येनिचेरी ओजाक अभी-अभी समाप्त हुआ था और नई सेना निर्माणाधीन थी, इसलिए ऑटोमन रक्षा आरंभ से कमज़ोर रही; रूसियों ने डैन्यूब पार करते हुए पूर्व में कार्स और अहिस्का ले लिए। एक वर्ष में एदिर्ने तक बढ़ आई रूसी सेना 1829 की एदिर्ने संधि की भारी शर्तें और यूनान की स्वतंत्रता थोपने वाली थी।", "9491c932"]},
"OLAYLAR_EK5:1830-05-07:0":{"b": ["संयुक्त राज्य अमेरिका से पहली संधि", "d737516f"], "d": ["वर्षों चली बातचीत के बाद हस्ताक्षरित व्यापार और नौवहन संधि से अमेरिका ने ऑटोमन भूमि में सर्वाधिक अनुकूल राष्ट्र का दर्जा और जलडमरूमध्य से व्यापारिक गुज़रने का अधिकार पाया। एक अलग गुप्त धारा के अनुसार ऑटोमन चाहे तो अमेरिकी जहाज़-घाटों में जहाज़ बनवा सकता था, बने-बनाए जहाज़ और लकड़ी ख़रीद सकता था; अमेरिकी सीनेट ने संधि को स्वीकृत किया पर इस गुप्त धारा को 18 के विरुद्ध 27 मतों से अस्वीकार कर दिया। जहाज़ मार्ग फिर भी बंद न हुआ: हेनरी एकफ़ोर्ड ने 1831 में लाया जहाज़ ऑटोमन को बेचा, आयनालीकवाक़ में काम करने वाले अमेरिकी कारीगरों ने बेड़े को नए प्रकार के जहाज़ दिए। यह संधि ऑटोमन राज्य के यूरोप से बाहर किसी राज्य से बने पहले व्यापक संबंध का दस्तावेज़ रही।", "c87615ca"]},
"OLAYLAR_EK5:1831-09-14:0":{"b": ["बग़दाद में कोलेमेन शासन का अंत", "7e1d38a3"], "d": ["केंद्रीकरण नीति चलाने वाले महमूद द्वितीय ने माँगा धन न भेजने और केंद्र से आए अधिकारी की हत्या कराने वाले बग़दाद वाली दाऊद पाशा को विद्रोही घोषित किया। अली रिज़ा पाशा की कमान की सेना ने नब्बे दिन चली घेराबंदी के बाद नगर लिया और कोलेमेनों का लगभग पूरा सफ़ाया किया गया। इस तरह 1704 से चला आ रहा अर्ध-स्वतंत्र कोलेमेन शासन समाप्त हुआ और इराक़ फिर सीधे केंद्र से जुड़ा।", "676f3744"]},
"OLAYLAR_EK5:1834-07-01:0":{"b": ["मेकतेब-ए हरबिये की माचका बैरक में स्थापना", "bf31c7d9"], "d": ["असाकिर-ए मंसूरे-ए मुहम्मदिये के लिए यूरोपीय पद्धति से प्रशिक्षित अधिकारी देने के उद्देश्य से माचका बैरक में मेकतेब-ए फ़ुनून-ए हरबिये खोला गया। विद्यार्थियों को गणित, मानचित्र, क़िलेबंदी और विदेशी भाषा पढ़ाई गई; शीघ्र वियना और पेरिस विद्यार्थी भेजकर कैडर सुदृढ़ किया गया। यह विद्यालय ऑटोमन सेना में विद्यालय-शिक्षित अधिकारी परंपरा के, और इसलिए XIX. शताब्दी के अंत में उभरने वाली नई सैनिक-बुद्धिजीवी पीढ़ी के जन्म का स्थान बना।", "1d64a30c"]},
"OLAYLAR_EK5:1835-05-26:0":{"b": ["त्रिपोलीतानिया का सीधे केंद्र से जुड़ना — करामानली राजवंश का अंत", "faabcb96"], "d": ["करामानली परिवार के भीतर के गद्दी-झगड़ों और फ़्रांस के 1830 में अल्जीरिया पर क़ब्ज़े के बाद बढ़े यूरोपीय दबाव पर बाबे-आली ने त्रिपोलीतानिया में सीधा हस्तक्षेप किया। इस्तांबुल से भेजा बेड़ा नगर में दाख़िल हुआ, अंतिम करामानली बेय पदच्युत करके इस्तांबुल लाया गया और प्रांत केंद्र से नियुक्त वाली को सौंपा गया। 124 वर्ष का राजवंशीय काल समाप्त होते समय उत्तरी अफ़्रीका में ऑटोमन राज्य की सीधे शासित अंतिम भूमि का टुकड़ा सुदृढ़ हो गया।", "71104846"]},
"OLAYLAR_EK5:1838-02-28:0":{"b": ["दफ़्तरदारी का उन्मूलन और वित्त मंत्रालय की स्थापना", "89f8125e"], "d": ["शास्त्रीय ऑटोमन वित्त व्यवस्था के प्रधान दफ़्तरदार पद को समाप्त करके यूरोपीय ढंग का मंत्रालय — वित्त नेज़ारेत — स्थापित किया गया और बिखरे ख़ज़ाने एक हाथ में जुटाए गए। उसी वर्ष बाबे-आली की अन्य इकाइयाँ भी नेज़ारेत नाम से पुनर्गठित करके आधुनिक मंत्रिपरिषद ढाँचे पर आया गया। यह व्यवस्था एक वर्ष बाद घोषित होने वाले तंज़ीमात फ़रमान के प्रशासनिक आधार को तैयार करने वाले सबसे महत्वपूर्ण क़दमों में से एक थी।", "46962eda"]},
"OLAYLAR_EK5:1839-01-19:0":{"b": ["अंग्रेज़ों का अदन में बसना", "ddbd556b"], "d": ["इंग्लैंड ने 1802 में लहिज के सुल्तान अहमद बिन अब्दुलकरीम से हस्ताक्षरित व्यापार और मित्रता समझौते के आधार पर अदन बंदरगाह पर सैनिक उतारे और नगर को अपने नियंत्रण में लिया। लाल सागर के मुहाने को थामने वाला यह बंदरगाह भारत मार्ग के कोयला-आपूर्ति अड्डे के रूप में अंग्रेज़ साम्राज्यिक रणनीति का कुंजी बिंदु बन गया। ऑटोमन राज्य का यमन पर दावा काग़ज़ पर चलता रहा, किंतु दक्षिणी तट पर उसका वास्तविक आधिपत्य इस तिथि के बाद फिर नहीं लौटा।", "731b896d"]},
"OLAYLAR_EK5:1849-01-01:0":{"b": ["तिहामे तट की वापसी: हुदैदा, ज़बीद और मोख़ा का लिया जाना", "353982d2"], "d": ["1840 में मिस्री सेना के हटने से मालिकहीन रह गए यमन तट पर मक्का शरीफ़ की निगरानी में तौफ़ीक़ पाशा की कमान की सेनाएँ उतरीं और हुदैदा, ज़बीद और मोख़ा बंदरगाह ऑटोमन प्रशासन से जोड़ दिए। सनआ तक बढ़ने का प्रयास किया गया पर जनता के प्रतिरोध के कारण हुदैदा लौटना पड़ा; इस तरह पठार ज़ैदी इमामों के पास रहे और ऑटोमन आधिपत्य तेईस वर्ष केवल तिहामे पट्टी में चला। भीतरी यमन केवल 1872 में अहमद मुख़्तार पाशा के अभियान से वापस लिया जाएगा।", "7a30c1f9"]},
"OLAYLAR_EK5:1849-05-01:0":{"b": ["बाल्टालिमानी समझौता: वलाचिया और बोग़दान में संयुक्त ऑटोमन-रूसी संरक्षण", "d3bb22e9"], "d": ["1848 की क्रांतियों के वलाचिया और बोग़दान तक फैलने पर ऑटोमन और रूसी सेनाओं ने रियासतों पर साथ क़ब्ज़ा किया था। बाल्टालिमानी में हस्ताक्षरित समझौते से वोइवोडाओं के चुनाव से नहीं बल्कि पदीशाह द्वारा सात वर्ष के लिए नियुक्त किए जाने और दोनों राज्यों के क्षेत्र में संयुक्त नियंत्रण स्थापित करने का निर्णय हुआ। समझौते ने ऑटोमन की काग़ज़ी संप्रभुता को बचाते हुए रूस को वास्तविक भागीदारी का अधिकार दिया और डैन्यूब रियासतों के ऑटोमन से कटने को तेज़ किया।", "b343f446"]},
"OLAYLAR_EK5:1849-08-16:0":{"b": ["हंगरियाई शरणार्थी मसला: कोस्सुथ और साथियों का ऑटोमन में शरण लेना", "1c7d7ef4"], "d": ["1848-1849 की हंगरी क्रांति के रूसी-ऑस्ट्रियाई हस्तक्षेप से कुचले जाने पर लायोश कोस्सुथ और हज़ारों हंगरियाई-पोलिश शरणार्थी ऑटोमन भूमि में शरण लेने आए। ऑस्ट्रिया और रूस ने शरणार्थियों को लौटाने की कठोर माँग की; बाबे-आली ने इंग्लैंड और फ़्रांस के समर्थन से लौटाने से इनकार किया और समूह को कुताह्या में बसाया। कोस्सुथ का दल यहाँ लगभग अठारह माह रहा, सैकड़ों शरणार्थी मुसलमान होकर ऑटोमन सेवा में आए। घटना तंज़ीमात ऑटोमन की यूरोपीय जनमत में प्रतिष्ठा बढ़ाने वाली दुर्लभ कूटनीतिक विजयों में से एक मानी गई।", "07b6d020"]},
"OLAYLAR_EK5:1851-02-11:0":{"b": ["अंजुमन-ए दानिश की स्थापना: इस्तांबुल में पहली ऑटोमन अकादमी", "6fda1365"], "d": ["मजलिस-ए मआरिफ़-ए उमूमिये के निर्णय से स्थापित अंजुमन-ए दानिश तुर्की में ज्ञान और पाठ्य-पुस्तकें तैयार करने के लिए संगठित पहली ऑटोमन विज्ञान अकादमी है। 18 जुलाई 1851 को दारुल-मआरिफ़ इमारत में समारोह से खोली गई; स्थानीय और विदेशी सदस्यों में अहमद जेवदेत पाशा भी थे। अल्पजीवी होने पर भी जेवदेत पाशा की तारीख़ और क़वाइद-ए उस्मानिये जैसी कृतियाँ इस संस्था की देन रहीं और तुर्की को ज्ञान की भाषा बनाने में आधारशिला मानी गईं।", "7eebb193"]},
"OLAYLAR_EK5:1853-11-11:0":{"b": ["ओल्तेनित्सा विजय: डैन्यूब मोर्चे पर पहली ऑटोमन सफलता", "a660ad2f"], "d": ["क्रीमिया युद्ध के आरंभिक चरण में सेरदार-ए एकरम उमर लुत्फ़ी पाशा ने डैन्यूब पार करके ओल्तेनित्सा में रूसी सेनाओं को भारी हानि के साथ खदेड़ा। विजय ने युद्ध के आरंभ में ही रूसी प्रगति रोककर ऑटोमन सेना की तंज़ीमात के बाद शिक्षा से पाई शक्ति यूरोप को दिखाई। इस सफलता ने इंग्लैंड और फ़्रांस के ऑटोमन के पक्ष में युद्ध में उतरने के निर्णय को सरल करने वाली मनोवैज्ञानिक ज़मीन तैयार की।", "a0e5e8fb"]},
"OLAYLAR_EK5:1854-03-12:0":{"b": ["इस्तांबुल में इंग्लैंड और फ़्रांस से गठबंधन संधि", "04809278"], "d": ["क्रीमिया युद्ध में रूस के विरुद्ध ऑटोमन राज्य और इंग्लैंड तथा फ़्रांस के बीच हस्ताक्षरित गठबंधन संधि ने तीनों राज्यों के संयुक्त अभियान चलाने और सहयोगियों के युद्ध समाप्त होने से पहले अलग शांति न करने का प्रावधान किया। इस तरह ऑटोमन राज्य ने अपने इतिहास में पहली बार बड़े यूरोपीय राज्यों के साथ बराबर के पक्ष के रूप में सैन्य गठबंधन में प्रवेश किया। यह संधि दो वर्ष बाद पेरिस में ऑटोमन के यूरोपीय राज्य-प्रणाली में औपचारिक स्वीकार का भी विधिक आधार बनी।", "1899331b"]},
"OLAYLAR_EK5:1855-08-16:0":{"b": ["इस्तांबुल शहरेमानेती की स्थापना: पहला आधुनिक नगरपालिका संगठन", "be4af27f"], "d": ["क्रीमिया युद्ध के दौरान इस्तांबुल में जमा हुए मित्र सैनिकों और बढ़ी जनसंख्या से उपजे बुनियादी ढाँचा संकट ने क़ाज़ी-केंद्रित शास्त्रीय नगर प्रशासन की अपर्याप्तता को उजागर किया। यूरोपीय उदाहरणों के अनुसार स्थापित शहरेमानेती से सफ़ाई, मूल्य-निर्धारण, बाज़ार-निरीक्षण और निर्माण-कार्य एक हाथ में जुटाए गए; अगले वर्ष बेयोग़्लू-गलाता में छठा नगरपालिका मंडल (दाइरे-ए बेलेदिये) पायलट क्षेत्र के रूप में गठित हुआ। इस क़दम को ऑटोमन में आधुनिक नगरपालिका-व्यवस्था का आरंभ माना जाता है।", "23959c70"]},
"OLAYLAR_EK5:1856-03-30:0":{"b": ["पेरिस संधि: क्रीमिया युद्ध का अंत और ऑटोमन का यूरोपीय राज्य-प्रणाली में स्वीकार", "4aee0e2a"], "d": ["क्रीमिया युद्ध समाप्त करने वाली पेरिस संधि से ऑटोमन राज्य को यूरोपीय राज्य-विधि का समान सदस्य घोषित किया गया और उसकी क्षेत्रीय अखंडता बड़ी शक्तियों की संयुक्त गारंटी में ली गई। काला सागर को तटस्थ किया गया, रूस का क्यूचुक कायनार्जा से पाया ऑर्थोडॉक्स प्रजा पर संरक्षण का दावा अमान्य ठहराया गया, बेसाराबिया का दक्षिण (किली, काहुल, इस्माईल और बोल्ग्राद क़ज़ा) बोग़दान को दिया गया। किंतु उसी संधि ने इस्लाहात फ़रमान को अंतरराष्ट्रीय प्रतिबद्धता बनाकर आंतरिक मामलों में हस्तक्षेप का द्वार भी खोला।", "42c5d63d"]},
"OLAYLAR_EK5:1856-06-07:0":{"b": ["दोलमाबाहचे सराय का उद्घाटन: प्रशासन केंद्र का तोपकापी से स्थानांतरण", "71ad26d0"], "d": ["अब्दुलमजीद द्वारा 1842 में बालयान परिवार को दिए आदेश का सराय चौदह वर्ष के निर्माण के बाद खुला और राज्य का प्रशासन केंद्र चार शताब्दी पुराने तोपकापी से बोस्फ़ोरस तट पर स्थानांतरित हुआ। यूरोपीय शैली, क्रिस्टल सीढ़ी और मुआयदे हॉल के साथ सराय तंज़ीमात के पश्चिमीकरण के दावे की पत्थर में अभिव्यक्ति बना। इसकी भारी लागत ऑटोमन वित्त के विदेशी ऋण के चक्र में फँसने वाले वर्षों की सबसे अधिक आलोचित मदों में से एक बन गई।", "bb3cd1c8"]},
"OLAYLAR_EK5:1859-02-05:0":{"b": ["वलाचिया और बोग़दान का कूज़ा शासन में एकीकरण: रोमानिया का जन्म", "baef4da5"], "d": ["पेरिस संधि के बाद आयोजित चुनावों में दोनों रियासतों ने कर्नल अलेक्सांद्रू इओन कूज़ा को वोइवोडा चुनकर वास्तविक एकीकरण कर लिया। बाबे-आली और ऑस्ट्रिया ने विरोध किया तो भी फ़्रांस के समर्थन से बना यह नियत-तथ्य स्वीकार करना पड़ा। काग़ज़ पर ऑटोमन से जुड़ी रही यह एकता 1862 में रोमानिया नाम लेगी और 1877 में एकतरफ़ा स्वतंत्रता घोषित करेगी; डैन्यूब तट के ऑटोमन आधिपत्य के विघटन में यह मोड़ है।", "83e52b52"]},
"OLAYLAR_EK5:1859-09-14:0":{"b": ["कुलेली घटना: इस्तांबुल में अब्दुलमजीद के विरुद्ध पहला तख़्तापलट प्रयास", "e3653b21"], "d": ["तंज़ीमात नीति और इस्लाहात फ़रमान के ग़ैर-मुसलमानों को दी समानता पर प्रतिक्रिया रखने वाली सैनिक-नागरिक मिश्रित गुप्त संस्था पदीशाह को गद्दी से उतारने की योजना बना रही थी कि क़िलिच अली पाशा मस्जिद में बैठक के दौरान छापे में पकड़ी गई। आरोपियों पर कुलेली बैरक में मुक़दमा चलने से घटना इसी नाम से जानी गई; मृत्युदंड निर्वासन में बदल दिए गए। इसे ऑटोमन इतिहास में वैचारिक आधार पर बनाए संगठन का पहला सराय तख़्तापलट प्रयास माना जाता है।", "4e9e2296"]},
"OLAYLAR_EK5:1860-05-30:0":{"b": ["जबल-ए लुबनान में द्रूज़-मारोनी गृहयुद्ध और दमिश्क़ घटनाएँ", "5595fdd6"], "d": ["मई 1860 में सैदा के निकट दो द्रूज़ों की हत्या से भड़के संघर्ष पर्वत के सबसे ख़ूनी द्रूज़-मारोनी गृहयुद्ध में बदल गए और जुलाई में दमिश्क़ तक फैलकर हज़ारों ईसाइयों की मृत्यु पर परिणत हुए। फ़्रांस के सैनिक उतारने पर बाबे-आली ने फ़ुआद पाशा को असाधारण अधिकार के साथ क्षेत्र में भेजा; कठोर दमन अभियान चलाया गया। घटनाएँ यूरोपीय हस्तक्षेप का आधार बनीं और लेबनान के विशेष दर्जा पाने का सीधा कारण रहीं।", "511709b3"]},
"OLAYLAR_EK5:1860-10-22:0":{"b": ["तरजुमान-ए अहवाल का प्रकाशन आरंभ: इस्तांबुल का पहला निजी तुर्की समाचार-पत्र", "24792957"], "d": ["आग़ाह एफ़ेंदी के निकाले और शिनासी के संपादकीय कार्य संभालने वाले तरजुमान-ए अहवाल राज्य की सहायता लिए बिना प्रकाशित पहला तुर्की समाचार-पत्र है। पहले अंक की भूमिका में जनता के अपने कामों पर बोलने के अधिकार का पक्ष लिया गया, पत्र ने शिनासी का 'शाइर एव्लेनमेसी' धारावाहिक छापकर आधुनिक तुर्की साहित्य का द्वार भी खोला। ऑटोमन में जनमत की अवधारणा और विरोधी प्रेस का जन्म इसी तिथि से माना जाता है।", "cc4ba4a5"]},
"OLAYLAR_EK5:1861-06-09:0":{"b": ["जबल-ए लुबनान नियमावली: लेबनान को विशेषाधिकार वाला मुतसर्रिफ़ियत दर्जा", "bf375603"], "d": ["1860 के क़त्लेआमों के बाद बड़ी शक्तियों के दबाव से तैयार नियमावली ने जबल-ए लुबनान को सीधे बाबे-आली से जुड़ी, मज़हबों के बीच संतुलन के अनुसार बनी प्रशासनिक परिषद से शासित विशेषाधिकार वाली मुतसर्रिफ़ियत बना दिया। मुतसर्रिफ़ के ऑटोमन प्रजा का कैथोलिक ईसाई होने और उसकी नियुक्ति के बड़ी शक्तियों की स्वीकृति को सौंपे जाने की शर्त रखी गई; पहले मुतसर्रिफ़ दाऊद पाशा हुए। यह व्यवस्था 1915 तक चलेगी और आधुनिक लेबनान राज्य का केंद्रक बनेगी।", "1b56a9d5"]},
"OLAYLAR_EK5:1861-06-25:0":{"b": ["अब्दुलमजीद का निधन और सुल्तान अब्दुलअज़ीज़ का राज्यारोहण", "27204d7c"], "d": ["बाईस वर्ष के शासन में तंज़ीमात और इस्लाहात फ़रमानों पर हस्ताक्षर करने वाले अब्दुलमजीद के क्षयरोग के शिकार होने पर भाई अब्दुलअज़ीज़ गद्दी पर बैठे। नए पदीशाह ने आरंभिक वर्षों में किफ़ायत के उपायों और सादे जीवन से आशा जगाई; बेड़े को दुनिया की गिनी-चुनी शक्तियों में से एक बनाया। किंतु शासन के अंत में भारी विदेशी ऋण, 1875 का दिवालियापन और बाल्कन विद्रोह जमा होकर 1876 के पदच्युत होने की ज़मीन तैयार करने वाले थे।", "1c2db3f9"]},
"OLAYLAR_EK5:1862-02-21:0":{"b": ["संयुक्त रियासतों का रोमानिया नाम लेना", "d960e3fc"], "d": ["1859 में कूज़ा के दोहरे चुनाव से वस्तुतः एक हुए वलाचिया और बोग़दान ने 1862 में अपनी सभाएँ और सरकारें बुख़ारेस्ट में एक छत्र के नीचे जुटाकर औपचारिक रूप से रोमानिया नाम लिया। ऑटोमन राज्य ने विधिक रूप से सर्वोच्च शासक की उपाधि और वार्षिक कर बनाए रखा तो भी रियासत पर वास्तविक नियंत्रण खो दिया। डैन्यूब के उत्तर के चार शताब्दी पुराने ऑटोमन प्रभाव का अंत इसी तिथि से प्रतीकित होता है।", "1693f20f"]},
"OLAYLAR_EK5:1865-01-01:0":{"b": ["सेवाकिन, मस्सावा और दहलक का मिस्र से जुड़ना", "a0924860"], "d": ["1846 में सुल्तान अब्दुलमजीद द्वारा मिस्र वाली मेहमेद अली पाशा को सेवाकिन के साथ सालियाने (आय आवंटन) के रूप में दिया गया मस्सावा, ख़िदीव इस्माईल पाशा के काल में दहलक और सेवाकिन के साथ मिस्र की संपदा में सम्मिलित करके क़ायमक़ामी दर्जे में संगठित किया गया। इस तरह लाल सागर के अफ़्रीकी तट के ये तीनों बंदरगाह विधिक रूप से ऑटोमन भूमि बने रहते हुए प्रशासनिक रूप से सीधे बाबे-आली से क़ाहिरा को चले गए — पड़ोसी मिस्र और सूडान के साथ उसी सामंत परत में आ गए।", "782199b7"]},
"OLAYLAR_EK5:1866-08-21:0":{"b": ["क्रीट विद्रोह का आरंभ (1866-1869)", "3679b861"], "d": ["यूनान के खुले समर्थन से द्वीप पर फूटे व्यापक विद्रोह ने क्रीट के यूनानियों की एनोसिस (यूनान में मिलने) की माँग को पहली बार अंतरराष्ट्रीय मसला बना दिया। तीन वर्ष चले कठिन पर्वतीय युद्ध ने ऑटोमन सेना को भारी हानि दी और यूरोपीय जनमत में बड़ी गूँज उठाई। विद्रोह केवल 1868 में आली पाशा के द्वीप जाकर व्यापक विशेषाधिकार देने वाली नियमावली लागू करने से शांत हो सका।", "eba163ff"]},
"OLAYLAR_EK5:1867-04-18:0":{"b": ["बेलग्रेड और सर्बिया के क़िलों की अंतिम ऑटोमन चौकियों का हटना", "b34217db"], "d": ["बड़ी शक्तियों के दबाव और राजकुमार मिहाइलो की आग्रही माँग पर बाबे-आली ने सर्बिया में बचे अंतिम सैन्य अड्डे ख़ाली करना स्वीकार किया; 18 अप्रैल 1867 को बेलग्रेड दुर्ग का ऑटोमन ध्वज उतारकर कुंजियाँ राजकुमार को सौंप दी गईं। इस तरह 1521 से चली आ रही वास्तविक ऑटोमन सैन्य उपस्थिति समाप्त हुई और सर्बिया के स्वतंत्रता की राह की अंतिम बड़ी बाधा हट गई। पदीशाह की सर्वोच्चता केवल प्रतीकात्मक ध्वज और कर के मसले तक सिमट गई।", "875dbecb"]},
"OLAYLAR_EK5:1867-06-08:0":{"b": ["मिस्र के वालियों को ख़िदीव उपाधि दिया जाना", "09e10c12"], "d": ["कवालाली राजवंश की तीसरी पीढ़ी के इस्माईल पाशा की भारी पैरवी और इस्तांबुल में बहाए धन के परिणामस्वरूप मिस्र वाली को, अन्य वालियों से श्रेष्ठ होने पर बल देने वाली ख़िदीव उपाधि दी गई। उन्हीं वर्षों में उत्तराधिकार की प्रथा भी पिता से पुत्र को जाने के रूप में बदली गई और मिस्र को विदेशी ऋण लेने, पदक देने, वाणिज्य दूतावास रखने जैसे संप्रभुता-स्वरूप अधिकार दिए गए। ये क़दम मिस्र के ऑटोमन से विधिक अलगाव को तेज़ करने वाली शृंखला की पहली कड़ी हैं।", "38a9a00f"]},
"OLAYLAR_EK5:1868-01-04:0":{"b": ["क्रीट नियमावली: द्वीप को व्यापक प्रशासनिक विशेषाधिकार", "12052262"], "d": ["तीन वर्ष का विद्रोह समाप्त करने के लिए वज़ीर-ए आज़म आली पाशा स्वयं द्वीप गए और पदीशाह की स्वीकृति से प्रकाशित नियमावली से क्रीटवासियों को मिश्रित प्रशासनिक परिषदें, स्थानीय न्यायालय, यूनानी भाषा का आधिकारिक कार्यों में प्रयोग और कर-सुविधाएँ दी गईं। इस व्यवस्था ने द्वीप पर ऑटोमन आधिपत्य को तीस वर्ष और खड़ा रखा। किंतु ईसाई जनसंख्या को दिए विशेषाधिकारों ने मुस्लिम क्रीटवासियों की स्थिति कमज़ोर की और 1896-1898 के संकट के बीज बोए।", "9cce04af"]},
"OLAYLAR_EK5:1868-05-10:0":{"b": ["शूरा-ए दौलत का उद्घाटन: ऑटोमन राज्य परिषद की स्थापना", "70b16497"], "d": ["5 मार्च 1868 की इरादे से मजलिस-ए अहकाम-ए अदलिये को दो भागों में बाँटकर प्रशासनिक-विधायी कार्य शूरा-ए दौलत को, न्यायिक कार्य दीवान-ए अहकाम-ए अदलिये को सौंपे गए; संस्था बाबे-आली में समारोह से खुली और पहली अध्यक्षता मिदहत पाशा को दी गई। इसे क़ानूनी मसौदे तैयार करने, प्रशासनिक विवाद सुलझाने और अधिकारियों पर मुक़दमे चलाने का दायित्व दिया गया। मुस्लिम-ग़ैर-मुस्लिम मिश्रित सदस्य संरचना के साथ यह ऑटोमन में शक्तियों के पृथक्करण के विचार का पहला संस्थागत अनुप्रयोग माना जाता है।", "c85741e0"]},
"OLAYLAR_EK5:1869-11-17:0":{"b": ["स्वेज़ नहर का उद्घाटन: मिस्र के रास्ते भारत मार्ग का छोटा होना", "377ccd04"], "d": ["1859 में आरंभ निर्माण दस वर्ष चला और भूमध्यसागर को लाल सागर से जोड़ने वाली 163 किलोमीटर की नहर भव्य समारोह से सेवा में आई। यूरोप को भारत से जोड़ने वाले मार्ग के हज़ारों मील छोटे होने पर मिस्र एक क्षण में विश्व व्यापार का कुंजी बिंदु बन गया। यह भू-रणनीतिक मूल्य नहर के उद्घाटन के तेरह वर्ष बाद इंग्लैंड के मिस्र पर क़ब्ज़े का प्रमुख कारण बनेगा; नहर का मिस्र पर डाला ऋण ख़िदीवत को दिवालियापन की ओर ले जाएगा।", "ccff3d4b"]},
"OLAYLAR_EK5:1870-03-11:0":{"b": ["बुल्गारियाई एक्सार्केट की स्थापना: बुल्गारियाई चर्च का फ़ेनेर से अलग होना", "33a8272c"], "d": ["पदीशाह के फ़रमान से यूनानी पैट्रियार्केट से अलग, स्वतंत्र बुल्गारियाई चर्च (एक्सार्केट) स्थापित हुआ और किन क़ज़ाओं को एक्सार्केट से जोड़ा जाए यह जन-मतदान पर छोड़ा गया। बाबे-आली ने यह क़दम यूनानी प्रभाव को तोड़ने के लिए उठाया तो भी परिणाम उलटा रहा: चर्च बुल्गारियाई राष्ट्रीय पहचान और मकिदुनिया पर बुल्गारियाई दावे का संगठित केंद्र बन गया। बाल्कन में बुल्गारियाई-यूनानी-सर्ब प्रतिद्वंद्विता और 1876 के विद्रोहों की संस्थागत ज़मीन इस तरह बिछ गई।", "ce8f108b"]},
"OLAYLAR_EK5:1871-01-01:0":{"b": ["असीर का सीधे प्रशासन में लिया जाना", "4559e099"], "d": ["स्वेज़ नहर के खुलने से लाल सागर का रणनीतिक मूल्य बढ़ने पर, यमन जाने वाले स्थल मार्ग के मध्य के असीर पर्वतों को अनियंत्रित न छोड़ा जा सकने की बात दिखी। यमन अभियान पर निकले रेदीफ़ पाशा की सेनाओं ने अब्हा में दाख़िल होकर क्षेत्र को सीधे ऑटोमन प्रशासन से जोड़ा और असीर संजक स्थापित हुआ। पर्वतीय भूगोल और इदरीसी प्रभाव के कारण यह आधिपत्य कभी पूरी तरह न जम सका।", "eb2bbdad"]},
"OLAYLAR_EK5:1871-04-20:0":{"b": ["मिदहत पाशा का नज्द अभियान: लहसा में ऑटोमन आधिपत्य की पुनर्स्थापना", "7db51461"], "d": ["बग़दाद वाली मिदहत पाशा ने सऊदी परिवार के भीतर के गद्दी-झगड़े का लाभ उठाकर बसरा खाड़ी के पश्चिमी तट पर सैनिक भेजे और लहसा क्षेत्र को नज्द संजक के नाम से बसरा विलायत से जोड़ा। अब्दुल्लाह बिन फ़ैसल मुतसर्रिफ़ नियुक्त किए गए और ऑटोमन आधिपत्य काग़ज़ पर स्थापित हुआ। अभियान का उद्देश्य खाड़ी में अंग्रेज़ प्रभाव के फैलाव को रोकना था और उसी वर्ष क़तर के भी ऑटोमन नियंत्रण में आने का कारण बना।", "fbc6819e"]},
"OLAYLAR_EK5:1871-09-07:0":{"b": ["वज़ीर-ए आज़म आली पाशा का निधन: तंज़ीमात कैडर का अंत", "1cf0141c"], "d": ["फ़ुआद पाशा की 1869 की मृत्यु के बाद तंज़ीमात नीति अकेले ढोने वाले आली पाशा के निधन से राज्य की विदेश नीति तीस वर्ष चलाने वाली माहिर कूटनीतिज्ञों की पीढ़ी समाप्त हो गई। उनकी जगह आए महमूद नदीम पाशा के रूस-समर्थक और मनमाने शासन ने अब्दुलअज़ीज़ के व्यक्तिगत शासन को पक्का किया। आली पाशा की मृत्यु के बाद पाँच वर्ष में वित्त दिवालिया हुआ, बाल्कन ने विद्रोह किया और शासन-परिवर्तन अनिवार्य हो गया।", "c4954cff"]},
"OLAYLAR_EK5:1871-09-20:0":{"b": ["क़तर में ऑटोमन नियंत्रण की स्थापना", "3b453165"], "d": ["अंग्रेज़ दबाव में आए शेख़ क़ासिम बिन सानी के बुलावे पर ऑटोमन सेनाएँ क़तर प्रायद्वीप में उतरीं और 1871 के पतझड़ में क्षेत्र में ऑटोमन नियंत्रण स्थापित हुआ। क़तर नज्द संजक से जुड़े क़स्बे के रूप में संगठित हुआ और शेख़ को क़ायमक़ाम नियुक्त किया गया। यह क़दम मिदहत पाशा की खाड़ी में इंग्लैंड के विरुद्ध चलाई अग्रगामी नीति की सबसे ठोस उपलब्धि बना; ऑटोमन ध्वज प्रायद्वीप में 1913 तक लहराया।", "823711c3"]},
"OLAYLAR_EK5:1871-10-24:0":{"b": ["ट्यूनिस को उत्तराधिकार का फ़रमान — बेयलिक मेहमेद सादिक़ पाशा के परिवार को", "1509ebb0"], "d": ["फ़्रांस की प्रशिया के सामने पराजय को अवसर मानने वाले ट्यूनिस बेय मेहमेद सादिक़ पाशा के इस्तांबुल भेजे ख़ैरुद्दीन पाशा के प्रयासों से निकले फ़रमान से ट्यूनिस, सीधे इस्तांबुल से जुड़ा रहते हुए, मेहमेद सादिक़ पाशा और उनकी संतान को उत्तराधिकार प्रथा से दिया गया। पदीशाह की अनुमति के बिना युद्ध और शांति वार्ता नहीं की जाएगी, देश की कोई भूमि किसी और को नहीं दी जाएगी, ऑटोमन की सैनिक माँग पूरी की जाएगी। फ़्रांस ने फ़रमान को नहीं माना; दस वर्ष बाद ट्यूनिस पर क़ब्ज़ा कर लिया।", "b72eabcc"]},
"OLAYLAR_EK5:1872-04-01:0":{"b": ["सनआ का लिया जाना: यमन में ऑटोमन अधिकार की पुनर्स्थापना", "978e20a0"], "d": ["स्वेज़ नहर के खुलने से लाल सागर का रणनीतिक मूल्य बढ़ने पर बाबे-आली ने यमन में अहमद मुख़्तार पाशा की कमान में फ़िरक़ा-ए इह्तियातिये सेना भेजी। सनआ पर क़ब्ज़े से दो शताब्दी से वस्तुतः खोए भीतरी यमन में राज्य का अधिकार फिर स्थापित हुआ और क्षेत्र को विलायत बनाया गया। किंतु ज़ैदी इमामों से संघर्ष कभी समाप्त नहीं हुआ; 1891, 1898 और 1904 के विद्रोह ऑटोमन के सबसे महँगे और सबसे लंबे चले आंतरिक मोर्चे बने। उसी तिथि को शामिल हुए अन्य स्थान: सनआ, ताइज़।", "2173d1a2"]},
"OLAYLAR_EK5:1875-06-19:0":{"b": ["हर्ज़ेगोविना विद्रोह का आरंभ: पूर्वी प्रश्न का फिर भड़कना", "571b18ec"], "d": ["भारी करों और अयान के दबाव से नेवेसिन्ये के आसपास के ईसाई किसानों का विद्रोह शीघ्र पूरे हर्ज़ेगोविना में फैल गया और सर्बिया तथा मोंटेनेग्रो से आए स्वयंसेवकों से पोषित हुआ। ऑस्ट्रिया और रूस के सुधार थोपने का कारण बना यह विद्रोह अगले वर्ष बुल्गारियाई विद्रोहों और सर्ब-मोंटेनेग्रो युद्ध घोषणाओं का कारण बना। इस तरह 93 युद्ध और बर्लिन संधि से बाल्कन की हानि तक पहुँचाने वाली बड़ी शृंखला की पहली कड़ी बनी।", "821a20d9"]},
"OLAYLAR_EK5:1875-10-06:0":{"b": ["ऑटोमन वित्त का दिवालियापन: विदेशी ऋण भुगतान आधे किए गए", "2cac2fa5"], "d": ["1854 से लगातार लिए गए ऋण, क्रीमिया युद्ध के ख़र्च, सराय निर्माण और 1873-74 के अनातोलिया अकाल ने बजट घाटे को पचास लाख लीरा से अधिक की खाई में बदल दिया। महमूद नदीम पाशा सरकार ने ऋण ब्याज और मूलधन के भुगतान पाँच वर्ष के लिए आधे किए जाने की घोषणा करके वस्तुतः मोरेटोरियम घोषित किया। यूरोपीय शेयर बाज़ारों में बड़ी प्रतिक्रिया जगाने वाले इस निर्णय ने छह वर्ष बाद मुहर्रम फ़रमान और दयून-ए उमूमिये की स्थापना में परिणत होने वाली प्रक्रिया आरंभ की।", "a6706632"]},
"OLAYLAR_EK5:1876-08-31:0":{"b": ["मुराद पंचम का पदच्युत होना और अब्दुलहमीद द्वितीय का राज्यारोहण", "cffb2271"], "d": ["अब्दुलअज़ीज़ के गद्दी से उतारे जाने के बाद बैठे मुराद पंचम, चाचा की मृत्यु और चेरकेज़ हसन घटना से हिली मानसिक स्थिति के कारण कार्य करने में अक्षम हो गए; तिरानवे दिन के शासन में केवल सात दिन ही उनका विवेक ठीक रहा। शेख़ुल-इस्लाम के फ़तवे से पदच्युत होकर उनकी जगह भाई अब्दुलहमीद द्वितीय लाए गए। नए पदीशाह गद्दी पर मिदहत पाशा को संविधान घोषित करने का वचन देकर बैठे; तैंतीस वर्ष चलने वाला दौर आरंभ हो रहा था।", "9904ab70"]},
"OLAYLAR_EK5:1876-12-23:0":{"b": ["तरसाने सम्मेलन: बड़ी शक्तियों का बाल्कन सुधार थोपना", "b5006a2c"], "d": ["बाल्कन संकट सुलझाने के लिए बड़ी शक्तियों के इस्तांबुल में जुटाए सम्मेलन ने बुल्गारिया के दो स्वायत्त विलायतों में बँटने और बोस्निया-हर्ज़ेगोविना में अंतरराष्ट्रीय निगरानी में सुधार लागू करने की माँग की। बाबे-आली ने सम्मेलन के आरंभ के दिन तोप दागकर क़ानून-ए असासी की घोषणा सुनाई और थोपे गए प्रस्तावों का उत्तर संवैधानिक सुधार से देने का प्रयास किया। प्रतिनिधियों ने इसे टालमटोल मानकर 20 जनवरी 1877 को सम्मेलन समाप्त किया; चार माह बाद रूस ने युद्ध घोषित किया।", "8149c00f"]},
"OLAYLAR_EK5:1877-03-19:0":{"b": ["पहली मजलिस-ए मेबऊसान का दोलमाबाहचे में उद्घाटन", "429bb279"], "d": ["क़ानून-ए असासी के अनुसार चुने गए 115 मेबऊस 19 मार्च 1877 को दोलमाबाहचे सराय के मुआयदे हॉल में हुए समारोह से पहली बार जुटे; इस तरह ऑटोमन इतिहास में प्रतिनिधि सभा का दौर आरंभ हुआ। मुस्लिम और ग़ैर-मुस्लिम मेबऊसों ने सरकार से कठोर पूछताछ की, युद्ध के संचालन और नाज़िरों के उत्तरदायित्व पर बहस की। यह साहसी विरोध सभा की आयु घटाने का प्रमुख कारण बनने वाला था।", "df95fa07"]},
"OLAYLAR_EK5:1877-07-19:0":{"b": ["प्लेवना रक्षा का आरंभ: ग़ाज़ी उस्मान पाशा का प्रतिरोध", "0e04a878"], "d": ["93 युद्ध में डैन्यूब पार करने वाली रूसी सेना के इस्तांबुल मार्ग को काटने के लिए विदिन से प्लेवना की ओर बढ़े उस्मान पाशा ने क़स्बे को तबिया और खाइयों से क़िलेबंद करके पाँच माह की दंतकथात्मक रक्षा आरंभ की। लगातार तीन बड़े रूसी-रोमानियाई आक्रमण भारी हानि के साथ खदेड़े गए और ज़ार अलेक्सांद्र द्वितीय की स्वयं संचालित सेना को घेराबंदी के लिए विवश होना पड़ा। प्लेवना, ऑटोमन सेना की 19वीं शताब्दी की सबसे चमकदार रक्षा सफलता के रूप में इतिहास में दर्ज हुआ।", "5a86466f"]},
"OLAYLAR_EK5:1877-12-10:0":{"b": ["प्लेवना का पतन: डैन्यूब मोर्चे का ढहना", "185e7602"], "d": ["पाँच माह की घेराबंदी में रसद ख़त्म होने पर उस्मान पाशा ने विद नदी की ओर से निकास-अभियान (हुरूच) किया; घायल होकर बंदी बने तो नगर ने आत्मसमर्पण किया। रूसी सेनापतियों ने बंदी बनाए पाशा को तलवार लौटाकर सलाम किया और उस्मान पाशा को 'ग़ाज़ी' उपाधि दी गई। प्लेवना के पतन से रूसी सेना का मार्ग खुल गया; दो माह में सोफ़िया, फ़िलिबे और एदिर्ने गिर गए, रूसी अग्रदल येशिलकोय तक पहुँच गए।", "fc075756"]},
"OLAYLAR_EK5:1878-01-04:0":{"b": ["सोफ़िया पर रूसी सेनाओं का क़ब्ज़ा", "ef369d22"], "d": ["प्लेवना के पतन के बाद बाल्कन पार करने वाली रूसी सेना असुरक्षित रह गए सोफ़िया में दाख़िल हुई। नगर फिर कभी ऑटोमन प्रशासन में नहीं लौटेगा, 1878 के अंत में स्वायत्त बुल्गारिया रियासत का और 1879 में वस्तुतः उसकी राजधानी बनेगा। मानचित्र में सोफ़िया इस तिथि से ऑटोमन सीधे प्रशासन से निकलकर अस्थायी रूसी क़ब्ज़े में और उसके बाद स्वायत्त बुल्गारियाई प्रशासन में चला जाता है।", "66b1da91"]},
"OLAYLAR_EK5:1878-01-31:0":{"b": ["एदिर्ने युद्धविराम: 93 युद्ध में हथियारों का थमना", "1f899180"], "d": ["सोफ़िया, फ़िलिबे और एदिर्ने के एक-एक करके गिरने और रूसी सेना के मरमरा तटों तक आ पहुँचने पर बाबे-आली को युद्धविराम माँगना पड़ा। एदिर्ने में हस्ताक्षरित संघर्ष-विराम ने बुल्गारिया को स्वायत्तता, मोंटेनेग्रो-सर्बिया-रोमानिया की स्वतंत्रता और भारी युद्ध-क्षतिपूर्ति जैसी प्रारंभिक शांति शर्तें ऑटोमन को मनवाईं। ये शर्तें एक माह बाद अयस्तेफ़ानोस में संधि-पाठ बनने वाली थीं।", "49d61081"]},
"OLAYLAR_EK5:1878-02-13:0":{"b": ["अब्दुलहमीद द्वितीय का मजलिस-ए मेबऊसान को अनिश्चित काल के लिए स्थगित करना", "e770b540"], "d": ["युद्ध के विपत्ति में समाप्त होने के लिए सरकार और सराय को उत्तरदायी ठहराने वाले मेबऊसों की कठोर आलोचना पर अब्दुलहमीद द्वितीय ने क़ानून-ए असासी से मिले अधिकार के आधार पर सभा को अनिश्चित काल के लिए स्थगित कर दिया। लगभग ग्यारह माह चली पहली ऑटोमन संसद इस तरह बंद हुई और तीस वर्ष चलने वाला निरंकुशता (इस्तिबदाद) का दौर आरंभ हुआ। सभा केवल 1908 की क्रांति के बाद फिर जुट सकेगी।", "dd2e6d60"]},
"OLAYLAR_EK5:1878-03-03:0":{"b": ["अयस्तेफ़ानोस संधि: बृहत बुल्गारिया की योजना", "2c7cc611"], "d": ["93 युद्ध समाप्त करने वाली अयस्तेफ़ानोस संधि एजियन तक फैला और मकिदुनिया को समेटने वाला विशाल स्वायत्त बुल्गारिया बनाती थी; सर्बिया, मोंटेनेग्रो और रोमानिया की स्वतंत्रता मानती थी; कार्स, अर्दाहान, बातुम और दोग़ुबायज़ीत रूस को छोड़ती थी, साथ ही चुकाना असंभव युद्ध-क्षतिपूर्ति थोपती थी। रूस को भूमध्यसागर तक उतारने वाले इस पाठ ने इंग्लैंड और ऑस्ट्रिया की तीव्र प्रतिक्रिया जगाई। लागू हुए बिना चार माह में बर्लिन कांग्रेस से पुनर्व्यवस्थित हुई; फिर भी ऑटोमन रुमेली के अंत की घोषणा करने वाले दस्तावेज़ के रूप में बनी रही।", "dfd3e7f4"]},
"OLAYLAR_EK5:1878-07-13:0":{"b": ["कार्स, अर्दाहान और बातुम रूस को छोड़े गए — एलविये-ए सलासे", "99bdfad2"], "d": ["बर्लिन संधि से ऑटोमन राज्य ने कार्स, अर्दाहान और बातुम युद्ध-क्षतिपूर्ति के एक भाग के बदले रूस को छोड़ दिए; अयस्तेफ़ानोस में रूस को दी गई दोग़ुबायज़ीत और एलेश्किर्त घाटी ऑटोमन में रही। बातुम मुक्त बंदरगाह के रूप में दिया गया तो भी यह दर्जा केवल 1886 तक बनाए रख सका। रूसियों ने कार्स को केंद्र तिफ़्लिस वाले ट्रांसकॉकेशिया गवर्नर-जनरलशिप से जुड़ा प्रांत बनाया; एलविये-ए सलासे से एक लाख तक पहुँचती जनसंख्या को एरज़ुरुम की ओर पलायन करना पड़ा। उसी संधि से दक्षिणी बेसाराबिया (किली, काहुल, बोल्ग्राद) रोमानिया से रूस को लौटाया गया।", "867dda58"]},
"OLAYLAR_EK5:1878-07-29:0":{"b": ["बोस्निया-हर्ज़ेगोविना और येनिपज़ार पर ऑस्ट्रिया-हंगरी का क़ब्ज़ा", "e5f901df"], "d": ["बर्लिन संधि से मिले अधिकार के आधार पर ऑस्ट्रिया-हंगरी की सेनाएँ बोस्निया में घुसीं; ऑटोमन सरकार के विरोध न करने पर सहमत होने के बावजूद साराएवो और मोस्तार की स्थानीय मुस्लिम-ऑर्थोडॉक्स जनता ने शस्त्र उठाकर तीन माह कठिन प्रतिरोध दिखाया। क़ब्ज़ा केवल 20 अक्तूबर 1878 को पूरा हो सका। पदीशाह की विधिक संप्रभुता 1908 तक काग़ज़ पर चलती रही, किंतु चार शताब्दी का ऑटोमन बोस्निया वस्तुतः हाथ से निकल गया और बड़ी मुस्लिम प्रवास लहर आरंभ हुई। उसी तिथि को हाथ से निकले अन्य स्थान: बान्यालुका।", "9d6a9e57"]},
"OLAYLAR_EK5:1881-12-20:0":{"b": ["मुहर्रम फ़रमान और दयून-ए उमूमिये प्रशासन की स्थापना", "02b7cc03"], "d": ["1875 के दिवालियेपन के बाद ऋणदाता राज्यों के प्रतिनिधियों से चली वार्ताएँ 28 मुहर्रम 1299 (20 दिसंबर 1881) के फ़रमान में परिणत हुईं: ऋण का मूलधन आधे से अधिक घटाया गया, इसके बदले नमक, तंबाकू, रेशम, स्टाम्प और मछली कर जैसे सबसे उपजाऊ आय-मद सीधे ऋणदाताओं के प्रबंधित दयून-ए उमूमिये प्रशासन को सौंपे गए। हज़ारों अधिकारी रखने वाला यह प्रशासन राज्य के भीतर अलग वित्त संगठन बन गया। इसे ऑटोमन वित्तीय स्वतंत्रता के वस्तुतः समाप्त होने की तिथि माना जाता है।", "3cb26eeb"]},
"OLAYLAR_EK5:1884-02-01:0":{"b": ["सेवाकिन — महदी के हाथ न गिरने वाला एकमात्र बंदरगाह", "5a37b198"], "d": ["1884 फ़रवरी से सेवाकिन के अतिरिक्त पूरे पूर्वी सूडान क्षेत्रों के मुहम्मद अहमद अल-महदी के आधिपत्य में चले जाने पर बंदरगाह जनरल ग्राहम की कमान की तीन बटालियन की अंग्रेज़ सेना के सैन्य संरक्षण से टिका रहा। यह वास्तविक और विधिक स्थिति के अलग होने वाले दौर का आरंभ था: तट वस्तुतः अंग्रेज़ सैन्य नियंत्रण में होने पर भी प्रशासनिक संबंध 1885 में मिस्र से लेकर सीधे यमन विलायत, यानी बाबे-आली से जोड़ा जाएगा — वह व्यवस्था 1888 में फ़्रांस के ज़ेयला पर क़ब्ज़े से समाप्त होने तक चली।", "343c16cf"]},
"OLAYLAR_EK5:1884-05-08:0":{"b": ["मिदहत पाशा की ताइफ़ क़ैदख़ाने में हत्या", "f4562261"], "d": ["क़ानून-ए असासी के शिल्पी और प्रथम मशरूतियत के प्रतीक मिदहत पाशा अब्दुलअज़ीज़ की मृत्यु से जुड़े यिल्दिज़ मुक़दमे में दोषी पाए जाकर मृत्युदंड के निर्वासन में बदले जाने पर ताइफ़ भेजे गए थे। TDV अभिलेख के अनुसार 7-8 मई 1884 की रात कोठरी में गला घोंटकर मारे गए, आधिकारिक कारण 'शीरपंजे' रोग बताया गया। उनकी मृत्यु अब्दुलहमीद द्वितीय काल में संवैधानिक विरोध के सफ़ाए का प्रतीक बन गई।", "06cc8d1c"]},
"OLAYLAR_EK5:1888-09-24:0":{"b": ["हैदरपाशा-अंकारा रेलवे रियायत का जर्मनों को दिया जाना", "5705b163"], "d": ["पदीशाह के इरादे से हैदरपाशा-अंकारा लाइन के निर्माण और संचालन की रियायत डॉयचे बैंक का प्रतिनिधित्व करने वाले बैंकर आल्फ़्रेड फ़ॉन कौला को दी गई और अनातोलिया रेलवे कंपनी स्थापित हुई। यह रियायत ऑटोमन परिवहन और विदेश नीति में अंग्रेज़-फ़्रांसीसी एकाधिकार तोड़कर जर्मन प्रभाव जमाने वाला मोड़ बनी। ग्यारह वर्ष बाद उसी कंपनी को दी जाने वाली बग़दाद लाइन रियायत के साथ 'बर्लिन-बग़दाद' का स्वप्न जन्मेगा, जो प्रथम विश्व युद्ध से पहले की बड़ी शक्ति प्रतिद्वंद्विता की मुख्य धुरियों में से एक बनने वाला था।", "9974f219"]},
"OLAYLAR_EK5:1889-06-02:0":{"b": ["इत्तिहाद-ए उस्मानी जमाअत की इस्तांबुल में स्थापना", "b7187939"], "d": ["सैन्य चिकित्सा विद्यालय के चार विद्यार्थियों ने इस्तिबदाद शासन के विरुद्ध गुप्त संगठन के रूप में इत्तिहाद-ए उस्मानी जमाअत स्थापित की; यह संरचना शीघ्र जोन तुर्क आंदोलन के सभी विरोधी तत्वों को अपने छत्र में जुटाने वाली इत्तिहाद वे तरक़्क़ी जमाअत में बदल गई। प्रकोष्ठ-आधारित संगठन यूरोप के निर्वासितों और सलोनिका के अधिकारियों से मिल गया। 1908 में द्वितीय मशरूतियत की घोषणा करवाने और 1913 के बाद राज्य को अकेले चलाने वाला कैडर इसी छोटे विद्यार्थी प्रकोष्ठ से निकला।", "f2417434"]},
"OLAYLAR_EK5:1896-08-26:0":{"b": ["ऑटोमन बैंक छापा: दाशनाक कार्यकर्ताओं की गलाता कार्रवाई", "08b3095f"], "d": ["आर्मेनियाई दाशनाकसूत्युन संगठन के सशस्त्र समूह ने यूरोप का ध्यान आर्मेनियाई मसले की ओर खींचने के उद्देश्य से गलाता के ऑटोमन बैंक मुख्यालय पर छापा मारकर बंधक बनाए और इमारत को उड़ाने की धमकी दी। संकट राजदूतों के बीच पड़ने से कार्यकर्ताओं को जहाज़ से देश से बाहर भेजे जाने के बदले समाप्त हुआ। छापे के बाद के दिनों में इस्तांबुल में हुई ख़ूनी घटनाएँ आर्मेनियाई मसले के अंतरराष्ट्रीय हस्तक्षेप के उत्तोलक में बदलने में निर्णायक रहीं।", "8fb5eb98"]},
"OLAYLAR_EK5:1897-04-17:0":{"b": ["1897 ऑटोमन-यूनानी युद्ध का आरंभ: थेसली मोर्चा", "33e490ab"], "d": ["यूनान के क्रीट पर बेड़ा और सैनिक उतारने तथा रुमेली सीमा पर गिरोह हमलों पर ऑटोमन राज्य ने युद्ध घोषित किया। जर्मन सुधार मिशन से प्रशिक्षित ऑटोमन सेना थेसली में तेज़ी से बढ़कर एक माह में येनिशेहिर, चतालजा और दोमेके ले आई; यूनानी सेना बिखर गई। बड़ी शक्तियों के बीच पड़ने से जीती भूमि लौटाई गई, किंतु युद्ध अब्दुलहमीद द्वितीय काल की एकमात्र निश्चित सैन्य विजय बना रहा और क्रीट की वास्तविक हानि को न रोक सका।", "405fd8a7"]},
"OLAYLAR_EK5:1899-11-27:0":{"b": ["कोन्या-बग़दाद रेलवे रियायत का जर्मनों को दिया जाना", "fd8b6cbd"], "d": ["कैसर विल्हेल्म द्वितीय की 1898 की इस्तांबुल और दमिश्क़ यात्रा के बाद अनातोलिया रेलवे कंपनी को कोन्या से बग़दाद और बसरा तक जाने वाली लाइन की प्रारंभिक रियायत दी गई। बग़दाद रेलवे परियोजना ऑटोमन के लिए अरब विलायतों पर केंद्रीय नियंत्रण को सुदृढ़ करने, जर्मनी के लिए बसरा खाड़ी तक पहुँचने का अर्थ रखती थी। इंग्लैंड और रूस के तीव्र विरोध वाली यह परियोजना प्रथम विश्व युद्ध की ओर बढ़ती साम्राज्यवादी प्रतिद्वंद्विता की सबसे विवादित फ़ाइलों में से एक बनी।", "0de9d1cf"]},
"OLAYLAR_EK5:1900-09-01:0":{"b": ["हिजाज़ रेलवे निर्माण का दमिश्क़ में आरंभ", "62f58f68"], "d": ["अब्दुलहमीद द्वितीय के 2 मई 1900 के इरादे से आदेशित लाइन का निर्माण 1 सितंबर 1900 को दमिश्क़ में हुए औपचारिक समारोह से आरंभ हुआ। पूरी तरह इस्लामी जगत से जुटाए दान और ऑटोमन इंजीनियर-सैनिकों के श्रम से बनी परियोजना ने हाजियों की दमिश्क़-मदीना यात्रा चालीस दिन से घटाकर पाँच दिन कर दी। यह ख़िलाफ़त के नैतिक अधिकार को सुदृढ़ करने वाली प्रतिष्ठा-कृति और हिजाज़ पर सैन्य नियंत्रण को सशक्त करने वाला रणनीतिक निवेश दोनों था।", "449890c9"]},
"OLAYLAR_EK5:1903-10-02:0":{"b": ["म्युर्ज़्स्टेग कार्यक्रम: मकिदुनिया में अंतरराष्ट्रीय सुधार निगरानी", "4c7464da"], "d": ["इलिंदेन विद्रोह के बाद रूसी और ऑस्ट्रियाई सम्राटों ने म्युर्ज़्स्टेग में मिलकर मकिदुनिया के लिए नया सुधार पैकेज तैयार किया। कार्यक्रम में ऑटोमन महानिरीक्षक के साथ दो विदेशी नागरिक एजेंट बैठाने, जेंडार्मरी को यूरोपीय अधिकारियों से पुनर्गठित करने और प्रशासनिक सीमाएँ राष्ट्रीयता के आधार पर बदलने का प्रावधान था। बाबे-आली ने संप्रभुता अधिकारों के आहत होने के आधार पर विरोध किया तो भी संयुक्त दबाव के सामने स्वीकार करना पड़ा; कार्यक्रम युवा अधिकारियों में इत्तिहादी संगठन को तेज़ करने वाले मूल कारकों में से एक बना।", "b56ab15c"]},
"OLAYLAR_EK5:1904-08-29:0":{"b": ["मुराद पंचम का निधन", "396659a7"], "d": ["1876 में तीन माह के क़रीब गद्दी पर रहकर पदच्युत किए गए मुराद पंचम ने, उन्हें फिर गद्दी पर बिठाने के प्रयासों के बाद कड़े पहरे में अट्ठाईस वर्ष बंदी जीवन बिताया और मधुमेह से चल बसे। येनिजामी के जदीद हवातीन मक़बरे में माता के पास दफ़नाए गए। गद्दी पर सबसे कम रहने वाले ऑटोमन पदीशाह के रूप में इतिहास में दर्ज हुए।", "8558c1b8"]},
"OLAYLAR_EK5:1905-04-01:0":{"b": ["सनआ का इमाम याह्या के हाथ जाना", "e7f876cb"], "d": ["ज़ैदी इमाम याह्या हमीदुद्दीन के 1904 में आरंभ विद्रोह का अंत अप्रैल 1905 में सनआ के घेराबंदी के बाद गिरने से हुआ; नगर ऑटोमन प्रशासन से निकल गया और घेराबंदी के दौरान भूख और महामारी फैली। यमन की पर्वतीय भौगोलिक स्थिति, रसद रेखाओं की लंबाई और ज़ैदी इमामत की स्थानीय वैधता यहाँ के ऑटोमन आधिपत्य को स्थापना से ही नाज़ुक बनाए रहे। नगर पाँच माह बाद भारी हानि की क़ीमत पर वापस लिया जाएगा, किंतु यमन समस्या 1918 तक बंद नहीं होगी।", "702b0ff5"]},
"OLAYLAR_EK5:1905-07-21:0":{"b": ["यिल्दिज़ हत्या-प्रयास: अब्दुलहमीद द्वितीय पर बम हमला", "1ee2e1a6"], "d": ["दाशनाकसूत्युन संगठन ने जुमे की सलामी से निकले पदीशाह की गाड़ी के पास घड़ी वाले बम से भरी एक बग्घी को फोड़कर हत्या का प्रयास किया; अब्दुलहमीद का शेख़ुल-इस्लाम से बात करने के कारण कुछ मिनट देर से निकलना उनके प्राण बचा गया। विस्फोट में छब्बीस लोग मरे, पचास से अधिक घायल हुए। घटना ने पदीशाह की सुरक्षा-सनक और जासूसी संगठन पर आधारित इस्तिबदाद शासन को और कठोर किया; तेवफ़ीक़ फ़िक्रेत की 'बिर लहज़ा-ए ताअख़्ख़ुर' कविता का भी विषय बनी।", "d4f10280"]},
"OLAYLAR_EK5:1905-09-01:0":{"b": ["सनआ की वापसी: इमाम याह्या विद्रोह का दमन", "dec3b8f9"], "d": ["1904 में ज़ैदी इमाम याह्या के नेतृत्व में आरंभ विद्रोह अप्रैल 1905 में सनआ के गिरने से परिणत हुआ और नगर में भूख तथा महामारी फैली। अली रिज़ा पाशा और अहमद फ़ेव्ज़ी पाशा की कमान की अतिरिक्त सेनाओं ने 15 जुलाई - 1 सितंबर 1905 के बीच चलाए और ताइज़ की सेनाओं से भी समर्थित अभियान से भारी हानि की क़ीमत पर नगर वापस लिया और विद्रोह कुचला। यमन अभियान ने ऑटोमन सेना को दसियों हज़ार हानि और विशाल वित्तीय बोझ दिया; रुमेली के अधिकारियों में 'यमन निर्वासन' का भय इत्तिहादी संगठन को पोषित करने वाली शिकायतों में सबसे ऊपर था।", "667bb98c"]},
"OLAYLAR_EK5:1908-12-17:0":{"b": ["द्वितीय मशरूतियत की पहली मजलिस-ए मेबऊसान का जुटना", "e7fd2716"], "d": ["तीस वर्ष के अंतराल के बाद हुए दो-चरणीय चुनावों से बनी सभा 17 दिसंबर 1908 को पदीशाह के भाषण से खुली और अध्यक्षता जोन तुर्क आंदोलन के नेता अहमद रिज़ा बेय को मिली। तुर्क, अरब, अल्बानियाई, यूनानी, आर्मेनियाई और यहूदी मेबऊसों से बनी सभा ऑटोमनवाद के आदर्श का अंतिम बड़ा प्रयोग थी। किंतु बुल्गारिया की स्वतंत्रता, बोस्निया का विलय और क्रीट के यूनान में मिलने की घोषणा ने सभा के खुलने से पहले ही इस आशावाद को धुँधला कर दिया था।", "b408f232"]},
"OLAYLAR_EK5:1909-04-27:0":{"b": ["हरकत ऑर्दुसू और अब्दुलहमीद द्वितीय का पदच्युत होना: मेहमेद पंचम रेशाद का राज्यारोहण", "6a65a704"], "d": ["31 मार्च घटना पर सलोनिका से चली हरकत ऑर्दुसू 22-23 अप्रैल की रात चार दिशाओं से इस्तांबुल में दाख़िल हुई और 24 अप्रैल को यिल्दिज़ सराय ने समर्पण किया। मजलिस-ए उमूमी-ए मिल्ली ने 27 अप्रैल को अब्दुलहमीद द्वितीय को पदच्युत करने का निर्णय लिया; पदीशाह सलोनिका भेजे गए, उनकी जगह भाई मेहमेद पंचम रेशाद गद्दी पर बिठाए गए। तैंतीस वर्ष का व्यक्तिगत शासन इस तरह समाप्त हुआ, किंतु उसकी जगह पदीशाह के प्रतीक बन जाने और इत्तिहाद वे तरक़्क़ी के सेना समर्थन से शासन चलाने वाले नए दौर ने ले ली।", "496ff2f2"]},
"OLAYLAR_EK5:1910-04-01:0":{"b": ["अल्बानिया विद्रोह: कोसोवो और इश्कोदरा में सशस्त्र प्रतिरोध", "93ed30c6"], "d": ["इत्तिहादी सरकार की केंद्रीकरण-आधारित कर नीति, हथियार जमा करने के अभियान और लैटिन वर्णमाला की बहस ने उस दिन तक राज्य के सबसे निष्ठावान तत्वों में गिने जाने वाले अल्बानियाई क़बीलों को विद्रोह के लिए उठाया। महमूद शेवकेत पाशा की कमान की सेना ने विद्रोह कठोरता से कुचला तो भी अशांति 1911 और 1912 में फिर भड़की। इन विद्रोहों ने ऑटोमन सेना को बाल्कन युद्ध की पूर्वसंध्या पर थकाया और अल्बानियाई राष्ट्रीय आंदोलन के जन्म को भी तेज़ किया।", "18d0ffb5"]},
"OLAYLAR_EK5:1912-10-18:0":{"b": ["ऊशी संधि: त्रिपोलीतानिया और बेनग़ाज़ी का इटली को छोड़ा जाना", "4ffa1fd2"], "d": ["बाल्कन राज्यों की युद्ध तैयारी के सामने दो मोर्चों का संघर्ष न झेल सकने वाले बाबे-आली ने स्विट्ज़रलैंड के ऊशी क़स्बे में इटली से गुप्त शांति हस्ताक्षरित करके त्रिपोलीतानिया और बेनग़ाज़ी छोड़ दिए। ऑटोमन राज्य ने अफ़्रीका की अपनी अंतिम भूमि इस तरह खो दी; इसके बदले इटली के क़ब्ज़े वाले रोड्स और बारह द्वीपों की वापसी का वादा हुआ तो भी वह वादा कभी पूरा नहीं हुआ। संधि हस्ताक्षरित होते समय बाल्कन युद्ध कब का आरंभ हो चुका था। इस घटना से मुर्ज़ुक़ (फ़ेज़ान), ग़ात, सब्हा, उबारी, तिर्गान (Traghan), ज़वीला (Zawila) और अल-क़त्रून (फ़ेज़ान (त्रिपोलीतानिया विलायत का संजक)) इटली के प्रशासन में चले गए।", "8294687e"]},
"OLAYLAR_EK5:1912-10-21:0":{"b": ["लिम्नी पर यूनानी क़ब्ज़ा", "9555af1d"], "d": ["प्रथम बाल्कन युद्ध में यूनानी बेड़े ने लिम्नी पर क़ब्ज़ा किया; द्वीप का मूद्रोस बंदरगाह चानाक्काले जलडमरूमध्य की नाकाबंदी के लिए अड्डा बना। द्वीप लोज़ान में (24 जुलाई 1923) यूनान को छोड़ा गया।", "61677826"]},
"OLAYLAR_EK5:1912-10-30:0":{"b": ["ताशोज़ पर यूनानी क़ब्ज़ा", "6c03c7f0"], "d": ["प्रथम बाल्कन युद्ध में यूनान ने ताशोज़ और समादिरेक पर क़ब्ज़ा किया।", "b0695c7a"]},
"OLAYLAR_EK5:1912-11-01:0":{"b": ["समादिरेक पर यूनानी क़ब्ज़ा", "911e82a3"], "d": ["प्रथम बाल्कन युद्ध में यूनान ने समादिरेक पर क़ब्ज़ा किया।", "0e592cf7"]},
"OLAYLAR_EK5:1912-11-21:0":{"b": ["मिदिल्ली पर यूनानी क़ब्ज़ा", "6b2b07ba"], "d": ["यूनानी बेड़ा मिदिल्ली में उतरा; द्वीप प्रथम बाल्कन युद्ध के अंत में यूनानी सेना और बेड़े द्वारा क़ब्ज़े में लिया गया। लंदन सम्मेलन (मई 1913) ने स्थिति की पुष्टि की।", "a07eeadb"]},
"OLAYLAR_EK5:1912-11-25:0":{"b": ["साकिज़ पर यूनानी अवतरण", "901c6539"], "d": ["प्रथम बाल्कन युद्ध में 7 अप्रैल 1912 को बमबारी झेल चुके साकिज़ पर यूनानियों ने उतरकर क़ब्ज़ा किया; ऑटोमन चौकी ने 3 जनवरी 1913 को समर्पण किया। द्वीप लोज़ान संधि (24 जुलाई 1923) से यूनान को छोड़ा गया।", "d9fc9f4b"]},
"OLAYLAR_EK5:1913-06-11:0":{"b": ["वज़ीर-ए आज़म महमूद शेवकेत पाशा की इस्तांबुल में हत्या", "68e60e63"], "d": ["बाबे-आली छापे के बाद वज़ीर-ए आज़म बनाए गए महमूद शेवकेत पाशा युद्ध मंत्रालय जाते समय चारशिकापी के निकट गाड़ी पर खुली गोलीबारी से मारे गए। इत्तिहाद वे तरक़्क़ी ने हत्या का आरोप विपक्ष पर डालकर व्यापक गिरफ़्तारी और मृत्युदंड की लहर आरंभ की, हुर्रियत वे इतिलाफ़ पार्टी वस्तुतः समाप्त कर दी गई। इस घटना के साथ इत्तिहादियों की एनवर-तलअत-जेमाल की तिकड़ी पर आधारित एकदलीय तानाशाही निश्चित रूप से स्थापित हुई।", "203085f0"]},
"OLAYLAR_EK5:1913-06-29:0":{"b": ["द्वितीय बाल्कन युद्ध का आरंभ: सहयोगियों की बँटवारा कलह", "48d088a2"], "d": ["लंदन संधि से ऑटोमन से पाई भूमि का बँटवारा न कर पाने वाले बाल्कन सहयोगी आपस में भिड़ गए; बुल्गारिया के सर्ब और यूनानी मोर्चों पर आक्रमण करने से दूसरा युद्ध आरंभ हुआ। रोमानिया और मोंटेनेग्रो के भी बुल्गारिया के विरुद्ध मोर्चे में उतरने पर बुल्गारियाई सेना ढह गई। ऑटोमन राज्य ने इस अवसर का लाभ उठाकर लंदन संधि की खींची मिदये-एनेज़ रेखा को पार किया और पूर्वी थ्रेस को एदिर्ने के साथ वापस ले लिया।", "33183400"]},
"OLAYLAR_EK5:1913-09-29:0":{"b": ["इस्तांबुल संधि: बुल्गारिया से शांति और एदिर्ने का पंजीकरण", "c8c18b2d"], "d": ["द्वितीय बाल्कन युद्ध के बाद ऑटोमन राज्य और बुल्गारिया के बीच हस्ताक्षरित संधि ने मेरिच नदी को सीमा मानकर एदिर्ने, किरक्लारेली, दिमेतोका और पूर्वी थ्रेस के ऑटोमन में रहने को विधिक रूप से पंजीकृत किया। देदेआग़ाच बुल्गारिया में छोड़ा गया (कवाला 1912 के पतझड़ के बुल्गारियाई क़ब्ज़े के बाद जुलाई 1913 में यूनान को चला गया था और 10 अगस्त 1913 की बुख़ारेस्ट संधि से यूनान में पंजीकृत हुआ था), दोनों देशों के बीच पारस्परिक जनसंख्या अदला-बदली और बुल्गारिया के मुसलमानों के अधिकार तय किए गए। बाल्कन विपत्ति से वापस लिए जा सके एकमात्र भूमि-खंड की गारंटी यही पाठ है। उसी तिथि को शामिल हुए अन्य स्थान: गुमुलजिने।", "1fe8a2f6"]},
"OLAYLAR_EK5:1913-11-01:0":{"b": ["बोज़जाअदा और इम्रोज़ की वापसी — एथेंस संधि", "ec084d09"], "d": ["बाल्कन युद्ध में यूनान के क़ब्ज़े में गए उत्तरी एजियन द्वीपों में से जलडमरूमध्य के मुहाने को थामे बोज़जाअदा और इम्रोज़, एथेंस संधि वार्ताओं में चानाक्काले की रक्षा के लिए अपरिहार्य माने गए और ऑटोमन को लौटाए गए। अन्य द्वीप यूनान में रहे। ये दो द्वीप साम्राज्य के एजियन में हाथ में रहे अंतिम भूखंड रहे और लोज़ान में भी तुर्की को छोड़े गए।", "bc1961ea"]},
"OLAYLAR_EK5:1913-11-14:0":{"b": ["एथेंस संधि: यूनान से शांति और सलोनिका-यानिया का हस्तांतरण", "8e94def7"], "d": ["ऑटोमन राज्य और यूनान के बीच हस्ताक्षरित संधि ने बाल्कन युद्ध में खोए सलोनिका, यानिया और दक्षिणी मकिदुनिया के यूनान को चले जाने को औपचारिक रूप से मान्य किया और क्रीट पर ऑटोमन अधिकार त्याग दिए गए। यूनान में रह गए मुसलमानों के धर्म और संपत्ति अधिकार, वक़्फ़ों की स्थिति और मुफ़्तियों की नियुक्ति का विस्तार से नियमन किया गया। एजियन द्वीपों की स्थिति अनसुलझी छोड़ी गई और दोनों राज्यों के बीच निरंतर तनाव का स्रोत बनी रही।", "a5ae7115"]},
"OLAYLAR_EK5:1914-08-02:0":{"b": ["इस्तांबुल में ऑटोमन-जर्मन गुप्त गठबंधन संधि पर हस्ताक्षर", "0472efb3"], "d": ["यूरोप में युद्ध भड़कते ही वज़ीर-ए आज़म सईद हलीम पाशा के कोनाक में ऑटोमन राज्य और जर्मनी के बीच गुप्त गठबंधन संधि हस्ताक्षरित हुई; पाठ में रूस के जर्मनी के विरुद्ध युद्ध में उतरने पर ऑटोमन के भी जर्मनी के पक्ष में रहने का प्रावधान था। संधि मंत्रिमंडल से भी छिपाई गई, केवल चार लोगों को ज्ञात थी। तीन माह बाद काला सागर आक्रमण से ऑटोमन राज्य वस्तुतः युद्ध में घसीटा जाएगा, साम्राज्य का भाग्य इस दस्तावेज़ से बँध जाएगा।", "063ef809"]},
"OLAYLAR_EK5:1914-09-09:0":{"b": ["कैपिट्यूलेशनों का एकतरफ़ा समाप्त किया जाना", "ec773d18"], "d": ["ऑटोमन सरकार ने यूरोप के युद्ध में व्यस्त होने के क्षण में विदेशियों को न्यायिक, वित्तीय और सीमा-शुल्क विशेषाधिकार देने वाली कैपिट्यूलेशनों को 1 अक्तूबर 1914 से एकतरफ़ा समाप्त करने की घोषणा की। चार शताब्दी की इस विशेषाधिकार व्यवस्था के समाप्त किए जाने का देश में बड़े स्वतंत्रता उत्साह से स्वागत हुआ और इस्तांबुल में समारोह हुए। मित्र जर्मनी सहित सभी राज्यों ने निर्णय का विरोध किया; कैपिट्यूलेशन केवल 1923 में लोज़ान में निश्चित रूप से इतिहास बनेंगी।", "b30c11aa"]},
"OLAYLAR_EK5:1914-10-29:0":{"b": ["काला सागर आक्रमण: ऑटोमन बेड़े का रूसी बंदरगाहों पर बमबारी करना", "8ad4ef61"], "d": ["जर्मनी से भागकर ऑटोमन बेड़े में 'ख़रीदे हुए' के रूप में सम्मिलित हुए गोएबेन और ब्रेस्लाउ (यावुज़ और मिदिल्ली) ने एडमिरल सूशों की कमान में काला सागर में उतरकर रूसी बंदरगाहों पर तोप दागी और जहाज़ डुबोए। एनवर पाशा के मंत्रिमंडल से छिपाकर दिए इस आदेश ने तटस्थता को वस्तुतः समाप्त कर दिया। एक सप्ताह में रूस, इंग्लैंड और फ़्रांस ने युद्ध घोषित किया और ऑटोमन राज्य अपरिवर्तनीय रूप से प्रथम विश्व युद्ध में उतर गया।", "bdd1c93a"]},
"OLAYLAR_EK5:1914-11-06:0":{"b": ["अंग्रेज़-भारतीय सेनाओं का फ़ाव पर क़ब्ज़ा — इराक़ मोर्चे का खुलना", "08663813"], "d": ["मित्र राष्ट्रों के ऑटोमन राज्य पर युद्ध घोषित करने के अगले दिन की सुबह, बहरीन में प्रतीक्षारत अंग्रेज़-भारतीय ब्रिगेड शत्तुल-अरब के मुहाने के फ़ाव में उतरी। जर्जर फ़ाव दुर्ग की छोटी ऑटोमन टुकड़ी युद्धपोतों की गोलाबारी में हट गई और भारत तार-लाइन का स्टेशन अंग्रेज़ों के हाथ आ गया। इराक़ मोर्चा इस तरह खुल गया।", "7da97cb0"]},
"OLAYLAR_EK5:1914-11-14:0":{"b": ["जिहाद-ए अकबर की घोषणा: फ़ातिह मस्जिद में जिहाद फ़तवे का पढ़ा जाना", "2a6174e8"], "d": ["शेख़ुल-इस्लाम उर्गुपलू हैरी एफ़ेंदी के दिए पाँच फ़तवे ख़लीफ़ा-पदीशाह के नाम से फ़ातिह मस्जिद में पढ़े गए और सभी मुसलमानों को मित्र राज्यों के विरुद्ध जिहाद के लिए पुकारा गया। यह चाल, जिससे जर्मनी ने बड़ी आशा बाँधी थी, अंग्रेज़ और फ़्रांसीसी उपनिवेशों के मुसलमानों को विद्रोह के लिए उठाना चाहती थी। अपेक्षित सामान्य उभार नहीं हुआ; इसके उलट दो वर्ष बाद मक्का अमीर शरीफ़ हुसैन का अंग्रेज़ समर्थन से विद्रोह करना ख़िलाफ़त के राजनीतिक प्रभाव की सीमाएँ कड़वाहट से दिखा गया।", "e5a86763"]},
"OLAYLAR_EK5:1914-12-09:0":{"b": ["क़ूर्ने का अंग्रेज़ों के सामने समर्पण", "621d36b0"], "d": ["बसरा के पतन के बाद दजला और फ़रात के संगम के क़ूर्ने में हटे बसरा वाली सुब्ही बेय की सेनाओं ने 4-8 दिसंबर की लड़ाइयों के बाद 9 दिसंबर 1914 की सुबह समर्पण किया।", "ff45626a"]},
"OLAYLAR_EK5:1914-12-22:0":{"b": ["सारिकामिश अभियान: कॉकेशस मोर्चे पर विपत्ति", "5cbde7f0"], "d": ["एनवर पाशा ने 1878 में खोए कार्स-अर्दाहान-बातुम को वापस लेने और कॉकेशस के तुर्कों को विद्रोह के लिए उठाने के उद्देश्य से तृतीय सेना को सर्दी में अल्लाहुअकबर पर्वतों के ऊपर से रूसी सेनाओं को घेरने वाली चाल पर हाँका। अपर्याप्त शीतकालीन उपकरण, ख़त्म होती रसद और शून्य से तीस डिग्री नीचे तक पहुँचने वाले तूफ़ान के कारण सेना युद्ध में उतरने से पहले ही घुल गई; हज़ारों सैनिक ठिठुरकर मरे। अभियान ऑटोमन की युद्ध की सबसे भारी विपत्तियों में से एक रहा और पूर्वी मोर्चे को दो वर्ष असुरक्षित छोड़ गया।", "f5289317"]},
"OLAYLAR_EK5:1915-01-14:0":{"b": ["पहला नहर अभियान: स्वेज़ पर सीना रेगिस्तान के पार आक्रमण", "02dd72f5"], "d": ["चतुर्थ सेना कमांडर जेमाल पाशा ने मिस्र को अंग्रेज़ क़ब्ज़े से छुड़ाने और स्वेज़ नहर को आवागमन के लिए बंद करने के उद्देश्य से सीना रेगिस्तान पार करके आक्रमण किया। ऑटोमन टुकड़ियाँ नहर के पूर्वी तट तक पहुँचीं और कुछ पार जाने में सफल रहीं तो भी अंग्रेज़ श्रेष्ठता और अपेक्षित मिस्री जन-विद्रोह के न होने पर पीछे हट गईं। अभियान लक्ष्य तक न पहुँचा, किंतु इंग्लैंड को मिस्र में बड़ी सेना रखने को विवश करके परोक्ष रणनीतिक प्रभाव डाला।", "d9d0152c"]},
"OLAYLAR_EK5:1915-05-27:0":{"b": ["सेव्क वे इस्कान (तेह्चीर) क़ानून का पारित किया जाना", "2f2bc22c"], "d": ["वान विद्रोह और रूसी प्रगति के बाद सरकार ने मोर्चे के पीछे सुरक्षा बिगाड़ने वाली मानी गई जनसंख्या को सेना कमांडरों द्वारा अन्य क्षेत्रों में स्थानांतरित करने की अनुमति देने वाला अस्थायी क़ानून पारित किया और पदीशाह ने 27 मई 1915 को पुष्ट किया। क्रियान्वयन से अनातोलिया के पूर्वी और दक्षिणी विलायतों की आर्मेनियाई जनसंख्या का बड़ा भाग सीरिया और मूसल की ओर भेजा गया; स्थानांतरण के दौरान बीमारी, भूख और हमलों के कारण बहुत बड़ी जनहानि हुई। निर्णय ऑटोमन के अंतिम वर्षों का सबसे भारी और आज भी सबसे विवादित मसला बना हुआ है।", "e8af8dee"]},
"OLAYLAR_EK5:1916-08-07:0":{"b": ["ऑटोमन टुकड़ियों ने मुश को रूसी क़ब्ज़े से वापस लिया", "fb1be113"], "d": ["मुश के पहले रूसी क़ब्ज़े के छह माह बाद ऑटोमन 16वीं कोर ने बिदलिस-मुश जवाबी आक्रमण में क़स्बे में प्रवेश किया।", "c235eed5"]},
"OLAYLAR_EK5:1916-08-25:0":{"b": ["मुश फिर रूसियों के हाथ गया", "43ad8a03"], "d": ["रूसी जवाबी आक्रमण पर ऑटोमन टुकड़ी ने मुश ख़ाली किया; क़स्बा 22-25 अगस्त 1916 के बीच फिर रूसी क़ब्ज़े में गया और 1917 के वसंत तक हाथ में रहा।", "db39e054"]},
"OLAYLAR_EK5:1917-05-01:0":{"b": ["मुश रूसी क़ब्ज़े से निश्चित रूप से मुक्त हुआ", "f0e89703"], "d": ["प्रथम विश्व युद्ध में रूसी क़ब्ज़े में गया मुश, 1 मई 1917 को ऑटोमन सेनाओं द्वारा निश्चित रूप से वापस ले लिया गया।", "f2406306"]},
"OLAYLAR_EK5:1918-02-10:0":{"b": ["अब्दुलहमीद द्वितीय का बेयलरबेयी सराय में निधन", "c9662582"], "d": ["1909 में गद्दी से उतारे जाकर पहले सलोनिका, बाल्कन युद्ध में नगर की हानि पर इस्तांबुल लाए गए और बेयलरबेयी सराय में नज़रबंद रखे गए अब्दुलहमीद द्वितीय चल बसे। उन्होंने तैंतीस वर्ष के शासन में राज्य को युद्धों से दूर रखकर समय पाने का प्रयास किया था, किंतु वे अपने इस्तिबदाद शासन के लिए भी याद किए जाते थे। जनाज़ा बड़ी भीड़ के साथ दीवान योलू के महमूद प्रथम मक़बरे में दफ़नाया गया; उनकी मृत्यु ऐसे युद्ध-वर्ष में हुई जब उनकी स्थापित व्यवस्था का कब का सफ़ाया हो चुका था।", "241489b4"]},
"OLAYLAR_EK5:1918-03-03:0":{"b": ["ब्रेस्ट-लितोव्स्क संधि: कार्स, अर्दाहान और बातूम की वापसी", "da82636f"], "d": ["बोल्शेविक क्रांति के बाद युद्ध से हटे रूस और केंद्रीय शक्तियों के बीच हुई संधि ने पूर्वी मोर्चा बंद कर दिया और उस्मानी राज्य को कार्स, अर्दाहान और बातूम (एल्विये-ए-सेलासे, तीन संजाक) लौटा दिए, जिन्हें उसने 1878 की बर्लिन संधि में खोया था। किंतु मुद्रोस युद्धविराम के बाद यह क्षेत्र फिर हाथ से निकल गया और अंतिम समाधान 1921 की कार्स संधि से आया।", "b321b56d"]},
"OLAYLAR_EK5:1918-03-28:0":{"b": ["ऑटोमन टुकड़ियाँ आर्त्विन में दाख़िल हुईं", "ca7d1778"], "d": ["25 मार्च को 1914 की सीमा पार करने वाली ऑटोमन टुकड़ियाँ, ब्रेस्ट-लितोव्स्क के 1878 से पहले की सीमा लौटाने पर एलविये-ए सलासे की ओर बढ़ीं और 28 मार्च 1918 को आर्त्विन में दाख़िल हुईं। आर्त्विन बातुम संजक के अंग के रूप में 1878 में रूस को छोड़ा गया था; TDV का आर्त्विन मद वापसी को केवल 'मार्च 1918' लिखता है, दिन मुस्तफ़ा सारी देता है।", "7c7f5573"]},
"OLAYLAR_EK5:1918-04-03:0":{"b": ["अर्दाहान तुर्क सेना के हाथ आया", "7fd9e3db"], "d": ["एलविये-ए सलासे अभियान में ऑटोमन सेना ने आर्त्विन के बाद अर्दाहान को 3 अप्रैल 1918 को लिया; अर्दाहान तिरानवे युद्ध में 1877 में गिरा था और 1878 में रूस को छोड़ा गया था। कार्स एक माह बाद, 25 अप्रैल को, लिया जाएगा।", "76d4ba84"]},
"OLAYLAR_EK5:1918-04-14:0":{"b": ["बातूम की वापसी", "d37a1a0d"], "d": ["ब्रेस्ट-लितोव्स्क संधि से रूस के युद्ध से हटने पर पूर्व की ओर बढ़ती उस्मानी सेना ने 1878 में खोया बातूम बंदरगाह चालीस वर्ष बाद वापस ले लिया। काला सागर के पूर्वी सिरे का यह बंदरगाह बाकू के तेल का समुद्री निकास था। यह उपलब्धि लगभग आठ महीने रही; मुद्रोस युद्धविराम के बाद क्षेत्र ख़ाली किया जाना था।", "fa25e090"]},
"OLAYLAR_EK5:1918-04-25:0":{"b": ["एलविये-ए सलासे: कार्स ऑटोमन प्रशासन में आया", "02cbf0b3"], "d": ["ब्रेस्ट-लितोव्स्क में 1878 की बर्लिन संधि से खोए तीन संजकों — कार्स, अर्दाहान और बातुम — की वापसी तय हुई थी; ऑटोमन सेना अर्दाहान में 3 अप्रैल, बातुम में 14 अप्रैल, कार्स में 25 अप्रैल 1918 को दाख़िल हुई और प्रशासन वस्तुतः स्थापित हुआ। 'एलविये-ए सलासे' नाम से जानी जाने वाली ये भूमियाँ तिरानवे युद्ध से चली आ रही हानि की क्षतिपूर्ति मानी गईं। युद्धविराम के बाद फिर हाथ से निकलेंगी, निश्चित रूप से केवल 1921 की कार्स संधि से तुर्की से जुड़ेंगी।", "83a69417"]},
"OLAYLAR_EK5:1918-05-20:0":{"b": ["इग़दिर क़ब्ज़े में लिया गया — अरस घाटी में प्रगति", "87ebf4d3"], "d": ["फ़रवरी 1918 में आरंभ आगे बढ़ने के अभियान के दायरे में तुर्क टुकड़ियों ने अरस के उत्तर के सेरदाराबाद में आर्मेनियाई टुकड़ियों को हराया और इग़दिर को 20 मई 1918 को अपने क़ब्ज़े में लिया। इग़दिर एलविये-ए सलासे में सम्मिलित नहीं था, येरेवान गुबेर्निया का सुरमेली क़ज़ा था; लगभग 180 वर्ष बाद क्षेत्र में पहला ऑटोमन प्रशासन स्थापित हुआ।", "f50c4b56"]},
"OLAYLAR_EK5:1918-07-03:0":{"b": ["मेहमेद पंचम रेशाद का निधन और मेहमेद षष्ठ वहीदुद्दीन का राज्यारोहण", "d302ba07"], "d": ["नौ वर्ष का शासन त्रिपोलीतानिया, बाल्कन और विश्व युद्धों में बीतने वाले मेहमेद पंचम रेशाद युद्ध के सबसे नाज़ुक दौर में चल बसे और उनकी जगह भाई वहीदुद्दीन मेहमेद षष्ठ नाम से गद्दी पर बैठे। नए पदीशाह ने इत्तिहादी कैडर की संरक्षकता से मुक्त होने का प्रयास किया; चार माह बाद युद्धविराम हस्ताक्षरित होने पर साम्राज्य के विघटन का संचालन करने को विवश होंगे। वे ऑटोमन राजवंश के छत्तीसवें और अंतिम पदीशाह थे।", "2d9306b3"]},
"OLAYLAR_EK5:1918-11-13:0":{"b": ["मित्र राष्ट्र बेड़े का इस्तांबुल के सामने आना और नगर का वास्तविक क़ब्ज़ा", "d10cb14d"], "d": ["मूद्रोस युद्धविराम के बाद अंग्रेज़, फ़्रांसीसी, इतालवी और यूनानी जहाज़ों के साठ से अधिक नौकाओं वाले मित्र राष्ट्र बेड़े ने दोलमाबाहचे के सामने लंगर डाला और इस्तांबुल वस्तुतः क़ब्ज़े में आ गया। चार सौ पैंसठ वर्ष बाद राजधानी पहली बार विदेशी सैनिकों के नियंत्रण में गई थी। कहा जाता है कि उसी दिन हैदरपाशा उतरकर यह दृश्य देखने पर मुस्तफ़ा केमाल पाशा ने 'जैसे आए वैसे ही चले जाएँगे' कहा था; यह वाक्य राष्ट्रीय संघर्ष के प्रतीक वाक्यों में से एक बनने वाला था।", "30db4974"]},
"OLAYLAR_EK5:1918-12-04:0":{"b": ["अरस क्षेत्र से पीछे हटना: इग़दिर ख़ाली किया गया", "57572ab4"], "d": ["मूद्रोस युद्धविराम के 1914 सीमा के पीछे हटने के प्रावधान के अनुसार याक़ूब शेव्की पाशा ने 21 नवंबर के आदेश से ब्रेस्ट-लितोव्स्क सीमा के बाहर की टुकड़ियों के 4 दिसंबर तक वापस लिए जाने का आदेश दिया; इग़दिर और आसपास इस तिथि को पूरी तरह ख़ाली किया गया। इसके बाद अरस-तुर्क हुकूमत दिसंबर 1918 के अंत में आर्मेनियाइयों द्वारा गिरा दी गई।", "68b8ff9a"]},
"OLAYLAR_EK5:1918-12-17:0":{"b": ["अंग्रेज़ आर्त्विन में बसे", "e2cb3153"], "d": ["30 अक्तूबर 1918 के मूद्रोस युद्धविराम ने ऑटोमन सेना के 1914 सीमा के पीछे हटने की शर्त रखी थी, इसलिए आर्त्विन ख़ाली किया गया और 17 दिसंबर 1918 को अंग्रेज़ों ने क़ब्ज़ा किया। TDV के आर्त्विन मद के अनुसार अंग्रेज़ क़ब्ज़ा 1920 के अप्रैल तक चला।", "5b9a237d"]},
"OLAYLAR_EK5:1918-12-24:0":{"b": ["मूद्रोस के बाद बातुम में ब्रिटिश प्रशासन", "9dd768fc"], "d": ["30 अक्तूबर 1918 के मूद्रोस युद्धविराम के अनुसार ऑटोमन राज्य को बातुम से हटना पड़ा; नगर 24 दिसंबर 1918 को ब्रिटिश टुकड़ियों ने थामा। अप्रैल 1918 में स्वतंत्र संजक का केंद्र बनाया गया बातुम इस तिथि से जुलाई 1920 तक अंग्रेज़ नियंत्रण में रहा।", "d172259b"]},
"OLAYLAR_EK5:1919-04-20:0":{"b": ["अर्दाहान जॉर्जियाई आधिपत्य में गया", "97cf47f6"], "d": ["मूद्रोस के बाद ख़ाली किए अर्दाहान पर, दक्षिण-पश्चिमी कॉकेशस हुकूमत के अंग्रेज़ों द्वारा भंग किए जाने के दिनों में, जॉर्जियाई सेनाओं ने 20 अप्रैल 1919 को क़ब्ज़ा किया। जॉर्जियाई आधिपत्य 23 फ़रवरी 1921 तक चलने वाला था।", "6027a645"]},
"OLAYLAR_EK5:1919-04-30:0":{"b": ["प्रेस्टन ने कार्स का प्रशासन आर्मेनियाई वाली को सौंपा", "efa81cb0"], "d": ["12-13 अप्रैल 1919 को दक्षिण-पश्चिमी कॉकेशस हुकूमत को भंग करने वाले अंग्रेज़ कमांडर प्रेस्टन ने अस्थायी शूरा हुकूमत को 30 अप्रैल 1919 को समाप्त करके नगर का प्रशासन कार्स वाली बनाए गए आर्मेनियाई कारगानोफ़ को सौंप दिया; कार्स में आर्मेनियाई प्रशासन का दौर आरंभ हुआ और काज़िम काराबेकिर की 30 अक्तूबर 1920 की विजय तक चला।", "ffa3989a"]},
"OLAYLAR_EK5:1919-07-23:0":{"b": ["एरज़ुरुम कांग्रेस: पूर्वी विलायतों का राष्ट्रीय प्रतिरोध निर्णय", "41ef0457"], "d": ["शर्क़ी अनातोलिया मुदाफ़ा-ए हुक़ूक़ जमाअत द्वारा जुटाई कांग्रेस, अंग्रेज़ दबाव से टलने के बाद छप्पन प्रतिनिधियों के साथ खुली और अध्यक्षता सेना सेवा से त्यागपत्र दे चुके मुस्तफ़ा केमाल पाशा को मिली। कांग्रेस ने घोषणा की कि राष्ट्रीय सीमाओं के भीतर मातृभूमि एक संपूर्ण है, मैंडेट और संरक्षण स्वीकार्य नहीं हैं और सरकार के बिखरने की स्थिति में राष्ट्र अपना भाग्य अपने हाथ में लेगा। ये निर्णय छह माह बाद मीसाक़-ए मिल्ली पाठ का केंद्रक बनने वाले थे।", "925ca450"]},
"OLAYLAR_EK5:1919-09-04:0":{"b": ["सिवास कांग्रेस: राष्ट्रीय प्रतिरोध का एक छत्र के नीचे एकजुट होना", "0e9ad36b"], "d": ["4 सितंबर 1919 को सिवास सुल्तानी में कार्य आरंभ करने वाली कांग्रेस ने देश के चारों कोनों की मुदाफ़ा-ए हुक़ूक़ जमाअतों को अनातोलिया और रुमेली मुदाफ़ा-ए हुक़ूक़ जमाअत नाम से जोड़ा और प्रतिनिधि समिति (हेयेत-ए तमसीलिये) चुनी। अमेरिकी मैंडेट का प्रस्ताव लंबी बहस के बाद अस्वीकार हुआ। 11 सितंबर को प्रकाशित घोषणापत्र से राष्ट्रीय संघर्ष एक-केंद्रीय, वैध राजनीतिक आंदोलन बन गया और इस्तांबुल सरकार से खुला शक्ति-संघर्ष आरंभ हुआ।", "9e4ba0a0"]},
"OLAYLAR_EK5:1919-10-22:0":{"b": ["आमासिया प्रोटोकॉल: इस्तांबुल सरकार और प्रतिनिधि समिति की वार्ता", "40e6a6ab"], "d": ["दामाद फ़रीद के गिरने और अली रिज़ा पाशा सरकार के बनने के बाद नौसेना मंत्री सालिह पाशा प्रतिनिधि समिति से मिलने आमासिया भेजे गए। हुए प्रोटोकॉलों से इस्तांबुल सरकार ने अनातोलिया आंदोलन के अस्तित्व को वस्तुतः मान्यता दी; मजलिस-ए मेबऊसान के जुटने, चुनावों के स्वतंत्र होने और राष्ट्रीय सीमाओं की रक्षा पर सहमति बनी। यह राष्ट्रीय संघर्ष की इस्तांबुल के सामने पाई पहली औपचारिक राजनीतिक उपलब्धि है।", "721d202a"]},
"OLAYLAR_EK5:1920-01-28:0":{"b": ["मीसाक़-ए मिल्ली का अंतिम ऑटोमन सभा में स्वीकार", "6322865e"], "d": ["अंतिम ऑटोमन मजलिस-ए मेबऊसान में 121 मेबऊसों के हस्ताक्षर वाले अहद-ए मिल्ली पाठ ने मूद्रोस रेखा के भीतर रह गई और मुस्लिम-तुर्क बहुसंख्या वाली भूमि की अविभाज्य अखंडता, अरब विलायतों और पश्चिमी थ्रेस में जनमत-संग्रह, कैपिट्यूलेशनों के समापन और पूर्ण राजनीतिक-वित्तीय स्वतंत्रता की शर्त रखी। पाठ 17 फ़रवरी 1920 को सर्वसम्मति से स्वीकृत करके विश्व को घोषित किया गया। यह घोषणापत्र राष्ट्रीय संघर्ष का राजनीतिक कार्यक्रम होने के साथ लोज़ान में बचाई जाने वाली सीमाओं का मानचित्र भी था; मित्र राष्ट्रों के 16 मार्च को इस्तांबुल पर औपचारिक क़ब्ज़े का सीधा कारण बना।", "576d2af5"]},
"OLAYLAR_EK5:1920-04-01:0":{"b": ["अंग्रेज़ों के हटते समय आर्त्विन जॉर्जिया में रहा", "6d086b06"], "d": ["TDV के आर्त्विन मद के अनुसार अंग्रेज़ क़ब्ज़ा 1920 वर्ष के अप्रैल माह तक चला; अंग्रेज़ों ने हटते समय नगर जॉर्जिया को छोड़ दिया। आर्त्विन जॉर्जिया के हाथ में टीबीएमएम के 23 फ़रवरी 1921 के अल्टीमेटम तक रहा।", "20ff63b0"]},
"OLAYLAR_EK5:1920-07-07:0":{"b": ["बातुम जॉर्जियाई प्रशासन को सौंपा गया", "6523d095"], "d": ["अंग्रेज़ों का बातुम को औपचारिक रूप से जॉर्जियाइयों को सौंपना 7 जुलाई 1920 को हुआ (TDV का बातुम मद केवल 'जुलाई 1920' कहता है)। अंकारा सरकार ने 25 जुलाई को इस हस्तांतरण का 'क़ब्ज़ा' कहकर विरोध किया।", "99c9bfc8"]},
"OLAYLAR_EK5:1920-12-03:0":{"b": ["ग्युमरू संधि: टीबीएमएम सरकार की पहली अंतरराष्ट्रीय संधि", "9232c690"], "d": ["काज़िम काराबेकिर की कमान की पूर्वी मोर्चा सेना के सारिकामिश और कार्स वापस लेने पर आर्मेनिया ने शांति माँगी और ग्युमरू में हस्ताक्षरित संधि से सेव्र को न मानने और पूर्व में भूमि माँगें छोड़ने को स्वीकार किया। अंकारा सरकार की हस्ताक्षरित यह पहली संधि, सेव्र को वस्तुतः अस्वीकार करने वाला पहला अंतरराष्ट्रीय दस्तावेज़ बनी और टीबीएमएम के लिए विधिक मान्यता का मार्ग खोला। इस तरह पूर्वी सीमा के सुरक्षित होने से पश्चिमी मोर्चे पर बल भेजना संभव हो गया।", "c41c725d"]},
"OLAYLAR_EK5:1921-01-10:0":{"b": ["पहली इनोनू लड़ाई: नियमित सेना की पहली विजय", "4add3719"], "d": ["नई बनी नियमित सेना ने बुर्सा दिशा से बढ़ती यूनानी सेनाओं को इनोनू मोर्चों पर रोककर पीछे हटने को विवश किया। सैन्य दृष्टि से सीमित पैमाने की इस सफलता के राजनीतिक परिणाम बहुत बड़े थे: अंकारा सरकार को लंदन सम्मेलन में आमंत्रित किया गया, सोवियत रूस से मॉस्को संधि का मार्ग खुला और तेशकिलात-ए असासिये क़ानून स्वीकार हुआ। आंतरिक जनमत में नियमित सेना के प्रति भरोसा भी इस विजय से पक्का हुआ।", "13509273"]},
"OLAYLAR_EK5:1921-04-01:0":{"b": ["दूसरी इनोनू लड़ाई: यूनानी आक्रमण का दूसरी बार टूटना", "a974521c"], "d": ["लंदन सम्मेलन से परिणाम न पा सकी यूनानी सेना बुर्सा और उशाक दिशाओं से नए आक्रमण पर निकली, किंतु फिर इनोनू की चोटियों पर रोकी गई और पीछे हटने को विवश हुई। मुस्तफ़ा केमाल पाशा का इस्मत पाशा को भेजा 'आपने वहाँ केवल शत्रु को नहीं, राष्ट्र के अशुभ भाग्य को भी हराया' तार इस विजय के बाद लिखा गया। युद्ध ने राष्ट्रीय संघर्ष की अंतरराष्ट्रीय प्रतिष्ठा बढ़ाई और इटली के अनातोलिया से हटने की प्रक्रिया को तेज़ किया।", "639e964d"]},
"OLAYLAR_EK5:1921-10-20:0":{"b": ["अंकारा समझौता: फ़्रांस से शांति और दक्षिणी मोर्चे का बंद होना", "35fc32db"], "d": ["सकारया विजय के बाद फ़्रांस से अंकारा में हस्ताक्षरित समझौते से दक्षिणी मोर्चे का युद्ध समाप्त हुआ; फ़्रांसीसी सेनाओं ने अदाना, अंतेप, मराश और उरफ़ा सहित चुकुरोवा और दक्षिण-पूर्व को ख़ाली करके सीरिया सीमा पर हटना स्वीकार किया। मित्र राष्ट्रों में से एक ने इस तरह अंकारा सरकार को वस्तुतः मान्यता दी और सेव्र मोर्चे में पहली दरार पड़ी। ख़ाली किए क्षेत्रों से लिए हथियार और मुक्त हुई टुकड़ियाँ महान आक्रमण की तैयारी में निर्णायक भूमिका में रहीं।", "7e088769"]},
"OLAYLAR_EK5:1922-10-11:0":{"b": ["मूदान्या युद्धविराम: इस्तांबुल और जलडमरूमध्य का बिना युद्ध हस्तांतरण", "ac0d9baf"], "d": ["महान आक्रमण के बाद तुर्क सेना के चानाक्काले और इज़मित में अंग्रेज़ सेनाओं के आमने-सामने आने पर मूदान्या में जुटा सम्मेलन ग्यारह दिन की कठिन सौदेबाज़ी के बाद युद्धविराम में परिणत हुआ। पूर्वी थ्रेस के मेरिच तक पंद्रह दिन में यूनान द्वारा ख़ाली करके तुर्क प्रशासन को सौंपे जाने और इस्तांबुल तथा जलडमरूमध्य के शांति संधि से सौंपे जाने पर सहमति बनी। इस तरह राष्ट्रीय संघर्ष का सशस्त्र चरण एक भी गोली चले बिना जीती कूटनीतिक विजय से बंद हुआ और लोज़ान का द्वार खुला।", "79b94dfb"]},
"OLAYLAR_EK5:1922-11-17:0":{"b": ["मेहमेद षष्ठ वहीदुद्दीन का इस्तांबुल से प्रस्थान और अब्दुलमजीद एफ़ेंदी का ख़लीफ़ा चुना जाना", "8ab0e847"], "d": ["सल्तनत के समाप्त किए जाने के बाद जिनकी स्थिति विवादित हो गई थी उन अंतिम पदीशाह मेहमेद षष्ठ वहीदुद्दीन ने 17 नवंबर 1922 शुक्रवार की सुबह अंग्रेज़ युद्धपोत मलाया से इस्तांबुल छोड़कर माल्टा की राह ली। टीबीएमएम ने दो दिन बाद, 19 नवंबर को, अब्दुलमजीद एफ़ेंदी को बिना राजनीतिक अधिकार वाले ख़लीफ़ा के रूप में चुना। छह सौ तेईस वर्ष का ऑटोमन राजवंशीय शासन इस तरह वस्तुतः समाप्त हुआ; ख़िलाफ़त पंद्रह माह और प्रतीकात्मक रूप से चली। माल्टा और फिर इटली गए वहीदुद्दीन सान रेमो की विला नोबेल में बसे; किसी मुस्लिम देश में स्वीकार किए जाने के आवेदनों से परिणाम न पा सके और 16 मई 1926 को वहीं, सल्तनत और ख़िलाफ़त के अधिकारों से कभी त्यागपत्र न देने की बात दोहराते हुए चल बसे।", "86831a04"]},
"OLAYLAR_EK5:1926-05-16:0":{"b": ["अंतिम पदीशाह मेहमेद षष्ठ वहीदुद्दीन का सान रेमो में निधन", "7149ed0e"], "d": ["इस्तांबुल से जाने के बाद इटली के सान रेमो नगर में बसे अंतिम ऑटोमन पदीशाह मेहमेद वहीदुद्दीन 16 मई 1926 को उस ख़िलाफ़त कांग्रेस (13 मई 1926) के जुटने की ख़बर पाए बिना चल बसे, जिसे उन्होंने सूचित किया था कि उन्होंने सल्तनत और ख़िलाफ़त के अधिकार कभी नहीं त्यागे। वे भारी आर्थिक तंगी में थे; सान रेमो के व्यापारियों का 60.000 लीरा क़र्ज़ था और उनकी मृत्यु सुनकर लेनदारों ने घर के सामान पर कुर्क़ी लगवाई।", "0864312a"]},
"OLAYLAR_EK6:1325-01-01:0":{"b": ["कोनुरआल्प की बोलु क्षेत्र विजय — मुदुर्नू, कोनुरापा और बोलु", "e245cd27"], "d": ["ओरहान ग़ाज़ी के सेनानायकों में से कोनुरआल्प ने सकारिया के पूर्व के पर्वतीय क्षेत्र की ओर बढ़कर मुदुर्नू, कोनुरापा और बोलु क्षेत्र को ऑटोमन प्रशासन से जोड़ा; दुज़जे मैदान का क़स्बा उनके नाम से जाना गया। विजय की सटीक तिथि अज्ञात है; वृत्तांत आशिक़पाशाज़ादे की रिवायत पर आधारित है। क्षेत्र उस समय चंदारओग़्लुओं और बीज़ान्टिन के बीच हाथ बदलता सीमांत क्षेत्र था; विजय ने ऑटोमन को पहली बार काला सागर के पश्चिमी तट के निकट पहुँचाया। अंकारा युद्ध के बाद क्षेत्र फिर चंदारओग़्लुओं के पास जाएगा, किंतु फ़ातिह काल में निश्चित रूप से वापस लिया जाएगा।", "d7b58190"]},
"OLAYLAR_EK6:1334-01-01:0":{"b": ["मरमरा के दक्षिण के बीज़ान्टिन क़स्बों का लिया जाना — मिहालिच, किरमास्ती, गोलयाज़ी", "9c61b8d4"], "d": ["इज़निक और इज़मित पर अधिकार के बाद बुर्सा मैदान के पश्चिम में बीज़ान्टिन के हाथ बचे क़स्बे एक-एक करके ऑटोमन प्रशासन में आए। उलुअबात झील के आसपास का गोलयाज़ी, सुसुरलुक नदी किनारे के किरमास्ती और मिहालिच ने मरमरा के दक्षिणी तट को कारेसी भूमि से जोड़ने वाला गलियारा पूर्ण किया। ये क़स्बे लंबे समय बिना घेराबंदी देखे, आसपास के कट जाने से समर्पित हुए; क्षेत्र में बीज़ान्टिन उपस्थिति इस तरह गेमलिक खाड़ी में सिमट गई।", "bd729343"]},
"OLAYLAR_EK6:1395-01-01:0":{"b": ["गोर्दुस (कोरिंथ) मोरिया डेस्पोटेट को गया", "392495eb"], "d": ["1358 से फ़्लोरेंस के अच्चायुओली परिवार की अख़ाया रियासत से जुड़ा तिमार रहा कोरिंथ, 1395 में बीज़ान्टिन के मोरिया डेस्पोट थेओदोरोस के हाथ आया। नगर इसके बाद ऑटोमन विजय तक डेस्पोटेट के प्रशासन में रहा।", "1803a03a"]},
"OLAYLAR_EK6:1427-06-01:0":{"b": ["हाजीएमीरओग़्लु बेयलिक का विलय — ओर्दू और ऊन्ये", "c064f07f"], "d": ["बयराम बेय द्वारा ओर्दू के आसपास स्थापित और 1350 के दशक में पुत्र हाजी एमीर द्वारा बढ़ाया गया तुर्कमान बेयलिक, जिसका केंद्र आज के एस्कीपज़ार में था, एक छोटा पर रणनीतिक तटीय राज्य था: वह सामसुन और ट्रेबिज़ोंड के बीच का एकमात्र स्वतंत्र आधिपत्य क्षेत्र था। अमीर सुलेमान ने 1398 में यिल्दिरिम बायज़ीद के जानिक अभियान में निष्ठा जताई थी, अंकारा युद्ध के बाद बेयलिक फिर स्वतंत्र हो गया था। मुराद द्वितीय काल में, ताजुद्दीनओग़्लुओं के सफ़ाए के उन्हीं वर्षों में, बेयलिक की भूमि सीधे ऑटोमन प्रशासन से जोड़ी गई और काला सागर तट सामसुन से गिरेसुन तक एक हाथ में एकीकृत हुआ।", "d5caa358"]},
"OLAYLAR_EK6:1458-08-06:0":{"b": ["गोर्दुस (कोरिंथ) की विजय", "87a2bc59"], "d": ["फ़ातिह के मोरिया अभियान में अक्रोकोरिंथ दुर्ग तीन माह घेरा गया और अंत में शांति के रास्ते लिया गया। मोरिया का द्वार माना जाने वाला कोरिंथ स्थलडमरूमध्य इस तरह ऑटोमन को गया।", "b2be3a05"]},
"OLAYLAR_EK6:1499-01-01:0":{"b": ["मोंटेनेग्रो का ऑटोमन प्रशासन से जुड़ना — चेतिन्ये", "7fdb7cc8"], "d": ["ज़ेता पर शासन करने वाले त्सर्नोयेविच राजवंश के 1496 में आधिपत्य छोड़ने पर इश्कोदरा के पिछवाड़े जैसा मोंटेनेग्रो का पर्वतीय क्षेत्र सीधे ऑटोमन प्रशासन में ले लिया गया और पहले अलग संजक, फिर इश्कोदरा संजक के भाग के रूप में संगठित किया गया। चेतिन्ये मठ क्षेत्र के धार्मिक केंद्र के रूप में यथास्थान छोड़ा गया। भूगोल की कठोरता के कारण यहाँ का प्रशासन मैदानों जैसा कसा कभी नहीं चला; दो शताब्दी बाद उसी मठ से जन्मा व्लादिका शासन वास्तविक स्वतंत्रता का केंद्रक बनेगा।", "e8356eb2"]},
"OLAYLAR_EK6:1534-06-23:0":{"b": ["बायज़ीद दुर्ग का इराक़ैन अभियान में ऑटोमन आधिपत्य मानना", "f29e2e17"], "d": ["वज़ीर-ए आज़म इब्राहीम पाशा के इराक़ैन अभियान में बिंगोल के आसपास आने पर क्षेत्र के अनेक कुर्द क़बीलों के साथ वान, तोप्रक्कले, अवनिक और बायज़ीद दुर्ग ऑटोमन आधिपत्य में आने को राज़ी हुए। बायज़ीद 1514 में यावुज़ के अभियान में ऑटोमन से जुड़ा था, किंतु सेना के लौटने पर सफ़वियों ने क्षेत्र वापस ले लिया था।", "14640206"]},
"OLAYLAR_EK6:1535-06-01:0":{"b": ["तबरेज़ का फिर सफ़वियों को जाना — इराक़ैन से वापसी", "80b8b761"], "d": ["इराक़ैन अभियान में सेना तबरेज़ में दाख़िल हुई थी, किंतु वास्तविक लक्ष्य बग़दाद होने के कारण नगर में स्थायी चौकी नहीं छोड़ी गई थी। सर्दी बग़दाद में बिताकर पश्चिम लौटती सेना के समय शाह तहमास्प ख़ाली किए अज़रबैजान में फिर घुसे और तबरेज़ वापस ले लिया। यह ऑटोमन-सफ़वी युद्धों का दोहराया जाने वाला ढर्रा था: तबरेज़ पाँच बार लिया गया, पाँचों में थामा न जा सका; नगर केवल 1585 में दीर्घकालिक ऑटोमन चौकी पाएगा।", "f60ea64f"]},
"OLAYLAR_EK6:1535-09-22:0":{"b": ["वान और एरचिश का तहमास्प के हाथ पड़ना (ऑटोमन रुख़ 1534-35 में समाप्त)", "cb93d561"], "d": ["वान को 1534 में ऑटोमन आधिपत्य में देने वाले क्षेत्र में उलामा पाशा वान दुर्ग में सफ़वी घेराबंदी में डटे; दुर्ग सफ़वियों के हाथ गया, एरचिश को घेरने वाली सफ़वी सेनाएँ ऑटोमन सहायता से पीछे हट चुकी थीं। कानूनी के अहलात पहुँचने (23 सितंबर 1535) तक वान तहमास्प के हाथ में था। वान 1548 तक सफ़वी रहा।", "eb576b34"]},
"OLAYLAR_EK6:1547-01-01:0":{"b": ["बायज़ीद संजक का सफ़वी आधिपत्य में जाना (वान और एरचिश 1535 में पहले ही सफ़वी थे)", "806a2cf1"], "d": ["ऑटोमन-सफ़वी सीमा के मध्य का बायज़ीद संजक फिर ईरान के हाथ गया (Kaya 2017 इसे 'वान और एरचिश के साथ' कहता है; किंतु वान और एरचिश Karataş 2025 और TDV के अनुसार 22 सितंबर 1535 को सफ़वी को लौट चुके थे); इस हाथ बदल में संजक के कुछ स्थान उजड़ गए। संजक 16वीं शताब्दी की अंतिम तिमाही तक दो राज्यों के बीच बार-बार हाथ बदलता रहा।", "24510bd0"]},
"OLAYLAR_EK6:1553-08-01:0":{"b": ["बायज़ीद संजक का नख़चिवान अभियान के दौरान फिर ऑटोमन में जाना", "cf0171fa"], "d": ["कानूनी के तीसरे ईरान (नख़चिवान) अभियान के दौरान बायज़ीद संजक फिर ऑटोमन प्रशासन में लिया गया। 1554 के अभियान में बायज़ीद सेना के लिए महत्वपूर्ण अड्डा बना; संजक 1578 में निश्चित रूप से ऑटोमन संप्रभुता में आया।", "a6c619eb"]},
"OLAYLAR_EK6:1604-06-08:0":{"b": ["येरेवान का शाह अब्बास के हाथ जाना", "34413cf2"], "d": ["जलाली विद्रोहों के अनातोलिया को जकड़ने के वर्षों में पूर्वी मोर्चे के असुरक्षित रह जाने पर, सेना को यूरोपीय पद्धति से पुनर्गठित कर चुके शाह अब्बास ने आक्रमण किया। 1583 में फ़रहाद पाशा द्वारा बनवाया येरेवान दुर्ग सात माह घिरे रहने के बाद समर्पित हुआ। फ़रहाद पाशा संधि से जीती कॉकेशस रेखा की पहली कड़ी टूट चुकी थी, अगले तीन वर्ष में पूरा दक्षिणी कॉकेशस हाथ से निकलने वाला था।", "b5f54d9c"]},
"OLAYLAR_EK6:1606-01-01:0":{"b": ["तिफ़्लिस और गांजा की हानि", "3fb51753"], "d": ["येरेवान के गिरने के बाद सफ़वी सेना कुर घाटी के किनारे बढ़ी; काराबाग़ का केंद्र गांजा और जॉर्जिया की राजधानी तिफ़्लिस एक के बाद एक हाथ से निकलीं। ऑटोमन राज्य उसी समय ऑस्ट्रिया मोर्चे पर तेरह वर्ष चलने वाला लंबा युद्ध लड़ रहा था, अनातोलिया में जलालियों से उलझा था; पूर्व को भेजने लायक़ बल नहीं था। इस तरह 1590 की फ़रहाद पाशा संधि से बनी विशाल कॉकेशस प्रांत व्यवस्था वस्तुतः समाप्त हो गई।", "c80d75b7"]},
"OLAYLAR_EK6:1607-01-01:0":{"b": ["शिरवान की हानि — शमाख़ी, बाकू और देरबेंद", "81beab11"], "d": ["कैस्पियन तट का शिरवान प्रांत, ओज़देमिरोग़्लु उस्मान पाशा के 1578-1585 अभियानों से जीता गया था और रेशम व्यापार के मुख्य स्रोत के रूप में ऑटोमन वित्त को महत्वपूर्ण आय देता था। शाह अब्बास के उत्तर की ओर के अभियान ने शमाख़ी, बाकू और देरबेंद को लगातार लेकर इस प्रांत का सफ़ाया किया। हानि केवल भूमि की नहीं थी: ईरानी रेशम का ऑटोमन के रास्ते यूरोप पहुँचने वाला मार्ग भी नियंत्रण से निकल गया और सफ़वी राज्य ने रेशम को हिंद महासागर के रास्ते बेचना आरंभ किया।", "f85d7f97"]},
"OLAYLAR_EK6:1629-01-01:0":{"b": ["ताइज़ की हानि", "65f20d53"], "d": ["ऑटोमनों ने 1038 (1629) में सनआ की क़ासिमी सत्ता को छोड़े गए यमन आधिपत्य के साथ ताइज़ को भी छोड़ दिया — ज़ैदी इमामों के भीतरी यमन वापस लेने की प्रक्रिया का पहला बड़ा क़दम।", "72344627"]}
});
